// Tata bahasa + terjemahan Indonesia (otomatis via Google Translate).
export default [{"pattern":"A うが B うが","meaning":"Expresses the idea of 'no matter how... or', 'even if... or'.","meaningId":"Mengekspresikan gagasan 'tidak peduli bagaimana... atau', 'sekalipun... atau'.","formation":"Verb-volitional form + うが + Verb-volitional form + うが, or Adjective (-かろう) + が + Adjective (-かろう) + が","formationId":"Bentuk kemauan-kata kerja + うが + Bentuk kemauan-kata kerja + うが, atau Kata Sifat (-かろう) + が + Kata Sifat (-かろう) + が","examples":[{"jp":"朝早かろうが夜遅かろうが、いつもバスが遅れる。","romaji":"Asa hayakarou ga yoru osokarou ga, itsumo basu ga okureru.","en":"No matter whether it's early morning or late at night, the bus is always late.","id":"Entah itu pagi atau larut malam, bus selalu terlambat."},{"jp":"彼に話そうが話すまいが、結果は変わらない。","romaji":"Kare ni hanasou ga hanasu maiga, kekka wa kawaranai.","en":"Even if I talk to him or don't, the outcome won't change.","id":"Bahkan jika aku berbicara dengannya atau tidak, hasilnya tidak akan berubah."},{"jp":"この仕事をしようがしまいが、給料は同じだ。","romaji":"Kono shigoto o shiyou ga shimai ga, kyuuryou wa onaji da.","en":"Whether I do this job or not, the salary is the same.","id":"Apakah saya melakukan pekerjaan ini atau tidak, gajinya tetap sama."},{"jp":"あの人に話そうが話すまいが、理解してくれるとは思えない。","romaji":"Ano hito ni hanasou ga hanasu maiga, rikai shite kureru to wa omoenai.","en":"I don't think that person would understand whether I talk to them or not.","id":"Saya tidak berpikir orang itu akan mengerti apakah saya berbicara dengan mereka atau tidak."}]},{"pattern":"A うと B うと","meaning":"Shows that the speaker is indifferent to both conditions; 'whether A or B'.","meaningId":"Menunjukkan bahwa penutur acuh tak acuh terhadap kedua kondisi tersebut; 'apakah A atau B'.","formation":"い-adjective (-かろう) + と, な-adjective / Noun + であろうと","formationId":"い-kata sifat (-かろう) + と, な-kata sifat / Kata Benda + であろうと","examples":[{"jp":"雨が降ろうと晴れようと、私は毎日ジョギングをします。","romaji":"Ame ga furou to hareyou to, watashi wa mainichi jogingu o shimasu.","en":"Whether it's raining or sunny, I jog every day.","id":"Entah saat hujan atau cerah, saya jogging setiap hari."},{"jp":"試験が難しかろうと易しかろうと、一生懸命勉強します。","romaji":"Shiken ga muzukashikarou to yasashikarou to, isshoukenmei benkyou shimasu.","en":"Whether the exam is difficult or easy, I will study hard.","id":"Apakah ujiannya sulit atau mudah, saya akan belajar dengan giat."},{"jp":"彼が学生であろうと社会人であろうと、私は彼を尊敬しています。","romaji":"Kare ga gakusei de arou to shakaijin de arou to, watashi wa kare o sonkei shiteimasu.","en":"Whether he's a student or a working adult, I respect him.","id":"Entah dia seorang pelajar atau orang dewasa yang bekerja, saya menghormatinya."},{"jp":"その映画が新しいであろうと古いであろうと、面白ければ観ます。","romaji":"Sono eiga ga atarashii de arou to furui de arou to, omoshirokereba mimasu.","en":"Whether the movie is new or old, if it's interesting, I'll watch it.","id":"Entah filmnya baru atau lama, kalau menarik, saya akan menontonnya."}]},{"pattern":"A かたわら B","meaning":"Expresses 'while also', 'at the same time as'.","meaningId":"Menyatakan 'sementara juga', 'pada saat yang sama dengan'.","formation":"Verb-dictionary form + かたわら, Noun + のかたわら","formationId":"Bentuk kamus kata kerja + かたわら, Kata Benda + のかたわら","examples":[{"jp":"彼は仕事をするかたわら、大学に通っている。","romaji":"Kare wa shigoto o suru katawara, daigaku ni kayotte iru.","en":"While working, he also attends university.","id":"Sambil bekerja, ia juga kuliah."},{"jp":"私は学生のかたわら、レストランでアルバイトをしている。","romaji":"Watashi wa gakusei no katawara, resutoran de arubaito o shite iru.","en":"While being a student, I work part-time at a restaurant.","id":"Saat menjadi mahasiswa, saya bekerja paruh waktu di sebuah restoran."},{"jp":"彼女は医者のかたわら、趣味で絵を描いている。","romaji":"Kanojo wa isha no katawara, shumi de e o kaite iru.","en":"While being a doctor, she paints as a hobby.","id":"Semasa menjadi dokter, ia melukis sebagai hobi."},{"jp":"彼は仕事をするかたわら、ボランティア活動にも積極的に参加している。","romaji":"Kare wa shigoto o suru katawara, borantia katsudou ni mo sekkyokuteki ni sanka shite iru.","en":"While doing his job, he also actively participates in volunteer work.","id":"Saat melakukan pekerjaannya, ia juga aktif berpartisipasi dalam pekerjaan sukarela."}]},{"pattern":"A かれ B かれ","meaning":"Expresses 'whether A or B'; both situations are included.","meaningId":"Menyatakan 'apakah A atau B'; kedua situasi disertakan.","formation":"Commonly i-adjective stems + かれ + i-adjective stems + かれ (e.g. 早かれ遅かれ). Also sometimes Noun + かれ + Noun + かれ in older usage.","formationId":"Umumnya kata sifat i + かれ + kata sifat i + かれ (misalnya 早かれ遅かれ). Terkadang juga Kata Benda + かれ + Kata Benda + かれ dalam penggunaan yang lebih lama.","examples":[{"jp":"冬かれ夏かれ、毎日ジョギングする。","romaji":"Fuyu kare natsu kare, mainichi jogingu suru.","en":"Whether it's winter or summer, I jog every day.","id":"Baik saat musim dingin atau musim panas, saya jogging setiap hari."},{"jp":"彼が来るかれ来ないかれ、パーティーは始める。","romaji":"Kare ga kuru kare konai kare, paatii wa hajimeru.","en":"Whether he comes or not, the party will start.","id":"Apakah dia datang atau tidak, pesta akan dimulai."},{"jp":"勝つかれ負けるかれ、試合に出ることが大事だ。","romaji":"Katsu kare makeru kare, shiai ni deru koto ga daiji da.","en":"Whether we win or lose, it's important to take part in the match.","id":"Apakah kami menang atau kalah, penting untuk mengambil bagian dalam pertandingan."},{"jp":"雨かれ雪かれ、犬の散歩は欠かさない。","romaji":"Ame kare yuki kare, inu no sanpo wa kakasanai.","en":"Whether it's raining or snowing, I never skip walking the dog.","id":"Baik saat hujan atau turun salju, saya tidak pernah melewatkan jalan-jalan dengan anjing."}]},{"pattern":"A だの B だの","meaning":"Used to list examples (often with a critical or complaining tone); 'things like A, B, etc.'.","meaningId":"Digunakan untuk membuat daftar contoh (seringkali dengan nada kritis atau mengeluh); 'hal-hal seperti A, B, dll.'.","formation":"Noun/Verb casual + だの + Noun/Verb casual + だの","formationId":"Kata Benda/Kata Kerja biasa + だの + Kata Benda/Kata Kerja biasa + だの","examples":[{"jp":"彼はいつも遅刻だの、仕事を忘れるだので困る。","romaji":"Kare wa itsumo chikoku dano, shigoto o wasureru dano de komaru.","en":"I'm troubled because he's always late, forgets work, and so on.","id":"Aku kesusahan karena dia selalu terlambat, lupa kerja, dan sebagainya."},{"jp":"彼女は新しい服だの、化粧品だのによくお金を使います。","romaji":"Kanojo wa atarashii fuku dano, keshouhin dano ni yoku okane o tsukaimasu.","en":"She often spends money on new clothes, cosmetics, and so on.","id":"Dia sering mengeluarkan uang untuk membeli baju baru, kosmetik, dan sebagainya."},{"jp":"彼が言うには、音楽だの映画だの本だのが好きらしい。","romaji":"Kare ga iu ni wa, ongaku dano, eiga dano, hon dano ga suki rashii.","en":"He says he likes music, movies, books, and so on.","id":"Dia bilang dia suka musik, film, buku, dan sebagainya."},{"jp":"子供にはお菓子だの、おもちゃだの、好きなものを限りなく与えてあげたい。","romaji":"Kodomo ni wa okashi dano, omocha dano, suki na mono o kagirinaku ataete agetai.","en":"I want to give children all the things they like, such as sweets and toys, without limit.","id":"Saya ingin memberi anak-anak semua hal yang mereka sukai, seperti permen dan mainan, tanpa batas."}]},{"pattern":"A であれ B であれ","meaning":"Indicates the same statement applies to both A and B; 'whether A or B'.","meaningId":"Menunjukkan pernyataan yang sama berlaku untuk A dan B; 'apakah A atau B'.","formation":"Noun A + であれ + Noun B + であれ","formationId":"Kata Benda A + であれ + Kata Benda B + であれ","examples":[{"jp":"雨であれ雪であれ、試合は中止にならない。","romaji":"Ame deare yuki deare, shiai wa chuushi ni naranai.","en":"Whether it's rain or snow, the match will not be canceled.","id":"Baik hujan maupun salju, pertandingan tidak akan dibatalkan."},{"jp":"男であれ女であれ、平等に扱われるべきだ。","romaji":"Otoko deare onna deare, byoudou ni atsukawareru beki da.","en":"Whether man or woman, everyone should be treated equally.","id":"Baik laki-laki maupun perempuan, semua orang harus diperlakukan sama."},{"jp":"豊かであれ貧乏であれ、真の幸福は金では買えない。","romaji":"Yutaka deare binbou deare, shin no shiawase wa kane de wa kaenai.","en":"Whether rich or poor, true happiness can't be bought with money.","id":"Baik kaya atau miskin, kebahagiaan sejati tidak bisa dibeli dengan uang."},{"jp":"経験者であれ初心者であれ、このゲームは楽しめる。","romaji":"Keikensha deare shoshinsha deare, kono geemu wa tanoshimeru.","en":"Whether you're a veteran or a beginner, you can enjoy this game.","id":"Baik Anda seorang veteran atau pemula, Anda dapat menikmati permainan ini."}]},{"pattern":"A というか B というか","meaning":"Means 'rather than say A, it's more like B', or 'whether to call it A or B'.","meaningId":"Berarti 'daripada mengatakan A, lebih seperti B', atau 'apakah menyebutnya A atau B'.","formation":"Phrase A + というか + Phrase B + というか","formationId":"Frase A + というか + Frase B + というか","examples":[{"jp":"彼は無礼というか、直接的というか、とにかくはっきりしている。","romaji":"Kare wa burei to iu ka, chokusetsuteki to iu ka, tonikaku hakkiri shite iru.","en":"He's rather rude, or maybe just direct; in any case, he is very blunt.","id":"Dia agak kasar, atau mungkin terus terang; bagaimanapun juga, dia sangat blak-blakan."},{"jp":"この映画は面白いというか、変というか、とにかく不思議な雰囲気がある。","romaji":"Kono eiga wa omoshiroi to iu ka, hen to iu ka, tonikaku fushigi na fun'iki ga aru.","en":"This movie is interesting or maybe strange; anyway, it has a mysterious vibe.","id":"Film ini menarik atau mungkin aneh; bagaimanapun, ini memiliki getaran misterius."},{"jp":"彼の絵は素晴らしいというか、驚くべきというか、本当に見る価値がある。","romaji":"Kare no e wa subarashii to iu ka, odoroku beki to iu ka, hontou ni miru kachi ga aru.","en":"His paintings are wonderful, or perhaps astonishing; they're definitely worth seeing.","id":"Lukisannya sangat indah, atau mungkin menakjubkan; mereka pasti layak untuk dilihat."},{"jp":"彼女の服はかわいいというか、派手というか、とにかく人目を引く。","romaji":"Kanojo no fuku wa kawaii to iu ka, hade to iu ka, tonikaku hitome o hiku.","en":"Her outfit is cute or maybe flashy; in any case, it grabs people's attention.","id":"Pakaiannya lucu atau mungkin mencolok; bagaimanapun juga, itu menarik perhatian orang."}]},{"pattern":"A とも B とも","meaning":"Expresses two possibilities; 'either A or B', 'whether A or B'.","meaningId":"Mengungkapkan dua kemungkinan; 'baik A atau B', 'apakah A atau B'.","formation":"Noun + とも + Noun + とも (or sometimes Verb forms for each A, B)","formationId":"Kata Benda + とも + Kata Benda + とも (atau terkadang bentuk Kata Kerja untuk setiap A, B)","examples":[{"jp":"決断とも誤りとも、結果は時間が教えてくれるでしょう。","romaji":"Ketsudan tomo ayamari tomo, kekka wa jikan ga oshiete kureru deshou.","en":"Whether it's a wise decision or a mistake, time will show the result.","id":"Entah itu keputusan bijak atau kesalahan, waktu akan menunjukkan hasilnya."},{"jp":"彼は父とも兄とも、もう何年も話していない。","romaji":"Kare wa chichi tomo ani tomo, mou nannen mo hanashite inai.","en":"He hasn't spoken to either his father or his brother in years.","id":"Dia belum berbicara dengan ayah atau saudara laki-lakinya selama bertahun-tahun."},{"jp":"彼女とも友達とも映画を見に行くつもりです。","romaji":"Kanojo tomo tomodachi tomo eiga o mi ni iku tsumori desu.","en":"I plan to go watch a movie either with my girlfriend or a friend.","id":"Saya berencana untuk pergi menonton film bersama pacar atau teman saya."},{"jp":"このゲームには時間とも努力とも言えないほどの根気が必要です。","romaji":"Kono geemu ni wa jikan tomo doryoku tomo ienai hodo no konki ga hitsuyou desu.","en":"This game requires a kind of persistence beyond just time or effort.","id":"Permainan ini membutuhkan ketekunan yang lebih dari sekedar waktu atau usaha."}]},{"pattern":"A にしろ B にしろ","meaning":"Means 'whether it is A or B'; 'regardless of A or B'.","meaningId":"Berarti 'apakah itu A atau B'; 'terlepas dari A atau B'.","formation":"Noun A + にしろ + Noun B + にしろ, or Verb-casual A + にしろ + Verb-casual B + にしろ","formationId":"Kata Benda A + にしろ + Kata Benda B + にしろ, atau Kata Kerja Biasa A + にしろ + Kata Kerja Biasa B + にしろ","examples":[{"jp":"暑いにしろ寒いにしろ、毎日運動するべきです。","romaji":"Atsui ni shiro samui ni shiro, mainichi undou suru beki desu.","en":"Whether it's hot or cold, you should exercise every day.","id":"Baik panas maupun dingin, Anda harus berolahraga setiap hari."},{"jp":"合格するにしろ不合格になるにしろ、最善を尽くしました。","romaji":"Goukaku suru ni shiro fukougaku ni naru ni shiro, saizen o tsukushimashita.","en":"Whether I pass or fail, I did my best.","id":"Apakah saya lulus atau gagal, saya melakukan yang terbaik."},{"jp":"忙しいにしろ暇にしろ、時間を大切にすべきです。","romaji":"Isogashii ni shiro hima ni shiro, jikan o taisetsu ni subeki desu.","en":"Whether you're busy or free, you should value your time.","id":"Apakah Anda sibuk atau senggang, Anda harus menghargai waktu Anda."},{"jp":"大きいにしろ小さいにしろ、その箱は全部ここに運んでください。","romaji":"Ookii ni shiro chiisai ni shiro, sono hako wa zenbu koko ni hakonde kudasai.","en":"Whether they're large or small, please move all those boxes here.","id":"Baik besar atau kecil, harap pindahkan semua kotak itu ke sini."}]},{"pattern":"A にせよ B にせよ","meaning":"Either A or B; Regardless of whether it's A or B.","meaningId":"Entah A atau B; Terlepas dari apakah itu A atau B.","formation":"Noun + にせよ + Noun + にせよ (also works with verbs in dictionary form + にせよ)","formationId":"Kata Benda + にせよ + Kata Benda + にせよ (juga dapat digunakan dengan kata kerja dalam bentuk kamus + にせよ)","examples":[{"jp":"雨にせよ雪にせよ、試合は中止しない。","romaji":"Ame ni seyo yuki ni seyo, shiai wa chuushi shinai.","en":"Whether it's rain or snow, the match won't be cancelled.","id":"Baik hujan atau salju, pertandingan tidak akan dibatalkan."},{"jp":"彼にせよ彼女にせよ、誰か一人が行くべきだ。","romaji":"Kare ni seyo kanojo ni seyo, dareka hitori ga iku beki da.","en":"Whether it's him or her, someone should go.","id":"Entah itu dia, seseorang harus pergi."},{"jp":"成果にせよ努力にせよ、どちらも重要だ。","romaji":"Seika ni seyo doryoku ni seyo, dochira mo juuyou da.","en":"Whether it's results or effort, both are important.","id":"Baik itu hasil atau usaha, keduanya penting."},{"jp":"春にせよ秋にせよ、私は花が好きだ。","romaji":"Haru ni seyo aki ni seyo, watashi wa hana ga suki da.","en":"Whether it's spring or fall, I like flowers.","id":"Entah itu musim semi atau musim gugur, saya suka bunga."}]},{"pattern":"A につけ B につけ","meaning":"Expresses 'whether... or...', 'both... and...', 'in either case'.","meaningId":"Menyatakan 'apakah... atau...', 'keduanya... dan...', 'dalam kedua kasus'.","formation":"Phrase A (dictionary/adjective form) + につけ、Phrase B (dictionary/adjective form) + につけ","formationId":"Frasa A (kamus/bentuk kata sifat) + につけ、Frase B (kamus/bentuk kata sifat) + につけ","examples":[{"jp":"彼には笑うにつけ泣くにつけ、とても魅力的だ。","romaji":"Kare ni wa warau ni tsuke naku ni tsuke, totemo miryokuteki da.","en":"He is very charming whether he’s laughing or crying.","id":"Dia sangat menawan apakah dia tertawa atau menangis."},{"jp":"嬉しいにつけ悲しいにつけ、彼はいつも音楽を聴いている。","romaji":"Ureshii ni tsuke kanashii ni tsuke, kare wa itsumo ongaku o kiite iru.","en":"Whether he's happy or sad, he's always listening to music.","id":"Entah dia senang atau sedih, dia selalu mendengarkan musik."},{"jp":"日中につけ夜間につけ、この景色は美しい。","romaji":"Nitchuu ni tsuke yakan ni tsuke, kono keishiki wa utsukushii.","en":"This view is beautiful whether it's daytime or nighttime.","id":"Pemandangan ini indah baik siang maupun malam hari."},{"jp":"喜びにつけ悲しみにつけ、彼女はいつも私を支えてくれる。","romaji":"Yorokobi ni tsuke kanashimi ni tsuke, kanojo wa itsumo watashi o sasaete kureru.","en":"Whether I’m joyful or sorrowful, she always supports me.","id":"Entah aku senang atau sedih, dia selalu mendukungku."}]},{"pattern":"A のやら B のやら","meaning":"Used when the speaker is unsure or confused between multiple possibilities.","meaningId":"Digunakan ketika pembicara tidak yakin atau bingung antara berbagai kemungkinan.","formation":"Noun1 + のやら + Noun2 + のやら (also works with adjectives and verbs + のやら)","formationId":"Kata Benda1 + のやら + Kata Benda2 + のやら (juga dapat digunakan dengan kata sifat dan kata kerja + のやら)","examples":[{"jp":"彼が怒っているのやら、悲しいのやら、私には分からない。","romaji":"Kare ga okotte iru no yara, kanashii no yara, watashi ni wa wakaranai.","en":"I don't know whether he's angry or sad.","id":"Saya tidak tahu apakah dia marah atau sedih."},{"jp":"試験の結果が良いのやら悪いのやら、気になって仕方がない。","romaji":"Shiken no kekka ga yoi no yara warui no yara, ki ni natte shikata ga nai.","en":"I can’t help worrying whether my exam results are good or bad.","id":"Mau tak mau aku khawatir apakah hasil ujianku baik atau buruk."},{"jp":"彼女が私を好きなのやら嫌いなのやら、わからない。","romaji":"Kanojo ga watashi o suki na no yara kirai na no yara, wakaranai.","en":"I don’t know whether she likes me or hates me.","id":"Aku tidak tahu apakah dia menyukaiku atau membenciku."},{"jp":"彼が本当に行くのやら行かないのやら、はっきりしない。","romaji":"Kare ga hontou ni iku no yara ikanai no yara, hakkiri shinai.","en":"It’s unclear whether he will really go or not.","id":"Tidak jelas apakah dia benar-benar akan pergi atau tidak."}]},{"pattern":"Noun1 が Noun1 なら、 Noun2 も Noun2 だ (A ga A nara, B mo B da)","meaning":"Indicates a parallel or matching situation; 'if Noun1 is (truly) Noun1, then Noun2 is also Noun2'.","meaningId":"Menunjukkan situasi paralel atau serasi; 'jika Noun1 (benar-benar) Noun1, maka Noun2 juga Noun2'.","formation":"Noun1 + が + (repeat Noun1) + なら、Noun2 + も + (repeat Noun2) + だ","formationId":"Kata Benda1 + が + (Ulangi Kata Benda1) + なら、Kata Benda2 + も + (Ulangi Kata Benda2) + だ","examples":[{"jp":"鬼が鬼なら、人間も人間だ。","romaji":"Oni ga oni nara, ningen mo ningen da.","en":"If demons are indeed demons, humans are likewise humans.","id":"Jika setan memang setan, maka manusia juga manusia."},{"jp":"彼が社長なら、私も社長だ。","romaji":"Kare ga shachou nara, watashi mo shachou da.","en":"If he is the president, then I'm the president too.","id":"Jika dia presidennya, maka saya juga presidennya."},{"jp":"貴様が戦士なら、俺も戦士だ。","romaji":"Kisama ga senshi nara, ore mo senshi da.","en":"If you're a warrior, then I'm a warrior as well.","id":"Jika Anda seorang pejuang, maka saya juga seorang pejuang."},{"jp":"ハムスターがペットなら、猫もペットだ。","romaji":"Hamusutā ga petto nara, neko mo petto da.","en":"If a hamster counts as a pet, then a cat is also a pet.","id":"Jika hamster dianggap sebagai hewan peliharaan, maka kucing juga merupakan hewan peliharaan."}]},{"pattern":"Noun1 も Noun1 なら、Noun2 も Noun2 だ (A mo A nara, B mo B da)","meaning":"Highlights two parallel facts or characteristics; 'if it’s said that ~, then it can also be said that ~'.","meaningId":"Menyoroti dua fakta atau karakteristik paralel; 'kalau dikatakan begitu ~, maka bisa juga dikatakan begitu ~'.","formation":"Noun1 + も + (repeat Noun1) + なら、Noun2 + も + (repeat Noun2) + だ","formationId":"Kata Benda1 + も + (Ulangi Kata Benda1) + なら、Kata Benda2 + も + (Ulangi Kata Benda2) + だ","examples":[{"jp":"君も君なら、私も私だ。","romaji":"Kimi mo kimi nara, watashi mo watashi da.","en":"If you are you, then I am also me.","id":"Jika kamu adalah kamu, maka aku juga adalah aku."},{"jp":"夏も夏なら、冬も冬だ。","romaji":"Natsu mo natsu nara, fuyu mo fuyu da.","en":"If it’s said that summer is summer, then winter is also winter.","id":"Jika dikatakan musim panas adalah musim panas, maka musim dingin juga merupakan musim dingin."},{"jp":"東京も東京なら、大阪も大阪だ。","romaji":"Toukyou mo toukyou nara, Oosaka mo Oosaka da.","en":"If Tokyo is Tokyo, then Osaka is also Osaka (they each have their distinctive qualities).","id":"Jika Tokyo adalah Tokyo, maka Osaka juga Osaka (masing-masing memiliki ciri khasnya masing-masing)."},{"jp":"犬も犬なら、猫も猫だ。","romaji":"Inu mo inu nara, neko mo neko da.","en":"If dogs are dogs, then cats are also cats.","id":"Jika anjing tetaplah anjing, maka kucing jugalah kucing."}]},{"pattern":"Noun + あっての + Noun","meaning":"Expresses 'B cannot exist without A'; 'B only exists because of A'.","meaningId":"Menyatakan 'B tidak bisa ada tanpa A'; 'B hanya ada karena A'.","formation":"Noun1 + あっての + Noun2","formationId":"Kata Benda1 + あっての + Kata Benda2","examples":[{"jp":"家族あっての私です。","romaji":"Kazoku atte no watashi desu.","en":"I am who I am thanks to my family.","id":"Aku adalah diriku yang sekarang berkat keluargaku."},{"jp":"お客様あってのビジネスです。","romaji":"Okyakusama atte no bijinesu desu.","en":"A business is nothing without its customers.","id":"Sebuah bisnis tidak ada artinya tanpa pelanggannya."},{"jp":"練習あっての成功です。","romaji":"Renshuu atte no seikou desu.","en":"Success is nothing without practice.","id":"Kesuksesan tidak ada artinya tanpa latihan."},{"jp":"健康あっての仕事です。","romaji":"Kenkou atte no shigoto desu.","en":"Work is nothing without your health.","id":"Pekerjaan tidak ada artinya tanpa kesehatan Anda."}]},{"pattern":"Noun かたがた","meaning":"Do one thing while also doing another; 'while', 'and at the same time'.","meaningId":"Lakukan satu hal sambil melakukan hal lain; 'sementara', 'dan pada saat yang sama'.","formation":"Noun + かたがた","formationId":"Kata benda + かたがた","examples":[{"jp":"東京へ出張のかたがた、友人に会いに行った。","romaji":"Toukyou e shucchou no kata gata, yuujin ni ai ni itta.","en":"While on a business trip to Tokyo, I also went to see a friend.","id":"Saat dalam perjalanan bisnis ke Tokyo, saya juga pergi menemui seorang teman."},{"jp":"観光のかたがた、お土産を買いました。","romaji":"Kankou no kata gata, omiyage o kaimashita.","en":"While sightseeing, I bought some souvenirs.","id":"Saat jalan-jalan, saya membeli beberapa oleh-oleh."},{"jp":"散歩のかたがた、ゴミを拾った。","romaji":"Sanpo no kata gata, gomi o hirotta.","en":"While taking a walk, I also picked up trash.","id":"Sambil berjalan-jalan, saya juga memungut sampah."},{"jp":"学習のかたがた、音楽を聞いた。","romaji":"Gakushuu no kata gata, ongaku o kiita.","en":"While studying, I also listened to music.","id":"Sambil belajar, saya juga mendengarkan musik."}]},{"pattern":"Noun がてら","meaning":"Means 'while...at the same time', 'on the occasion of', or 'along with'.","meaningId":"Berarti 'sementara...pada saat yang sama', 'pada kesempatan', atau 'bersama'.","formation":"Noun + がてら","formationId":"Kata benda + がてら","examples":[{"jp":"散歩がてらに、近くの公園で花を摘みました。","romaji":"Sanpo gatera ni, chikaku no kouen de hana o tsumimashita.","en":"While taking a walk, I picked some flowers in the nearby park.","id":"Sambil berjalan-jalan, saya memetik beberapa bunga di taman terdekat."},{"jp":"買い物がてら、友達に会いに行きました。","romaji":"Kaimono gatera, tomodachi ni ai ni ikimashita.","en":"While I was out shopping, I went to see a friend.","id":"Ketika saya sedang berbelanja, saya pergi menemui seorang teman."},{"jp":"彼女は旅行がてら、新しい言語を勉強しました。","romaji":"Kanojo wa ryokou gatera, atarashii gengo o benkyou shimashita.","en":"She studied a new language while traveling.","id":"Dia belajar bahasa baru saat bepergian."},{"jp":"ドライブがてら、新しいアルバムを聞きました。","romaji":"Doraibu gatera, atarashii arubamu o kikimashita.","en":"I listened to a new album while going for a drive.","id":"Saya mendengarkan album baru sambil berkendara."}]},{"pattern":"Noun からある (〜kara aru)","meaning":"Used with large numbers or measurements to emphasize 'at least that many' or 'no less than.'","meaningId":"Digunakan dengan angka atau ukuran yang besar untuk menekankan 'setidaknya sebanyak itu' atau 'tidak kurang dari'.","formation":"Number + Counter + からある","formationId":"Angka + Penghitung + からある","examples":[{"jp":"彼のコレクションは500個からある。","romaji":"Kare no korekushon wa gohyaku ko kara aru.","en":"He has at least 500 items in his collection.","id":"Dia memiliki setidaknya 500 item dalam koleksinya."},{"jp":"このビルは40階からある。","romaji":"Kono biru wa yonjuu kai kara aru.","en":"This building has at least 40 floors.","id":"Gedung ini setidaknya memiliki 40 lantai."},{"jp":"彼の財産は10億円からある。","romaji":"Kare no zaisan wa juu oku en kara aru.","en":"He has assets worth at least one billion yen.","id":"Dia memiliki aset senilai setidaknya satu miliar yen."},{"jp":"このマラソンは10kmからある。","romaji":"Kono marason wa juu kiro kara aru.","en":"This marathon is at least 10 kilometers long.","id":"Maraton ini panjangnya setidaknya 10 kilometer."}]},{"pattern":"Noun からする","meaning":"Used to indicate that something is judged, estimated, or considered from a certain point or aspect.","meaningId":"Digunakan untuk menunjukkan bahwa sesuatu dinilai, diperkirakan, atau dipertimbangkan dari sudut atau aspek tertentu.","formation":"Noun + からする","formationId":"Kata benda + からする","examples":[{"jp":"彼の態度からすると、彼はその計画に反対しているようだ。","romaji":"Kare no taido kara suru to, kare wa sono keikaku ni hantai shiteiru you da.","en":"Judging from his attitude, he seems to be against the plan.","id":"Dilihat dari sikapnya, dia sepertinya menentang rencana tersebut."},{"jp":"このレストランの雰囲気からすると、料理もすばらしいはずだ。","romaji":"Kono resutoran no fun'iki kara suru to, ryouri mo subarashii hazu da.","en":"Judging from the atmosphere of this restaurant, the food must be wonderful.","id":"Dilihat dari suasana restoran ini, makanannya pasti enak."},{"jp":"彼女の成績からすると、彼女は非常に勉強熱心な人でしょう。","romaji":"Kanojo no seiseki kara suru to, kanojo wa hijou ni benkyou nesshin na hito deshou.","en":"Judging from her grades, she must be a very diligent student.","id":"Dilihat dari nilainya, dia pasti murid yang sangat rajin."},{"jp":"その会社の成長率からすると、将来的には大きな利益を得られるでしょう。","romaji":"Sono kaisha no seicho-ritsu kara suru to, shouraiteki ni wa ooki na rieki o erareru deshou.","en":"From the company's growth rate, it seems likely to gain substantial profits in the future.","id":"Dilihat dari tingkat pertumbuhannya, perusahaan tersebut sepertinya akan memperoleh keuntungan yang cukup besar di masa depan."}]},{"pattern":"Noun からの","meaning":"Defines the starting point or the origin; 'from'.","meaningId":"Mendefinisikan titik awal atau asal; 'dari'.","formation":"Noun + からの","formationId":"Kata benda + からの","examples":[{"jp":"日本からの手紙を受け取りました。","romaji":"Nihon kara no tegami wo uketorimashita.","en":"I received a letter from Japan.","id":"Saya menerima surat dari Jepang."},{"jp":"彼は東京からの旅行者です。","romaji":"Kare wa Tokyo kara no ryokousha desu.","en":"He is a traveler from Tokyo.","id":"Dia adalah seorang musafir dari Tokyo."},{"jp":"昨日、母からの電話がありました。","romaji":"Kinou, haha kara no denwa ga arimashita.","en":"Yesterday, I got a call from my mother.","id":"Kemarin, aku mendapat telepon dari ibuku."},{"jp":"彼女は大学からの友人です。","romaji":"Kanojo wa daigaku kara no yuujin desu.","en":"She is a friend from college.","id":"Dia adalah teman kuliah."}]},{"pattern":"Noun から言わせれば","meaning":"Express the perspective of the noun; 'from ~'s point of view.'","meaningId":"Ekspresikan perspektif kata benda; 'dari sudut pandang ~.'","formation":"Noun + から言わせれば","formationId":"Kata benda + から言わせれば","examples":[{"jp":"先生から言わせれば、毎日勉強するべきだ。","romaji":"Sensei kara iwasereba, mainichi benkyou suru beki da.","en":"From the teacher's point of view, you should study every day.","id":"Dari sudut pandang guru, Anda harus belajar setiap hari."},{"jp":"子供たちから言わせれば、もっと遊ぶ時間がほしい。","romaji":"Kodomo-tachi kara iwasereba, motto asobu jikan ga hoshii.","en":"From the children's perspective, they want more time to play.","id":"Dari sudut pandang anak-anak, mereka ingin lebih banyak waktu bermain."},{"jp":"僕から言わせれば、そのプランは実行可能だ。","romaji":"Boku kara iwasereba, sono puran wa jikkou kanou da.","en":"From my point of view, that plan is feasible.","id":"Dari sudut pandang saya, rencana itu layak dilakukan."},{"jp":"犬から言わせれば、もっと散歩したいはずだ。","romaji":"Inu kara iwasereba, motto sanpo shitai hazu da.","en":"If the dog could talk, it would probably want more walks.","id":"Jika anjing dapat berbicara, ia mungkin ingin berjalan-jalan lebih banyak."}]},{"pattern":"Noun + ぐるみ (〜gurumi)","meaning":"Describes 'entirely', 'all together', or 'as a whole group'.","meaningId":"Menjelaskan 'seluruhnya', 'bersama-sama', atau 'sebagai satu kelompok keseluruhan'.","formation":"Noun + ぐるみ","formationId":"Kata benda + ぐるみ","examples":[{"jp":"家族ぐるみで旅行に行きました。","romaji":"Kazoku gurumi de ryokou ni ikimashita.","en":"We went on a trip with the whole family.","id":"Kami melakukan perjalanan bersama seluruh keluarga."},{"jp":"クラスぐるみで遠足に行きました。","romaji":"Kurasu gurumi de ensoku ni ikimashita.","en":"The entire class went on an excursion.","id":"Seluruh kelas pergi bertamasya."},{"jp":"この国は国民ぐるみでその法案を支持しています。","romaji":"Kono kuni wa kokumin gurumi de sono houan wo shiji shiteimasu.","en":"The entire population of the country supports that bill.","id":"Seluruh penduduk negara mendukung RUU tersebut."},{"jp":"彼は友人ぐるみでそのクラブに参加した。","romaji":"Kare wa yuujin gurumi de sono kurabu ni sanka shita.","en":"He joined the club along with all of his friends.","id":"Dia bergabung dengan klub bersama semua temannya."}]},{"pattern":"Noun こそあれ","meaning":"Expresses 'though there is ... (some negative or burdensome aspect), still ...'.","meaningId":"Menyatakan 'meskipun ada... (beberapa aspek negatif atau memberatkan), tetap saja...'.","formation":"Noun + こそあれ + (result/continuation)","formationId":"Kata Benda + こそあれ + (hasil/lanjutan)","examples":[{"jp":"問題こそあれ、プロジェクトは順調に進んでいます。","romaji":"Mondai koso are, purojekuto wa junchou ni susunde imasu.","en":"Though there are problems, the project is progressing smoothly.","id":"Meskipun ada kendala, proyek ini berjalan dengan lancar."},{"jp":"多少のリスクこそあれ、挑戦する価値はある。","romaji":"Tashou no risuku koso are, chousen suru kachi wa aru.","en":"Though there is some risk, it's worth taking on the challenge.","id":"Meskipun ada risikonya, ada baiknya menerima tantangan ini."},{"jp":"欠点こそあれ、彼の提案は興味深い。","romaji":"Ketten koso are, kare no teian wa kyoumibukai.","en":"Though it has flaws, his proposal is intriguing.","id":"Meski memiliki kekurangan, usulannya menarik."},{"jp":"不安こそあれ、今が行動するときだ。","romaji":"Fuan koso are, ima ga koudou suru toki da.","en":"Though there is anxiety, now is the time to act.","id":"Meskipun ada kekhawatiran, sekaranglah waktunya untuk bertindak."}]},{"pattern":"Noun こそ～が","meaning":"Emphasizes that 'it is precisely Noun that ...', then adds a contrasting or additional point.","meaningId":"Menekankan 'Justru Noun that ...', lalu menambahkan poin kontras atau tambahan.","formation":"Noun + こそ + (statement) + が + (contrasting/additional statement)","formationId":"Kata benda + こそ + (pernyataan) + が + (pernyataan kontras/tambahan)","examples":[{"jp":"お金こそ必要だが、それだけが人生のすべてではない。","romaji":"Okane koso hitsuyou da ga, sore dake ga jinsei no subete de wa nai.","en":"Money is indeed necessary, but it isn't everything in life.","id":"Uang memang diperlukan, namun uang bukanlah segalanya dalam hidup."},{"jp":"努力こそ大事だが、結果も見逃せない。","romaji":"Doryoku koso daiji da ga, kekka mo minogasenai.","en":"Effort is certainly crucial, but results also matter.","id":"Upaya memang penting, namun hasil juga penting."},{"jp":"健康こそ宝だが、ときには仕事を優先せざるを得ない。","romaji":"Kenkou koso takara da ga, toki ni wa shigoto o yuusen sezaru wo enai.","en":"Health is indeed a treasure, but sometimes you have to prioritize work.","id":"Kesehatan memang sebuah harta karun, namun terkadang pekerjaan harus diprioritaskan."},{"jp":"愛こそ力だが、表現するのは難しい。","romaji":"Ai koso chikara da ga, hyougen suru no wa muzukashii.","en":"Love is certainly a powerful force, but it's difficult to express.","id":"Cinta tentu saja merupakan kekuatan yang dahsyat, namun sulit diungkapkan."}]},{"pattern":"Noun こそすれ","meaning":"An emphatic pattern meaning 'it may be X, but definitely not Y.' Often pairs with a negative statement.","meaningId":"Pola tegas yang berarti 'mungkin X, tapi jelas bukan Y.' Seringkali berpasangan dengan pernyataan negatif.","formation":"Noun + こそすれ + (negative or contrasting statement)","formationId":"Kata benda + こそすれ + (pernyataan negatif atau kontras)","examples":[{"jp":"感謝こそすれ、非難などできません。","romaji":"Kansha koso sure, hinan nado dekimasen.","en":"I might feel grateful, but I could never criticize.","id":"Saya mungkin merasa bersyukur, tetapi saya tidak pernah bisa mengkritik."},{"jp":"忙しさこそすれ、退屈することはありません。","romaji":"Isogashisa koso sure, taikutsu suru koto wa arimasen.","en":"I may be busy, but I'm never bored.","id":"Aku mungkin sibuk, tapi aku tidak pernah bosan."},{"jp":"後悔こそすれ、忘れることはできない。","romaji":"Koukai koso sure, wasureru koto wa dekinai.","en":"I might regret it, but I can't forget it.","id":"Aku mungkin menyesalinya, tapi aku tidak bisa melupakannya."},{"jp":"疑問こそすれ、賛成はできない。","romaji":"Gimon koso sure, sansei wa dekinai.","en":"I may have doubts, but I cannot agree.","id":"Saya mungkin ragu, tetapi saya tidak setuju."}]},{"pattern":"Noun ごとき / Noun ごとく (〜gotoki/〜gotoku)","meaning":"Means 'like a...', 'as if...', expressing a simile or metaphor.","meaningId":"Berarti 'seperti...', 'seolah-olah...', mengungkapkan perumpamaan atau metafora.","formation":"Noun + ごとき, Noun + ごとく, Verb-casual + ごとく, い-Adjective + ごとく","formationId":"Kata Benda + ごとき, Kata Benda + ごとく, Kata Kerja-kasual + ごとく, い-Kata Sifat + ごとく","examples":[{"jp":"彼は天使のごとく純粋だ。","romaji":"Kare wa tenshi no gotoku junsui da.","en":"He is as pure as an angel.","id":"Dia semurni malaikat."},{"jp":"悪魔のごとき行為をするな。","romaji":"Akuma no gotoki koui o suru na.","en":"Don't engage in acts like those of a devil.","id":"Jangan terlibat dalam tindakan seperti yang dilakukan setan."},{"jp":"彼女は雪のごとく白い肌をしている。","romaji":"Kanojo wa yuki no gotoku shiroi hada o shiteiru.","en":"She has skin as white as snow.","id":"Dia memiliki kulit seputih salju."},{"jp":"彼は風のごとく去った。","romaji":"Kare wa kaze no gotoku satta.","en":"He left like the wind.","id":"Dia pergi seperti angin."}]},{"pattern":"Noun じゃあるまいし","meaning":"Expressing that something 'is not'; 'it's not like...'. Colloquial/masculine form of ではあるまいし.","meaningId":"Menyatakan bahwa sesuatu 'tidak ada'; 'tidak seperti...'. Bentuk sehari-hari/maskulin dari ではあるまいし.","formation":"Noun or Na-Adjective + じゃあるまいし","formationId":"Kata Benda atau Kata Sifat Na + じゃあるまいし","examples":[{"jp":"彼は子供じゃあるまいし、その問題をしっかりと解決するべきだ。","romaji":"Kare wa kodomo ja aru mai shi, sono mondai o shikkari to kaiketsu suru beki da.","en":"He’s not a child, so he should solve that problem properly.","id":"Dia bukan anak kecil, jadi dia harus menyelesaikan masalah itu dengan baik."},{"jp":"急ぐ必要はない、時間じゃあるまいし。","romaji":"Isogu hitsuyou wa nai, jikan ja aru mai shi.","en":"We don’t need to hurry; it’s not like we’re short of time.","id":"Kita tidak perlu terburu-buru; bukan berarti kita kekurangan waktu."},{"jp":"監督じゃあるまいし、試合の結果について心配するな。","romaji":"Kantoku ja aru mai shi, shiai no kekka ni tsuite shinpai suru na.","en":"You’re not the coach, so don’t worry about the game results.","id":"Anda bukan pelatihnya, jadi jangan khawatir tentang hasil pertandingan."},{"jp":"飴じゃあるまいし、そのまま飲み込んでも大丈夫だよ。","romaji":"Ame ja aru mai shi, sono mama nomikonde mo daijoubu da yo.","en":"It’s not candy, so it’s okay to just swallow it.","id":"Ini bukan permen, jadi tidak apa-apa jika ditelan saja."}]},{"pattern":"Noun ずくめ","meaning":"Denotes 'entirely' or 'nothing but' the preceding noun.","meaningId":"Menunjukkan 'seluruhnya' atau 'tidak lain hanyalah' kata benda sebelumnya.","formation":"Noun + ずくめ","formationId":"Kata benda + ずくめ","examples":[{"jp":"彼は最近、失敗ずくめだ。","romaji":"Kare wa saikin, shippai zukume da.","en":"He has had nothing but failures recently.","id":"Dia hanya mengalami kegagalan akhir-akhir ini."},{"jp":"この冬は雪ずくめで大変だ。","romaji":"Kono fuyu wa yuki zukume de taihen da.","en":"This winter has been nothing but snow, which is tough.","id":"Musim dingin ini hanyalah salju, yang sangat sulit."},{"jp":"彼の話は嘘ずくめだった。","romaji":"Kare no hanashi wa uso zukume datta.","en":"His story was full of nothing but lies.","id":"Kisahnya penuh dengan kebohongan."},{"jp":"今日の仕事は忙しさずくめだった。","romaji":"Kyou no shigoto wa isogashisa zukume datta.","en":"Today's work was nothing but constant busyness.","id":"Pekerjaan hari ini hanyalah kesibukan yang tiada henti."}]},{"pattern":"Noun だけではすまない","meaning":"Expresses 'it can't be settled with just...', 'cannot be resolved merely by...'.","meaningId":"Mengungkapkan 'tidak dapat diselesaikan hanya dengan...', 'tidak dapat diselesaikan hanya dengan...'.","formation":"Noun + だけではすまない","formationId":"Kata Benda + だけではすまない","examples":[{"jp":"この問題は謝罪だけではすまない。","romaji":"Kono mondai wa shazai dake dewa sumanai.","en":"This problem cannot be settled with just an apology.","id":"Masalah ini tidak bisa diselesaikan hanya dengan permintaan maaf."},{"jp":"彼女が怒っているから、お菓子をあげただけではすまないよ。","romaji":"Kanojo ga okotte iru kara, okashi o ageta dake dewa sumanai yo.","en":"She’s angry, so just giving her sweets won't fix it.","id":"Dia marah, jadi memberinya permen saja tidak akan menyelesaikan masalah."},{"jp":"このプロジェクトの成功は努力だけではすまない。","romaji":"Kono purojekuto no seikou wa doryoku dake dewa sumanai.","en":"Success on this project cannot be achieved with mere effort.","id":"Keberhasilan dalam proyek ini tidak dapat dicapai hanya dengan usaha belaka."},{"jp":"資金調達だけではすまない、実際のビジネスプランも必要だ。","romaji":"Shikin choutatsu dake dewa sumanai, jissai no bijinesu puran mo hitsuyou da.","en":"We can’t just finish with fundraising; we also need a real business plan.","id":"Kita tidak bisa menyelesaikannya begitu saja dengan penggalangan dana; kita juga memerlukan rencana bisnis yang nyata."}]},{"pattern":"Noun たりとも～ない","meaning":"Used to show a strong negative: 'not even ~', 'not a single ~'.","meaningId":"Digunakan untuk menunjukkan negatif yang kuat: 'bahkan tidak ~', 'tidak satupun ~'.","formation":"Noun + たりとも + Negative Verb","formationId":"Kata Benda + たりとも + Kata Kerja Negatif","examples":[{"jp":"一分たりとも無駄にするな。","romaji":"Ippun tari tomo muda ni suru na.","en":"Don’t waste even a single minute.","id":"Jangan buang waktu satu menit pun."},{"jp":"彼は一言たりとも話さない。","romaji":"Kare wa hitokoto tari tomo hanasanai.","en":"He doesn't speak even a single word.","id":"Dia tidak berbicara sepatah kata pun."},{"jp":"彼女は一度たりともその映画を見たことがない。","romaji":"Kanojo wa ichido tari tomo sono eiga o mita koto ga nai.","en":"She has never seen that movie, not even once.","id":"Dia belum pernah menonton film itu, tidak sekali pun."},{"jp":"私は一枚たりともその写真を持っていない。","romaji":"Watashi wa ichimai tari tomo sono shashin o motte inai.","en":"I don't have even a single picture of it.","id":"Aku bahkan tidak punya satupun gambarnya."}]},{"pattern":"Noun たる Noun","meaning":"Indicates 'being in the position/state of', used for roles or statuses.","meaningId":"Menunjukkan 'berada dalam posisi/keadaan', digunakan untuk peran atau status.","formation":"Noun1 + たる + Noun2","formationId":"Kata Benda1 + たる + Kata Benda2","examples":[{"jp":"リーダーたる者は、常に先を見て行動すべきだ。","romaji":"Riidaa taru mono wa, tsune ni saki o mite koudou subeki da.","en":"A person who is a leader should always look ahead and act accordingly.","id":"Seseorang yang menjadi pemimpin harus selalu melihat ke depan dan bertindak sesuai dengan itu."},{"jp":"教師たる者、学生に模範を示すべきである。","romaji":"Kyoushi taru mono, gakusei ni mohan o shimesu beki de aru.","en":"Someone who is a teacher should set a good example for the students.","id":"Seseorang yang berprofesi sebagai guru hendaknya memberikan contoh yang baik kepada siswanya."},{"jp":"母たる者、家族を愛するのは当然だ。","romaji":"Haha taru mono, kazoku o aisuru no wa touzen da.","en":"If you are a mother, it’s natural to love your family.","id":"Jika Anda seorang ibu, wajar jika Anda menyayangi keluarga."},{"jp":"医者たる者、患者の安全を最優先に考えるべきだ。","romaji":"Isha taru mono, kanja no anzen o saiyuusen ni kangaeru beki da.","en":"A person who is a doctor should make patient safety their top priority.","id":"Seseorang yang berprofesi sebagai dokter harus menjadikan keselamatan pasien sebagai prioritas utama."}]},{"pattern":"Noun ですら","meaning":"Means 'even', 'as much as', used for emphasis in formal contexts.","meaningId":"Berarti 'genap', 'sebanyak', digunakan untuk penekanan dalam konteks formal.","formation":"Noun + ですら","formationId":"Kata benda + ですら","examples":[{"jp":"明日試験があるのに、彼はテキストですら読まない。","romaji":"Ashita shiken ga aru noni, kare wa tekisuto desura yomanai.","en":"He doesn’t even read the textbook, despite having a test tomorrow.","id":"Dia bahkan tidak membaca buku pelajaran, meski besok ada ujian."},{"jp":"この問題は専門家ですら解けない。","romaji":"Kono mondai wa senmonka desura tokenai.","en":"Even an expert can’t solve this problem.","id":"Bahkan seorang ahli pun tidak dapat menyelesaikan masalah ini."},{"jp":"彼女は最後のスピーチですら泣いてしまった。","romaji":"Kanojo wa saigo no supiichi desura naite shimatta.","en":"She ended up crying, even during the final speech.","id":"Dia akhirnya menangis, bahkan saat pidato terakhirnya."},{"jp":"彼は毎日勉強しているが、基本の漢字ですら覚えられない。","romaji":"Kare wa mainichi benkyou shite iru ga, kihon no kanji desura oboerarenai.","en":"He studies every day, but can’t even remember basic kanji.","id":"Dia belajar setiap hari, tapi bahkan tidak bisa mengingat kanji dasar."}]},{"pattern":"Noun でなくてなんだろう (〜de nakute nandarou)","meaning":"A strong rhetorical question: 'If not X, then what is it?'","meaningId":"Sebuah pertanyaan retoris yang kuat: 'Jika bukan X, lalu apa itu?'","formation":"Noun + でなくてなんだろう","formationId":"Kata Benda + でなくてなんだろう","examples":[{"jp":"これが真実でなくてなんだろう。","romaji":"Kore ga shinjitsu de nakute nandarou.","en":"If this isn’t the truth, then what is?","id":"Jika ini tidak benar, lalu apa?"},{"jp":"彼がリーダーでなくてなんだろう。","romaji":"Kare ga riidaa de nakute nandarou.","en":"If he isn’t the leader, then who is?","id":"Jika dia bukan pemimpinnya, lalu siapa lagi?"},{"jp":"これが愛でなくてなんだろう。","romaji":"Kore ga ai de nakute nandarou.","en":"If this isn’t love, then what is?","id":"Jika ini bukan cinta, lalu apa?"},{"jp":"これが最高のレストランでなくてなんだろう。","romaji":"Kore ga saikou no resutoran de nakute nandarou.","en":"If this isn’t the best restaurant, then what is?","id":"Jika ini bukan restoran terbaik, lalu apa lagi?"}]},{"pattern":"Noun ではあるまいし","meaning":"Means 'it’s not as if...', 'it’s not that...', more formal than じゃあるまいし.","meaningId":"Berarti 'bukannya seperti...', 'bukan itu...', lebih formal dari じゃあるまいし.","formation":"Noun + ではあるまいし","formationId":"Kata benda + ではあるまいし","examples":[{"jp":"彼女はプロの歌手ではあるまいし、完璧を求めるのは酷だ。","romaji":"Kanojo wa puro no kashu de wa aru mai shi, kanpeki o motomeru no wa koku da.","en":"She’s not a professional singer, so it’s rather harsh to demand perfection.","id":"Dia bukan penyanyi profesional, jadi menuntut kesempurnaan agak sulit."},{"jp":"彼は子供ではあるまいし、そんなにチョコレートばかり食べるのはどうかと思う。","romaji":"Kare wa kodomo de wa aru mai shi, sonnani chokoreeto bakari taberu no wa douka to omou.","en":"He’s not a child, so I’m not sure about him eating that much chocolate.","id":"Dia bukan anak kecil, jadi saya tidak yakin dia makan coklat sebanyak itu."},{"jp":"彼は医者ではあるまいし、あなたの健康状態を詮索する必要はない。","romaji":"Kare wa isha de wa aru mai shi, anata no kenkou joutai o sensaku suru hitsuyou wa nai.","en":"He’s not a doctor, so he has no need to pry into your health.","id":"Dia bukan seorang dokter, jadi dia tidak perlu mencampuri kesehatan Anda."},{"jp":"この指輪は高価なものではあるまいし、落としても大したことはない。","romaji":"Kono yubiwa wa kouka na mono de wa aru mai shi, otoshite mo taishita koto wa nai.","en":"It’s not an expensive ring, so dropping it isn’t a big deal.","id":"Ini bukan cincin yang mahal, jadi menjatuhkannya bukanlah masalah besar."}]},{"pattern":"Noun と Noun を兼ねて","meaning":"Used to indicate doing two things at once or fulfilling two roles/purposes.","meaningId":"Digunakan untuk menunjukkan melakukan dua hal sekaligus atau memenuhi dua peran/tujuan.","formation":"Noun + と + Noun + を兼ねて","formationId":"Kata Benda + と + Kata Benda + を兼ねて","examples":[{"jp":"お父さんは社長と経理部長を兼ねています。","romaji":"Otousan wa shachou to keiri buchou o kanete imasu.","en":"My father serves as both the company president and the head of accounting.","id":"Ayah saya menjabat sebagai presiden perusahaan dan kepala akuntansi."},{"jp":"彼女は音楽教師とピアニストを兼ねています。","romaji":"Kanojo wa ongaku kyoushi to pianisuto o kanete imasu.","en":"She works as both a music teacher and a pianist.","id":"Dia bekerja sebagai guru musik dan pianis."},{"jp":"この部屋は寝室と書斎を兼ねています。","romaji":"Kono heya wa shinshitsu to shosai o kanete imasu.","en":"This room serves as both a bedroom and a study.","id":"Ruangan ini berfungsi sebagai kamar tidur sekaligus ruang belajar."},{"jp":"彼は父と母を兼ねて子どもの世話をしている。","romaji":"Kare wa chichi to haha o kanete kodomo no sewa o shite iru.","en":"He looks after his child, taking on both mother and father roles.","id":"Dia merawat anaknya, mengambil peran sebagai ibu dan ayah."}]},{"pattern":"Noun といい Noun といい (〜to ii〜to ii)","meaning":"Used to express 'both A and B'; 'whether it's A or B'; 'not to mention A and also B'.","meaningId":"Digunakan untuk menyatakan 'A dan B'; 'apakah itu A atau B'; 'belum lagi A dan juga B'.","formation":"Noun1 + といい + Noun2 + といい + Comment","formationId":"Kata Benda1 + といい + Kata Benda2 + といい + Komentar","examples":[{"jp":"日本の食べ物といい観光地といい、すべてが素晴らしいです。","romaji":"Nihon no tabemono to ii kankouchi to ii, subete ga subarashii desu.","en":"Both Japanese food and tourist spots are all wonderful.","id":"Makanan Jepang dan tempat wisata semuanya luar biasa."},{"jp":"彼の優しさといい、体力といい、彼は理想的なパートナーだ。","romaji":"Kare no yasashisa to ii, tairyoku to ii, kare wa risouteki na paatonaa da.","en":"Whether it's his kindness or stamina, he is an ideal partner.","id":"Entah itu kebaikan atau staminanya, dia adalah pasangan yang ideal."},{"jp":"この町の映画館といい、公園といい、老若男女が楽しめる。","romaji":"Kono machi no eigakan to ii, kouen to ii, rounyakunan'nyo ga tanoshimeru.","en":"Not to mention the movie theaters and parks in this town, they are enjoyable for all ages.","id":"Belum lagi bioskop dan taman di kota ini, menyenangkan untuk segala usia."},{"jp":"彼の歌唱力といい、ダンスのスキルといい、完璧だ。","romaji":"Kare no kashou ryoku to ii, dansu no sukiru to ii, kanpeki da.","en":"Both his singing ability and his dance skills are perfect.","id":"Kemampuan menyanyi dan keterampilan menarinya sempurna."}]},{"pattern":"Noun という Noun","meaning":"Used to specify or define one noun with another; 'the noun called', 'the noun that is', or 'a certain'.","meaningId":"Digunakan untuk menentukan atau mendefinisikan satu kata benda dengan kata benda lainnya; 'kata benda yang disebut', 'kata benda yang ada', atau 'yang pasti'.","formation":"Noun1 という Noun2","formationId":"Kata benda1 という Kata benda2","examples":[{"jp":"宮崎駿という人は有名なアニメーション監督です。","romaji":"Miyazaki Hayao to iu hito wa yuumei na animation kantoku desu.","en":"The person called Hayao Miyazaki is a famous animation director.","id":"Orang bernama Hayao Miyazaki adalah seorang sutradara animasi terkenal."},{"jp":"その恋人という女性は彼にとても厳しいです。","romaji":"Sono koibito to iu josei wa kare ni totemo kibishii desu.","en":"The woman called his girlfriend is very strict with him.","id":"Wanita yang disebut pacarnya itu sangat tegas padanya."},{"jp":"東京という都市は夜も賑やかです。","romaji":"Tokyo to iu toshi wa yoru mo nigiyaka desu.","en":"The city called Tokyo is bustling even at night.","id":"Kota bernama Tokyo ini ramai bahkan di malam hari."},{"jp":"私は「ハリーポッター」という本が好きです。","romaji":"Watashi wa 'Harry Potter' to iu hon ga suki desu.","en":"I like the book called 'Harry Potter'.","id":"Saya suka buku berjudul 'Harry Potter'."}]},{"pattern":"Noun というところだ","meaning":"Means 'it's approximately...' or 'it's about...'. Used to show approximation or a general assessment.","meaningId":"Berarti 'ini kira-kira...' atau 'ini tentang...'. Digunakan untuk menunjukkan perkiraan atau penilaian umum.","formation":"Noun + というところだ","formationId":"Kata benda + というところだ","examples":[{"jp":"今回の試験の合格者は半数というところだろう。","romaji":"Konkai no shiken no goukakusha wa hansuu to iu tokoro darou.","en":"The passers in this exam would be approximately half.","id":"Jumlah yang lulus dalam ujian ini kira-kira setengahnya."},{"jp":"彼の力は80％というところだ。","romaji":"Kare no chikara wa hachijuu paasento to iu tokoro da.","en":"His strength is about 80%.","id":"Kekuatannya sekitar 80%."},{"jp":"このプランに賛成の人は7割というところだ。","romaji":"Kono puran ni sansei no hito wa nanawari to iu tokoro da.","en":"About 70% of people agree with this plan.","id":"Sekitar 70% orang setuju dengan rencana ini."},{"jp":"課長の意見には、私としては90％というところでしょう。","romaji":"Kachou no iken ni wa, watashi toshite wa kyuujuu paasento to iu tokoro deshou.","en":"As for the section manager's opinion, I'd say I'm about 90% in agreement.","id":"Adapun pendapat manajer bagian, menurut saya sekitar 90% setuju."}]},{"pattern":"Noun + というもの","meaning":"Used to express a generic concept: 'all ~', 'any ~ of that kind'.","meaningId":"Digunakan untuk menyatakan konsep umum: 'semua ~', 'apa pun ~ semacam itu'.","formation":"Noun + というもの","formationId":"Kata benda + というもの","examples":[{"jp":"子供というものは、毎日たくさん遊びます。","romaji":"Kodomo to iu mono wa, mainichi takusan asobimasu.","en":"Children, as a group, play a lot every day.","id":"Anak-anak, sebagai sebuah kelompok, banyak bermain setiap hari."},{"jp":"大学生というものは研究に時間をたくさんかけます。","romaji":"Daigakusei to iu mono wa kenkyuu ni jikan o takusan kakemasu.","en":"University students spend a lot of time on research.","id":"Mahasiswa universitas menghabiskan banyak waktu untuk penelitian."},{"jp":"日本文化というものは伝統的なものと新しいものが混ざっています。","romaji":"Nihon bunka to iu mono wa dentouteki na mono to atarashii mono ga mazatte imasu.","en":"Japanese culture is a mixture of traditional and new.","id":"Budaya Jepang adalah campuran tradisional dan baru."},{"jp":"別れというものはいつも悲しいものです。","romaji":"Wakare to iu mono wa itsumo kanashii mono desu.","en":"Goodbyes are always sad.","id":"Perpisahan selalu menyedihkan."}]},{"pattern":"Noun といったところだ","meaning":"Expresses 'at most', 'as much as', or 'limited to'.","meaningId":"Menyatakan 'paling banyak', 'sebanyak', atau 'terbatas pada'.","formation":"Noun + といったところだ","formationId":"Kata Benda + といったところだ","examples":[{"jp":"彼の英語レベルは初級といったところだ。","romaji":"Kare no eigo reberu wa shokyuu to itta tokoro da.","en":"His English level is at most beginner level.","id":"Level bahasa Inggrisnya paling banyak di level pemula."},{"jp":"私の日本語の語彙は1000語といったところだ。","romaji":"Watashi no nihongo no goi wa sen go to itta tokoro da.","en":"My Japanese vocabulary is limited to about 1000 words.","id":"Kosakata bahasa Jepang saya terbatas sekitar 1000 kata."},{"jp":"彼が毎日ランニングできるのは5キロといったところだ。","romaji":"Kare ga mainichi ranningu dekiru no wa go kiro to itta tokoro da.","en":"He can run as much as 5 kilometers a day at most.","id":"Dia bisa berlari paling banyak 5 kilometer sehari."},{"jp":"その会社の従業員は20人といったところだ。","romaji":"Sono kaisha no juugyouin wa nijuu nin to itta tokoro da.","en":"The employees at that company are limited to about 20 people.","id":"Karyawan di perusahaan itu dibatasi sekitar 20 orang."}]},{"pattern":"Noun といわず Noun といわず","meaning":"Expresses 'both A and B' or 'be it A or B'; applies to both without distinction.","meaningId":"Menyatakan 'A dan B' atau 'baik itu A atau B'; berlaku untuk keduanya tanpa perbedaan.","formation":"Noun1 + といわず + Noun2 + といわず + (rest of the sentence)","formationId":"Kata Benda1 + といわず + Kata Benda2 + といわず + (sisa kalimat)","examples":[{"jp":"冬といわず夏といわず、彼はいつもアイスクリームを食べます。","romaji":"Fuyu to iwazu natsu to iwazu, kare wa itsumo aisukuriimu o tabemasu.","en":"Be it winter or summer, he always eats ice cream.","id":"Baik musim dingin atau musim panas, dia selalu makan es krim."},{"jp":"老いといわず若きといわず、全ての人がそのイベントを楽しめます。","romaji":"Oi to iwazu wakaki to iwazu, subete no hito ga sono ibento o tanoshimemasu.","en":"Whether old or young, everyone can enjoy that event.","id":"Baik tua maupun muda, semua orang bisa menikmati acara itu."},{"jp":"男といわず女といわず、誰もがこの映画を楽しむでしょう。","romaji":"Otoko to iwazu onna to iwazu, daremo ga kono eiga o tanoshimu deshou.","en":"Be it men or women, everyone will enjoy this movie.","id":"Baik pria maupun wanita, semua orang akan menikmati film ini."},{"jp":"月といわず火といわず、あの店は毎日混んでいます。","romaji":"Getsu to iwazu ka to iwazu, ano mise wa mainichi konde imasu.","en":"Be it Monday or Tuesday, that shop is busy every day.","id":"Baik itu Senin atau Selasa, toko itu sibuk setiap hari."}]},{"pattern":"Noun + ときたら (〜tokitara)","meaning":"Expresses strong feelings about a topic; 'speaking of', 'when it comes to'.","meaningId":"Mengungkapkan perasaan yang kuat mengenai suatu topik; 'berbicara tentang', 'bila menyangkut'.","formation":"Noun + ときたら","formationId":"Kata benda + ときたら","examples":[{"jp":"寿司ときたら、彼は何も食べられない。","romaji":"Sushi tokitara, kare wa nanimo taberarenai.","en":"When it comes to sushi, he can't eat anything.","id":"Kalau soal sushi, dia tidak bisa makan apa pun."},{"jp":"数学の問題ときたら、彼女はいつも困っている。","romaji":"Suugaku no mondai tokitara, kanojo wa itsumo komatte iru.","en":"When it comes to math problems, she's always struggling.","id":"Kalau soal matematika, dia selalu kesulitan."},{"jp":"あの店のハンバーガーときたら、本当に美味しい。","romaji":"Ano mise no hanbaagaa tokitara, hontou ni oishii.","en":"Speaking of that shop's hamburgers, they're really delicious.","id":"Ngomong-ngomong soal hamburger di toko itu, rasanya enak sekali."},{"jp":"彼のいつもの態度ときたら、本当に困ったものだ。","romaji":"Kare no itsumo no taido tokitara, hontou ni komatta mono da.","en":"Speaking of his usual attitude, it's truly problematic.","id":"Berbicara tentang sikapnya yang biasa, itu benar-benar bermasalah."}]},{"pattern":"Noun とは比べものにならない","meaning":"Indicates something is not comparable; 'beyond comparison'.","meaningId":"Menunjukkan ada sesuatu yang tidak sebanding; 'tak bisa dibandingkan'.","formation":"Noun + とは比べものにならない","formationId":"Kata Benda + とは比べものにならない","examples":[{"jp":"新しい車の速さは古い車とは比べものにならない。","romaji":"Atarashii kuruma no hayasa wa furui kuruma to wa kurabemono ni naranai.","en":"The speed of the new car is not comparable to the old one.","id":"Kecepatan mobil baru tidak sebanding dengan mobil lama."},{"jp":"彼の英語のうまさは私とは比べものにならない。","romaji":"Kare no eigo no umasa wa watashi to wa kurabemono ni naranai.","en":"His English skills are beyond comparison with mine.","id":"Kemampuan bahasa Inggrisnya tidak bisa dibandingkan dengan kemampuan saya."},{"jp":"日本の技術は他の国とは比べものにならない。","romaji":"Nihon no gijutsu wa hoka no kuni to wa kurabemono ni naranai.","en":"Japan's technology is not comparable to that of other countries.","id":"Teknologi Jepang tidak bisa dibandingkan dengan negara lain."},{"jp":"今回の地震の被害は前回とは比べものにならない。","romaji":"Konkai no jishin no higai wa zenkai to wa kurabemono ni naranai.","en":"The damage from this earthquake is incomparable to the previous one.","id":"Kerusakan akibat gempa kali ini tidak sebanding dengan gempa sebelumnya."}]},{"pattern":"Noun + ともあろう + Noun","meaning":"Used to criticize or question unbecoming behavior by someone of a certain status.","meaningId":"Digunakan untuk mengkritik atau mempertanyakan perilaku tidak pantas yang dilakukan seseorang dengan status tertentu.","formation":"Noun + ともあろう + Noun","formationId":"Kata Benda + ともあろう + Kata Benda","examples":[{"jp":"先生ともあろう者が、そんな間違いをするなんて。","romaji":"Sensei tomoarou mono ga, sonna machigai o suru nante.","en":"For a teacher, it's shocking to make such a mistake.","id":"Bagi seorang guru, sungguh mengejutkan jika melakukan kesalahan seperti itu."},{"jp":"大人ともあろう者が子供みたいにふるまってはいけない。","romaji":"Otona tomoarou mono ga kodomo mitai ni furumatte wa ikenai.","en":"It's not right for an adult to behave like a child.","id":"Tidak pantas bagi orang dewasa berperilaku seperti anak kecil."},{"jp":"社長ともあろう人がそんな失礼なことを言うなんて。","romaji":"Shachou tomoarou hito ga sonna shitsurei na koto o iu nante.","en":"It's shocking that someone who is the company president would say such a rude thing.","id":"Mengejutkan jika seseorang yang merupakan presiden perusahaan mengatakan hal yang tidak sopan seperti itu."},{"jp":"プロの選手ともあろう者が、試合に遅刻するなんて。","romaji":"Puro no senshu tomoarou mono ga, shiai ni chikoku suru nante.","en":"For a professional athlete, being late to a match is unthinkable.","id":"Bagi seorang atlet profesional, terlambat bertanding adalah hal yang tidak terpikirkan."}]},{"pattern":"Noun ともなると (〜to mo naru to)","meaning":"'When it comes to...', emphasizes a change of situation or status.","meaningId":"'Ketika menyangkut...', menekankan perubahan situasi atau status.","formation":"Noun + ともなると","formationId":"Kata benda + ともなると","examples":[{"jp":"クリスマスともなると、街中がきらきらと輝いて見えます。","romaji":"Kurisumasu to mo naru to, machijuu ga kirakira to kagayaite miemasu.","en":"When it comes to Christmas time, the whole city sparkles.","id":"Saat Natal tiba, seluruh kota bersinar."},{"jp":"子供が自分の過ちを認めるともなると、話は別ですね。","romaji":"Kodomo ga jibun no ayamachi o mitomeru to mo naru to, hanashi wa betsu desu ne.","en":"When a child admits their mistake, that’s a different story.","id":"Lain ceritanya jika seorang anak mengakui kesalahannya."},{"jp":"夏休みともなると、海辺は観光客で溢れかえります。","romaji":"Natsu yasumi to mo naru to, umibe wa kankoukyaku de afurekaerimasu.","en":"When summer vacation comes, the seaside is filled with tourists.","id":"Saat liburan musim panas tiba, pantai ini dipenuhi wisatawan."},{"jp":"試験週間ともなると、図書館はいつもより混雑します。","romaji":"Shiken shuukan to mo naru to, toshokan wa itsumo yori konzatsu shimasu.","en":"When exam week arrives, the library gets more crowded than usual.","id":"Saat minggu ujian tiba, perpustakaan menjadi lebih ramai dari biasanya."}]},{"pattern":"Noun ともなれば (〜to mo nareba)","meaning":"Expresses 'if it comes to', 'when', or 'once'.","meaningId":"Menyatakan 'jika sampai', 'kapan', atau 'sekali'.","formation":"Noun + ともなれば","formationId":"Kata benda + ともなれば","examples":[{"jp":"試験ともなれば、大抵の人が緊張するものです。","romaji":"Shiken to mo nareba, taitei no hito ga kinchou suru mono desu.","en":"When it comes to exams, most people get nervous.","id":"Saat menghadapi ujian, kebanyakan orang merasa gugup."},{"jp":"彼がリーダーともなれば、チームの性能はさらに向上するでしょう。","romaji":"Kare ga riidaa to mo nareba, chiimu no seinou wa sara ni koujou suru deshou.","en":"If he becomes the leader, the team's performance will improve even more.","id":"Jika ia menjadi pemimpin, performa tim akan semakin meningkat."},{"jp":"夏休みともなれば、観光地はいつも人であふれている。","romaji":"Natsuyasumi to mo nareba, kankouchi wa itsumo hito de afurete iru.","en":"When it comes to summer vacation, tourist spots are always packed with people.","id":"Jika berbicara tentang liburan musim panas, tempat-tempat wisata selalu dipadati orang."},{"jp":"結婚ともなれば、ただ二人が愛し合っているだけではすまされない事情も多い。","romaji":"Kekkon to mo nareba, tada futari ga aishiatte iru dake de wa sumasarenai jijou mo oi.","en":"When it comes to marriage, there are often issues that can’t be solved by love alone.","id":"Dalam pernikahan, sering kali ada permasalahan yang tidak bisa diselesaikan hanya dengan cinta."}]},{"pattern":"Noun と相まって","meaning":"Used to express 'in combination with', 'together with', 'along with'.","meaningId":"Digunakan untuk menyatakan 'dalam kombinasi dengan', 'bersama dengan', 'bersama dengan'.","formation":"Noun + と相まって","formationId":"Kata benda + と相まって","examples":[{"jp":"天気の良さと相まって、ピクニックは大成功でした。","romaji":"Tenki no yosa to aimatte, pikunikku wa daiseikou deshita.","en":"In combination with the good weather, the picnic was a great success.","id":"Dikombinasikan dengan cuaca yang bagus, piknik tersebut sukses besar."},{"jp":"努力と運と相まって、彼は試験に合格しました。","romaji":"Doryoku to un to aimatte, kare wa shiken ni goukaku shimashita.","en":"Thanks to both effort and luck, he passed the exam.","id":"Berkat usaha dan keberuntungan, dia lulus ujian."},{"jp":"ひまわり油とガーリックと相まって、この料理は美味しいです。","romaji":"Himawari abura to gaarikku to aimatte, kono ryouri wa oishii desu.","en":"Combined with sunflower oil and garlic, this dish is delicious.","id":"Dikombinasikan dengan minyak bunga matahari dan bawang putih, hidangan ini lezat."},{"jp":"新しい技術と経験と相まって、私たちはこの問題を克服できました。","romaji":"Atarashii gijutsu to keiken to aimatte, watashitachi wa kono mondai o kokufuku dekimashita.","en":"Together with new technology and experience, we were able to overcome this problem.","id":"Bersama dengan teknologi dan pengalaman baru, kami mampu mengatasi masalah ini."}]},{"pattern":"Noun なくして～はない","meaning":"Expresses 'without ~, there can't be ~'; 'can't do ~ without first doing ~'.","meaningId":"Menyatakan 'tanpa ~, tidak mungkin ada ~'; 'tidak dapat melakukan ~ tanpa terlebih dahulu melakukan ~'.","formation":"Noun + なくして + Sentence ～はない","formationId":"Kata Benda + なくして + Kalimat ～はない","examples":[{"jp":"努力なくして成功はない。","romaji":"Doryoku nakushite seikou wa nai.","en":"There is no success without effort.","id":"Tidak ada kesuksesan tanpa usaha."},{"jp":"時間なくして完璧な作品は作れない。","romaji":"Jikan nakushite kanpeki na sakuhin wa tsukurenai.","en":"You cannot create a perfect work without time.","id":"Anda tidak dapat menciptakan sebuah karya sempurna tanpa waktu."},{"jp":"経験なくして成長はない。","romaji":"Keiken nakushite seichou wa nai.","en":"There is no growth without experience.","id":"Tidak ada pertumbuhan tanpa pengalaman."},{"jp":"リーダーシップなくしてグループの成功はない。","romaji":"Riidaashippu nakushite guruupu no seikou wa nai.","en":"Without leadership, there can be no success for the group.","id":"Tanpa kepemimpinan, tidak akan ada kesuksesan bagi kelompok."}]},{"pattern":"Noun なしでは～ない","meaning":"Expresses the necessity of something; 'cannot do without', 'not possible without'.","meaningId":"Mengungkapkan perlunya sesuatu; 'tidak dapat dilakukan tanpa', 'tidak mungkin tanpa'.","formation":"Noun + なしでは～ない","formationId":"Kata benda + なしでは～ない","examples":[{"jp":"水なしでは生きられない。","romaji":"Mizu nashi de wa ikirarenai.","en":"We cannot live without water.","id":"Kita tidak bisa hidup tanpa air."},{"jp":"彼の助けなしでは、この問題を解決することはできない。","romaji":"Kare no tasuke nashi de wa, kono mondai o kaiketsu suru koto wa dekinai.","en":"Without his help, I cannot solve this problem.","id":"Tanpa bantuannya, saya tidak dapat menyelesaikan masalah ini."},{"jp":"コンピュータなしでは、現代のビジネスは成り立たない。","romaji":"Konpyuuta nashi de wa, gendai no bijinesu wa naritatanai.","en":"Modern business cannot function without computers.","id":"Bisnis modern tidak dapat berfungsi tanpa komputer."},{"jp":"友情なしでは、人生は退屈だろう。","romaji":"Yuujou nashi de wa, jinsei wa taikutsu darou.","en":"Life would be boring without friendship.","id":"Hidup akan membosankan tanpa persahabatan."}]},{"pattern":"Noun なしには～ない","meaning":"Means 'without', 'cannot do without', 'not possible without'.","meaningId":"Berarti 'tanpa', 'tidak dapat dilakukan tanpa', 'tidak mungkin tanpa'.","formation":"Noun + なしには + Verb-negative","formationId":"Kata Benda + なしには + Kata Kerja-negatif","examples":[{"jp":"お金なしには生活ができない。","romaji":"Okane nashi ni wa seikatsu ga dekinai.","en":"I cannot get by without money.","id":"Saya tidak bisa hidup tanpa uang."},{"jp":"愛情なしには子育てができない。","romaji":"Aijou nashi ni wa kosodate ga dekinai.","en":"You cannot raise a child without love.","id":"Anda tidak dapat membesarkan anak tanpa cinta."},{"jp":"彼なしにはこのプロジェクトを進められない。","romaji":"Kare nashi ni wa kono purojekuto o susumerarenai.","en":"Without him, I cannot move this project forward.","id":"Tanpa dia, saya tidak dapat memajukan proyek ini."},{"jp":"水なしには生きていけない。","romaji":"Mizu nashi ni wa ikite ikenai.","en":"I cannot live without water.","id":"Saya tidak bisa hidup tanpa air."}]},{"pattern":"Noun ならいざ知らず","meaning":"Expresses 'maybe X is possible, but Y is definitely not'. Often 'let alone...'.","meaningId":"Menyatakan 'mungkin X mungkin, tapi Y pasti tidak'. Seringkali 'apalagi...'.","formation":"Noun1 + ならいざ知らず + Noun2 (comment)","formationId":"Kata Benda1 + ならいざ知らず + Kata Benda2 (komentar)","examples":[{"jp":"数学ならいざ知らず、物理なんて全然わからない。","romaji":"Suugaku nara iza shirazu, butsuri nante zenzen wakaranai.","en":"Math might be manageable, but as for physics, I'm completely clueless.","id":"Matematika mungkin bisa ditangani, tetapi untuk fisika, saya sama sekali tidak mengerti."},{"jp":"5キロならいざ知らず、10キロなんて走れません。","romaji":"Go kiro nara iza shirazu, juu kiro nante hashiremasen.","en":"Maybe I could run 5 kilometers, but 10 kilometers is out of the question.","id":"Mungkin saya bisa berlari sejauh 5 kilometer, tetapi 10 kilometer adalah hal yang mustahil."},{"jp":"日本語ならいざ知らず、中国語なんて話せない。","romaji":"Nihongo nara iza shirazu, chuugokugo nante hanasenai.","en":"I might be able to speak Japanese, but Chinese is impossible for me.","id":"Saya mungkin bisa berbicara bahasa Jepang, tetapi bahasa Mandarin tidak mungkin bagi saya."},{"jp":"冷たい水ならいざ知らず、熱い水で泳ぐなんて考えたこともない。","romaji":"Tsumetai mizu nara iza shirazu, atsui mizu de oyogu nante kangaeta koto mo nai.","en":"Maybe cold water, but swimming in hot water never even crossed my mind.","id":"Mungkin airnya dingin, tapi berenang di air panas bahkan tidak pernah terlintas di benak saya."}]},{"pattern":"Noun + ならでは","meaning":"Expresses something unique or characteristic only of that noun; 'only found in', 'only possible with'.","meaningId":"Mengekspresikan sesuatu yang unik atau karakteristik hanya dari kata benda itu; 'hanya ditemukan di', 'hanya mungkin dengan'.","formation":"Noun + ならでは","formationId":"Kata benda + ならでは","examples":[{"jp":"これは日本ならではの風景ですね。","romaji":"Kore wa Nihon nara dewa no fuukei desu ne.","en":"This is a landscape you can only find in Japan.","id":"Ini adalah pemandangan yang hanya bisa Anda temukan di Jepang."},{"jp":"新鮮な魚はこの町ならではの特産品です。","romaji":"Shinsen na sakana wa kono machi nara dewa no tokusanhin desu.","en":"Fresh fish is a specialty unique to this town.","id":"Ikan segar adalah makanan khas kota ini."},{"jp":"彼の技術は彼ならではのものだ。","romaji":"Kare no gijutsu wa kare nara dewa no mono da.","en":"His skills are unique to him.","id":"Keahliannya unik baginya."},{"jp":"この手作りの一品は、彼女ならではのものです。","romaji":"Kono tezukuri no ippin wa, kanojo nara dewa no mono desu.","en":"This handmade item is something only she could produce.","id":"Barang buatan tangan ini adalah sesuatu yang hanya bisa dia hasilkan."}]},{"pattern":"Noun なり Noun なり","meaning":"Lists alternatives of the same kind; 'either A or B', 'A or B, for example'.","meaningId":"Mencantumkan alternatif-alternatif yang sejenis; 'A atau B', 'A atau B, misalnya'.","formation":"Noun + なり + Noun + なり","formationId":"Kata Benda + なり + Kata Benda + なり","examples":[{"jp":"映画なり、音楽なり、何か趣味はありますか。","romaji":"Eiga nari, ongaku nari, nanika shumi wa arimasu ka?","en":"Do you have any hobbies, such as movies or music?","id":"Apakah Anda memiliki hobi, seperti film atau musik?"},{"jp":"紅茶なり、コーヒーなり、何か飲み物をください。","romaji":"Koucha nari, koohii nari, nanika nomimono o kudasai.","en":"Please give me something to drink, like tea or coffee.","id":"Tolong beri saya sesuatu untuk diminum, seperti teh atau kopi."},{"jp":"パンなり、おにぎりなり、何か食べてください。","romaji":"Pan nari, onigiri nari, nanika tabete kudasai.","en":"Please eat something—bread, onigiri, or whatever you’d like.","id":"Silakan makan sesuatu—roti, onigiri, atau apa pun yang Anda suka."},{"jp":"タクシーなり、バスなりに乗って来てください。","romaji":"Takushii nari, basu nari ni notte kite kudasai.","en":"Please come by either taxi or bus.","id":"Silakan datang dengan taksi atau bus."}]},{"pattern":"Noun なりとも","meaning":"Indicates even a small amount or degree; 'at least', 'even a little'.","meaningId":"Menunjukkan jumlah atau derajat yang kecil; 'setidaknya', 'walaupun sedikit'.","formation":"Noun + なりとも","formationId":"Kata benda + なりとも","examples":[{"jp":"時間が限られているので、一時間なりとも練習すべきだ。","romaji":"Jikan ga kagirarete iru node, ichi-jikan nari tomo renshuu subeki da.","en":"Since time is limited, you should practice for at least an hour.","id":"Karena waktu terbatas, Anda harus berlatih setidaknya selama satu jam."},{"jp":"彼には一言なりとも謝罪の言葉を聞きたい。","romaji":"Kare ni wa hitokoto nari tomo shazai no kotoba o kikitai.","en":"I’d like to hear at least a word of apology from him.","id":"Saya ingin mendengar setidaknya satu kata permintaan maaf darinya."},{"jp":"このプロジェクトには、一人なりともメンバーが必要だ。","romaji":"Kono purojekuto ni wa, hitori nari tomo membaa ga hitsuyou da.","en":"We need at least one member for this project.","id":"Kami membutuhkan setidaknya satu anggota untuk proyek ini."},{"jp":"あなたには、一言なりとも感謝の言葉を述べたい。","romaji":"Anata ni wa, hitokoto nari tomo kansha no kotoba o nobetai.","en":"I want to offer at least a word of gratitude to you.","id":"Saya ingin menyampaikan setidaknya satu kata terima kasih kepada Anda."}]},{"pattern":"Noun に Noun を重ねて","meaning":"This expression is used to describe repeated actions or states, 'one after another' or 'pile up'.","meaningId":"Ungkapan ini digunakan untuk menggambarkan tindakan atau keadaan yang berulang, 'satu demi satu' atau 'menumpuk'.","formation":"Noun に Noun を重ねて","formationId":"Kata benda に Kata benda を重ねて","examples":[{"jp":"彼女は失敗に失敗を重ねて、とうとう会社を辞めた。","romaji":"Kanojo wa shippai ni shippai wo kasanete, toutou kaisha wo yameta.","en":"She piled up failures upon failures and finally quit the company.","id":"Dia menumpuk kegagalan demi kegagalan dan akhirnya keluar dari perusahaan."},{"jp":"仕事に仕事を重ねて、彼は疲れ果てた。","romaji":"Shigoto ni shigoto wo kasanete, kare wa tsukarehateta.","en":"He piled up work upon work and was completely exhausted.","id":"Dia menumpuk pekerjaan demi pekerjaan dan benar-benar kelelahan."},{"jp":"彼は試験に不合格になり、失望に失望を重ねていた。","romaji":"Kare wa shiken ni fugōkaku ni nari, shitsubō ni shitsubō wo kasanete ita.","en":"He failed the exam and kept piling up his disappointments.","id":"Dia gagal dalam ujian dan terus menumpuk kekecewaannya."},{"jp":"彼は問題に問題を重ねて、とうとう退学になった。","romaji":"Kare wa mondai ni mondai wo kasanete, toutou taigaku ni natta.","en":"He kept piling up problems upon problems until he was finally expelled.","id":"Dia terus menumpuk masalah demi masalah hingga akhirnya dia dikeluarkan."}]},{"pattern":"Noun にあっては","meaning":"Indicates a specific situation or environment in which something happens or is the case.","meaningId":"Menunjukkan situasi atau lingkungan tertentu di mana sesuatu terjadi atau terjadi.","formation":"Noun + にあっては","formationId":"Kata benda + にあっては","examples":[{"jp":"戦争時にあっては、すべての人々が困難に直面していました。","romaji":"Sensouji ni atte wa, subete no hito ga konnan ni chokumen shiteimashita.","en":"In wartime, all people were facing difficulties.","id":"Di masa perang, semua orang menghadapi kesulitan."},{"jp":"経済危機にあっては、多くの企業が倒産の危機に瀕している。","romaji":"Keizai kiki ni atte wa, ooku no kigyou ga tousan no kiki ni hinshite iru.","en":"In the economic crisis, many companies are on the verge of bankruptcy.","id":"Dalam krisis ekonomi, banyak perusahaan berada di ambang kebangkrutan."},{"jp":"不況下にあっては、どの企業も経費削減を迫られている。","romaji":"Fukyouka ni atte wa, dono kigyou mo keihi sakugen o semararete iru.","en":"In times of recession, every company is forced to cut costs.","id":"Di masa resesi, setiap perusahaan terpaksa memangkas biaya."},{"jp":"改革期にあっては、新しいアイデアを大切にする必要がある。","romaji":"Kaikaku ki ni atte wa, atarashii aidea o taisetsu ni suru hitsuyou ga aru.","en":"In a period of reform, it's necessary to value new ideas.","id":"Dalam masa reformasi, penting untuk menghargai ide-ide baru."}]},{"pattern":"Noun にあるまじき Noun","meaning":"Expresses the idea of 'unfitting', 'unbecoming' or 'inappropriate'.","meaningId":"Mengekspresikan gagasan 'tidak pantas', 'tidak pantas' atau 'tidak pantas'.","formation":"Noun1 にあるまじき Noun2","formationId":"Kata benda1 にあるまじき Kata benda2","examples":[{"jp":"彼は教師にあるまじき言動をとった。","romaji":"Kare wa kyoushi ni aru majiki gendou wo totta.","en":"He took actions that are unbecoming of a teacher.","id":"Dia mengambil tindakan yang tidak pantas dilakukan seorang guru."},{"jp":"これは人間にあるまじき行為だ。","romaji":"Kore wa ningen ni aru majiki koui da.","en":"This is an act that is unfitting for a human.","id":"Ini adalah tindakan yang tidak pantas dilakukan manusia."},{"jp":"彼女は社長にあるまじき振る舞いをした。","romaji":"Kanojo wa shachou ni aru majiki furumai wo shita.","en":"She behaved in a way that is unbecoming of a president.","id":"Dia berperilaku dengan cara yang tidak pantas bagi seorang presiden."},{"jp":"それは社会人にあるまじき行動だ。","romaji":"Sore wa shakaijin ni aru majiki koudou da.","en":"That is a behaviour that is not suitable for an adult.","id":"Itu adalah perilaku yang tidak pantas dilakukan oleh orang dewasa."}]},{"pattern":"Noun にして","meaning":"Expresses the idea 'even for', 'even though', or 'in spite of'.","meaningId":"Mengekspresikan gagasan 'bahkan untuk', 'meskipun', atau 'meskipun'.","formation":"Noun + にして","formationId":"Kata benda + にして","examples":[{"jp":"彼は医者にしてその基本的な知識がないのが信じられない。","romaji":"Kare wa isha ni shite sono kihonteki na chishiki ga nai no ga shinjirarenai.","en":"I can't believe that even as a doctor, he doesn't have that basic knowledge.","id":"Saya tidak percaya bahkan sebagai seorang dokter, dia tidak memiliki pengetahuan dasar itu."},{"jp":"彼は経験豊富な運転手にして、事故を起こした。","romaji":"Kare wa keiken houfu na untenshu ni shite, jiko wo okoshita.","en":"Even as an experienced driver, he had an accident.","id":"Bahkan sebagai pengemudi berpengalaman, dia mengalami kecelakaan."},{"jp":"彼は成績優秀な生徒にして、その問題が解けなかった。","romaji":"Kare wa seiseki yuushuu na seito ni shite, sono mondai ga tokenakatta.","en":"Even as an excellent student, he couldn't solve that problem.","id":"Bahkan sebagai siswa yang berprestasi, dia tidak dapat menyelesaikan masalah itu."},{"jp":"彼は勉強家にして、その問題を理解できなかった。","romaji":"Kare wa benkyouka ni shite, sono mondai o rikai dekinakatta.","en":"Even as a studious person, he could not understand that problem.","id":"Bahkan sebagai orang yang rajin belajar, dia tidak dapat memahami masalah itu."}]},{"pattern":"Noun にして初めて","meaning":"Expresses 'only when/after... for the first time'.","meaningId":"Menyatakan 'hanya ketika/setelah... untuk pertama kalinya'.","formation":"Noun + にして初めて","formationId":"Kata benda + にして初めて","examples":[{"jp":"大人にして初めて、親の苦労が分かった。","romaji":"Otona ni shite hajimete, oya no kurou ga wakatta.","en":"Only when I became an adult did I understand my parents' struggles for the first time.","id":"Baru ketika aku dewasa barulah aku memahami perjuangan orang tuaku untuk pertama kalinya."},{"jp":"彼は40歳にして初めて、海外旅行を経験した。","romaji":"Kare wa yonjuu-sai ni shite hajimete, kaigai ryokou o keiken shita.","en":"Only when he turned 40 did he travel abroad for the first time.","id":"Baru ketika dia berusia 40 tahun dia bepergian ke luar negeri untuk pertama kalinya."},{"jp":"彼女は親にして初めて、子育ての大変さを理解した。","romaji":"Kanojo wa oya ni shite hajimete, kosodate no taihensa o rikai shita.","en":"It was only after she became a parent that she realized how challenging raising a child can be.","id":"Baru setelah dia menjadi orang tua barulah dia menyadari betapa menantangnya membesarkan seorang anak."},{"jp":"社長にして初めて、会社全体の重責を痛感した。","romaji":"Shachou ni shite hajimete, kaisha zentai no juuseki o tsuukan shita.","en":"Only when he became president did he feel the full weight of responsibility for the entire company.","id":"Hanya ketika dia menjadi presiden barulah dia merasakan tanggung jawab penuh atas seluruh perusahaan."}]},{"pattern":"Noun にすら (〜ni sura)","meaning":"Expresses the concept of 'even'; 'even in', 'even as', 'even to'.","meaningId":"Mengungkapkan konsep 'genap'; 'bahkan di', 'bahkan sebagai', 'bahkan sampai'.","formation":"Noun + にすら","formationId":"Kata benda + にすら","examples":[{"jp":"彼にすらその問題は解けなかった。","romaji":"Kare ni sura sono mondai wa tokenakatta.","en":"Even he could not solve that problem.","id":"Bahkan dia tidak bisa menyelesaikan masalah itu."},{"jp":"彼女はテストにすら合格しなかった。","romaji":"Kanojo wa tesuto ni sura goukaku shinakatta.","en":"She did not even pass the test.","id":"Dia bahkan tidak lulus ujian."},{"jp":"この犬は自分の名前にすら反応しない。","romaji":"Kono inu wa jibun no namae ni sura hannou shinai.","en":"This dog doesn't even respond to its own name.","id":"Anjing ini bahkan tidak merespon namanya sendiri."},{"jp":"彼にすら話す余裕がなかった。","romaji":"Kare ni sura hanasu yoyuu ga nakatta.","en":"I didn't even have the time to talk to him.","id":"Aku bahkan tidak punya waktu untuk berbicara dengannya."}]},{"pattern":"Noun にとどまらず～も","meaning":"This expresses the idea of 'not only...but also', 'not stopping at...'.","meaningId":"Hal ini mengungkapkan gagasan 'tidak hanya...tetapi juga', 'tidak berhenti pada...'.","formation":"Noun + にとどまらず + Noun + も","formationId":"Kata Benda + にとどまらず + Kata Benda + も","examples":[{"jp":"このアプリは、日本語にとどまらず、他の言語もサポートしています。","romaji":"Kono apuri wa, nihongo ni todomarazu, hoka no gengo mo sapooto shite imasu.","en":"This app not only supports Japanese, but also other languages.","id":"Aplikasi ini tidak hanya mendukung bahasa Jepang, tetapi juga bahasa lainnya."},{"jp":"彼は、音楽にとどまらず、映画製作にも興味がある。","romaji":"Kare wa, ongaku ni todomarazu, eiga seisaku ni mo kyoumi ga aru.","en":"He is not only interested in music, but also in filmmaking.","id":"Ia tidak hanya tertarik pada musik, tetapi juga pembuatan film."},{"jp":"彼の影響は、家族にとどまらず、地域全体にも及んでいます。","romaji":"Kare no eikyou wa, kazoku ni todomarazu, chiiki zentai ni mo oyonde imasu.","en":"His influence extends not only to his family but also to the entire region.","id":"Pengaruhnya tidak hanya meluas ke keluarganya tetapi juga ke seluruh wilayah."},{"jp":"彼女の才能は、絵画にとどまらず、文学にも及ぶ。","romaji":"Kanojo no sainou wa, kaiga ni todomarazu, bungaku ni mo oyobu.","en":"Her talent extends not only to painting, but also to literature.","id":"Bakatnya tidak hanya terbatas pada seni lukis, tetapi juga sastra."}]},{"pattern":"Noun にひきかえ Noun は","meaning":"Represents 'in contrast to', 'as opposed to'.","meaningId":"Mewakili 'berlawanan dengan', 'sebagai lawan'.","formation":"Noun 1 + にひきかえ + Noun 2 + は","formationId":"Kata Benda 1 + にひきかえ + Kata Benda 2 + は","examples":[{"jp":"彼の親切さにひきかえ、彼女は無感情だ。","romaji":"Kare no shinsetsusa ni hikikae, kanojo wa mukanjou da.","en":"In contrast to his kindness, she is emotionless.","id":"Berbeda dengan kebaikannya, dia tidak memiliki emosi."},{"jp":"夏にひきかえ、冬は雪で寒い。","romaji":"Natsu ni hikikae, fuyu wa yuki de samui.","en":"As opposed to summer, winter is cold with snow.","id":"Berbeda dengan musim panas, musim dingin lebih dingin disertai salju."},{"jp":"日本の駅にひきかえ、アメリカの駅は広い。","romaji":"Nihon no eki ni hikikae, Amerika no eki wa hiroi.","en":"As opposed to Japanese stations, American stations are wide.","id":"Berbeda dengan stasiun Jepang, stasiun Amerika lebih luas."},{"jp":"昔にひきかえ、現代はテクノロジーが進歩した。","romaji":"Mukashi ni hikikae, gendai wa tekunorojii ga shinpo shita.","en":"As opposed to the old days, modern times have advanced technology.","id":"Berbeda dengan zaman dahulu, zaman modern sudah memiliki teknologi yang canggih."}]},{"pattern":"Noun にもまして (〜ni mo mashite)","meaning":"This expresses 'Even more than; exceeding'.","meaningId":"Hal ini mengungkapkan 'Bahkan lebih dari; melebihi'.","formation":"Noun + にもまして","formationId":"Kata benda + にもまして","examples":[{"jp":"私は彼にもまして、音楽を愛しています。","romaji":"Watashi wa kare ni mo mashite, ongaku o aishiteimasu.","en":"I love music even more than he does.","id":"Saya lebih menyukai musik daripada dia."},{"jp":"彼女は年齢にもまして、経験豊富です。","romaji":"Kanojo wa nenrei ni mo mashite, keiken houfu desu.","en":"She has even more experience than her age would suggest.","id":"Dia memiliki lebih banyak pengalaman daripada usianya."},{"jp":"今日は昨日にもまして寒いです。","romaji":"Kyou wa kinou ni mo mashite samui desu.","en":"It is even colder today than it was yesterday.","id":"Hari ini bahkan lebih dingin dibandingkan kemarin."},{"jp":"このビルは高さにもまして、美しい設計が有名です。","romaji":"Kono biru wa takasa ni mo mashite, utsukushii sekkei ga yuumei desu.","en":"This building is famous for its beautiful design even more than its height.","id":"Bangunan ini terkenal dengan desainnya yang indah bahkan melebihi tingginya."}]},{"pattern":"Noun によらず","meaning":"Regardless of, irrespective of.","meaningId":"Terlepas dari itu, terlepas dari itu.","formation":"Noun + によらず","formationId":"Kata benda + によらず","examples":[{"jp":"結果は勉強時間によらず変わらないでしょう。","romaji":"Kekka wa benkyou jikan ni yorazu kawaranai deshou.","en":"The result will not change regardless of the study time.","id":"Hasilnya tidak akan berubah berapapun waktu belajarnya."},{"jp":"季節によらず、この地域は常に暖かいです。","romaji":"Kisetsu ni yorazu, kono chiiki wa tsune ni atatakai desu.","en":"This region is always warm, regardless of the season.","id":"Wilayah ini selalu hangat, apapun musimnya."},{"jp":"年齢によらず、皆が楽しめるイベントです。","romaji":"Nenrei ni yorazu, mina ga tanoshimeru ibento desu.","en":"It is an event that everyone can enjoy, regardless of age.","id":"Ini adalah acara yang dapat dinikmati semua orang, tanpa memandang usia."},{"jp":"国籍によらず、誰でも参加できます。","romaji":"Kokuseki ni yorazu, dare demo sanka dekimasu.","en":"Anyone can participate, regardless of nationality.","id":"Siapa pun dapat berpartisipasi, apa pun kebangsaannya."}]},{"pattern":"Noun に先駆けて (〜ni saki gakete)","meaning":"Meaning 'ahead of', 'before', or 'preceding in time'.","meaningId":"Artinya 'sebelum', 'sebelum', atau 'sebelumnya'.","formation":"Noun + に先駆けて","formationId":"Kata benda + に先駆けて","examples":[{"jp":"この映画は日本に先駆けて、アメリカで公開されました。","romaji":"Kono eiga wa Nippon ni sakigakete, Amerika de koukai saremashita.","en":"This film was released in America ahead of Japan.","id":"Film ini dirilis di Amerika sebelum Jepang."},{"jp":"彼は周りの人々に先駆けて、その発表を聞いた。","romaji":"Kare wa mawari no hitobito ni sakigakete, sono happyou o kiita.","en":"He heard the announcement before the people around him.","id":"Dia mendengar pengumuman itu di hadapan orang-orang di sekitarnya."},{"jp":"ジョンソンさんは他の参加者に先駆けて、会場に到着しました。","romaji":"Jonson-san wa hoka no sankasha ni sakigakete, kaijou ni touchaku shimashita.","en":"Mr. Johnson arrived at the venue ahead of the other participants.","id":"Tuan Johnson tiba di tempat tersebut lebih dulu dari peserta lainnya."},{"jp":"彼女は同級生に先駆けて卒業することができました。","romaji":"Kanojo wa doukyuusei ni sakigakete sotsugyou suru koto ga dekimashita.","en":"She was able to graduate before her classmates.","id":"Dia mampu lulus sebelum teman-teman sekelasnya."}]},{"pattern":"Noun に即した Noun","meaning":"Expresses the idea of 'in accordance with', 'based on'.","meaningId":"Mengungkapkan gagasan 'sesuai dengan', 'berdasarkan'.","formation":"Noun1 + に即した + Noun2","formationId":"Kata Benda1 + に即した + Kata Benda2","examples":[{"jp":"社会のニーズに即した教育改革が必要だ。","romaji":"Shakai no niizu ni sokushita kyouiku kaikaku ga hitsuyou da.","en":"We need an educational reform that is in accordance with the needs of society.","id":"Kita memerlukan reformasi pendidikan yang sesuai dengan kebutuhan masyarakat."},{"jp":"国際法に即した対応をとるべきだ。","romaji":"Kokusaihou ni sokushita taiou wo toru beki da.","en":"We should respond in accordance with international law.","id":"Kita harus merespons sesuai dengan hukum internasional."},{"jp":"チームのポリシーに即した行動を取りましょう。","romaji":"Chiimu no porishii ni sokushita koudou wo torimashou.","en":"Let's take action in accordance with the team's policy.","id":"Mari kita mengambil tindakan sesuai dengan kebijakan tim."},{"jp":"現実に即した計画を立てなければならない。","romaji":"Genjitsu ni sokushita keikaku wo tatenakereba naranai.","en":"We must make a plan based on reality.","id":"Kita harus membuat rencana berdasarkan kenyataan."}]},{"pattern":"Noun に即して Verb (〜ni soku shite ~)","meaning":"The grammar point Noun に即して Verb is used to mean 'to act in accordance with', 'in line with' or 'based on'.","meaningId":"Poin tata bahasa Kata Benda に即して Kata kerja digunakan untuk berarti 'bertindak sesuai dengan', 'sejalan dengan' atau 'berdasarkan'.","formation":"Noun + に即して + Verb","formationId":"Kata Benda + に即して + Kata Kerja","examples":[{"jp":"会社のポリシーに即して行動しましょう。","romaji":"Kaisha no porishii ni soku shite koudou shimashou.","en":"Let's act in accordance with the company's policy.","id":"Mari bertindak sesuai dengan kebijakan perusahaan."},{"jp":"法律に即して判断を下すことが重要です。","romaji":"Houritsu ni soku shite hantei o kudasu koto ga juuyou desu.","en":"It's important to make judgments in accordance with the law.","id":"Penting untuk membuat penilaian sesuai dengan hukum."},{"jp":"彼の意見に即して、プランを変更しました。","romaji":"Kare no iken ni soku shite, puran o henkou shimashita.","en":"Based on his opinion, we changed the plan.","id":"Berdasarkan pendapatnya, kami mengubah rencana."},{"jp":"ルールに即して行動すれば、問題は起きません。","romaji":"Ruuru ni soku shite koudou sureba, mondai wa okimasen.","en":"If we act in accordance with the rules, there will be no problem.","id":"Kalau kita bertindak sesuai aturan, tidak akan ada masalah."}]},{"pattern":"Noun に言わせれば","meaning":"Expresses 'according to', 'if you ask', 'in the opinion of'.","meaningId":"Menyatakan 'menurut', 'jika Anda bertanya', 'menurut pendapat'.","formation":"Noun + に言わせれば","formationId":"Kata benda + に言わせれば","examples":[{"jp":"先生に言わせれば、毎日勉強することが重要だと言う。","romaji":"Sensei ni iwasereba, mainichi benkyou suru koto ga juuyou da to iu.","en":"According to the teacher, it's important to study every day.","id":"Menurut guru, penting untuk belajar setiap hari."},{"jp":"彼に言わせれば、早く結婚する方がいいと思っている。","romaji":"Kare ni iwasereba, hayaku kekkon suru hou ga ii to omotte iru.","en":"If you ask him, he thinks it's better to get married early.","id":"Kalau ditanya, menurutnya lebih baik menikah dini."},{"jp":"評論家に言わせれば、この映画は今年の最高の映画だそうだ。","romaji":"Hyouronka ni iwasereba, kono eiga wa kotoshi no saikou no eiga da sou da.","en":"According to the critic, this movie is the best of the year.","id":"Menurut kritikus, film ini adalah yang terbaik tahun ini."},{"jp":"父に言わせれば、海外で働く経験はとても価値がある。","romaji":"Chichi ni iwasereba, kaigai de hataraku keiken wa totemo kachi ga aru.","en":"In my father's opinion, the experience of working overseas is very valuable.","id":"Menurut ayah saya, pengalaman bekerja di luar negeri sangat berharga."}]},{"pattern":"Noun に限ったことではない (〜ni kagitta koto dewa nai)","meaning":"Indicates that something is not only limited to; 'not only', 'not just'.","meaningId":"Menunjukkan bahwa sesuatu tidak hanya terbatas pada; 'tidak hanya', 'tidak hanya'.","formation":"Noun + に限ったことではない","formationId":"Kata Benda + に限ったことではない","examples":[{"jp":"この問題は日本に限ったことではない。","romaji":"Kono mondai wa Nihon ni kagitta koto dewa nai.","en":"This issue is not only limited to Japan.","id":"Permasalahan ini tidak hanya terjadi di Jepang saja."},{"jp":"英語はアメリカに限ったことではない。","romaji":"Eigo wa Amerika ni kagitta koto dewa nai.","en":"English is not just limited to America.","id":"Bahasa Inggris tidak hanya terbatas di Amerika."},{"jp":"スマホの依存症は若者に限ったことではない。","romaji":"Sumaho no izonshou wa wakamono ni kagitta koto dewa nai.","en":"Smartphone addiction is not only limited to young people.","id":"Kecanduan smartphone tidak hanya terbatas pada generasi muda saja."},{"jp":"地球温暖化は我々人間に限ったことではない。","romaji":"Chikyuu ondanka wa wareware ningen ni kagitta koto dewa nai.","en":"Global warming is not just limited to us humans.","id":"Pemanasan global tidak hanya terjadi pada kita manusia saja."}]},{"pattern":"Noun に限ったことでもない","meaning":"'Not limited to'; 'not just', 'not exclusively'.","meaningId":"'Tidak terbatas pada'; 'tidak hanya', 'tidak eksklusif'.","formation":"Noun + に限ったことでもない","formationId":"Kata Benda + に限ったことでもない","examples":[{"jp":"この試験が難しいのは、数学に限ったことでもない。","romaji":"Kono shiken ga muzukashii no wa, suugaku ni kagitta koto demo nai.","en":"The exam being difficult is not limited to just math.","id":"Sulitnya ujian tidak hanya sebatas matematika saja."},{"jp":"彼女が可愛いのは顔だけに限ったことでもない。性格も好きだ。","romaji":"Kanojo ga kawaii no wa kao dake ni kagitta koto demo nai. Seikaku mo suki da.","en":"Her being cute is not just limited to her face. I also like her personality.","id":"Kelucuannya tidak hanya terbatas pada wajahnya saja. Saya juga menyukai kepribadiannya."},{"jp":"その問題が起こるのは、我々の国に限ったことでもない。","romaji":"Sono mondai ga okoru no wa, wareware no kuni ni kagitta koto demo nai.","en":"The occurrence of that problem is not limited to our country.","id":"Terjadinya permasalahan tersebut tidak hanya terjadi di negara kita saja."},{"jp":"この作家の本が売れているのは日本に限ったことでもない。","romaji":"Kono sakka no hon ga urete iru no wa Nippon ni kagitta koto demo nai.","en":"The selling of this author's books is not limited to just Japan.","id":"Penjualan buku karya penulis ini tidak hanya terbatas di Jepang saja."}]},{"pattern":"Noun に限る","meaning":"Expresses the idea that 'nothing but', 'nothing is better than'.","meaningId":"Mengekspresikan gagasan bahwa 'tidak ada yang lain selain', 'tidak ada yang lebih baik dari'.","formation":"Noun + に限る","formationId":"Kata benda + に限る","examples":[{"jp":"こういう時には家族に話すに限る。","romaji":"Kou iu toki ni wa kazoku ni hanasu ni kagiru.","en":"At times like this, there's nothing better than talking to your family.","id":"Di saat seperti ini, tidak ada yang lebih baik daripada berbicara dengan keluarga Anda."},{"jp":"寒い冬には温かいお茶に限る。","romaji":"Samui fuyu ni wa atatakai ocha ni kagiru.","en":"In cold winter, there's nothing better than warm tea.","id":"Di musim dingin, tidak ada yang lebih baik dari teh hangat."},{"jp":"疲れたときは、よい睡眠に限る。","romaji":"Tsukareta toki wa, yoi suimin ni kagiru.","en":"When you are tired, nothing is better than a good sleep.","id":"Saat Anda lelah, tidak ada yang lebih baik daripada tidur yang nyenyak."},{"jp":"ダイエットするなら、運動に限る。","romaji":"Daietto suru nara, undou ni kagiru.","en":"If you want to go on a diet, there is nothing better than exercise.","id":"Jika Anda ingin melakukan diet, tidak ada yang lebih baik dari olahraga."}]},{"pattern":"Noun ぬいた Noun","meaning":"Expresses the idea of 'taking something out from something else'.","meaningId":"Mengungkapkan gagasan 'mengambil sesuatu dari sesuatu yang lain'.","formation":"Noun1 + をぬいた + Noun2","formationId":"Kata Benda1 + をぬいた + Kata Benda2","examples":[{"jp":"このサラダはにんじんをぬいたサラダです。","romaji":"Kono sarada wa ninjin o nuita sarada desu.","en":"This is a salad with the carrots removed.","id":"Ini adalah salad dengan wortel yang dibuang."},{"jp":"彼はコーヒーから砂糖をぬいた。","romaji":"Kare wa koohii kara satou o nuita.","en":"He removed the sugar from the coffee.","id":"Dia menghilangkan gula dari kopi."},{"jp":"私は料理から塩をぬいた。","romaji":"Watashi wa ryouri kara shio o nuita.","en":"I removed the salt from the cooking.","id":"Saya menghilangkan garam dari masakan."},{"jp":"彼女は服からシミをぬいた。","romaji":"Kanojo wa fuku kara shimi o nuita.","en":"She removed the stain from the clothes.","id":"Dia menghilangkan noda dari pakaiannya."}]},{"pattern":"Noun + ぬいて（~nuite)","meaning":"This is a way to express 'minus' or 'except for' some specific noun.","meaningId":"Ini adalah cara untuk menyatakan 'minus' atau 'kecuali' untuk beberapa kata benda tertentu.","formation":"Noun + ぬいて","formationId":"Kata benda + ぬいて","examples":[{"jp":"私たちは、彼ぬいて全員が集まることができました。","romaji":"Watashitachi wa, kare nuite zen'in ga atsumaru koto ga dekimashita.","en":"We were able to gather everyone except for him.","id":"Kami dapat mengumpulkan semua orang kecuali dia."},{"jp":"このレストランはお子様メニューをぬいてすべてが美味しい。","romaji":"Kono resutoran wa okosama menyuu o nuite subete ga oishii.","en":"Everything at this restaurant is delicious except for the kids' menu.","id":"Segala sesuatu di restoran ini enak kecuali menu anak-anak."},{"jp":"今日の仕事は昼休みをぬいて忙しかった。","romaji":"Kyou no shigoto wa hiruyasumi o nuite isogashikatta.","en":"Today's work was busy except for the lunch break.","id":"Pekerjaan hari ini sibuk kecuali istirahat makan siang."},{"jp":"休暇の日をぬいて、毎日彼は働きます。","romaji":"Kyuuka no hi o nuite, mainichi kare wa hatarakimasu.","en":"He works every day except for the holidays.","id":"Dia bekerja setiap hari kecuali hari libur."}]},{"pattern":"～ぬく","meaning":"Expresses the concept of doing something completely or thoroughly.","meaningId":"Mengungkapkan konsep melakukan sesuatu secara lengkap atau menyeluruh.","formation":"Verb-stem + ぬく","formationId":"Batang kata kerja + ぬく","examples":[{"jp":"彼は一日中本を読みぬく。","romaji":"Kare wa ichinichijuu hon o yominuku.","en":"He will read the book all day long.","id":"Dia akan membaca buku itu sepanjang hari."},{"jp":"私はこのプロジェクトを終わらせぬく。","romaji":"Watashi wa kono purojekuto o owarasenuku.","en":"I will finish this project completely.","id":"Saya akan menyelesaikan proyek ini sepenuhnya."},{"jp":"彼女は毎日ジムに行き、エクササイズを終わりぬく。","romaji":"Kanojo wa mainichi jim ni iki, ekusasaizu o owari nuku.","en":"She goes to the gym every day and finishes her exercise completely.","id":"Dia pergi ke gym setiap hari dan menyelesaikan latihannya sepenuhnya."},{"jp":"私たちはこのゲームを解きぬく。","romaji":"Watashitachi wa kono geemu o tokinuku.","en":"We will solve this game completely.","id":"Kami akan menyelesaikan game ini sepenuhnya."}]},{"pattern":"Noun+のいかんだ","meaning":"Depends on; up to","meaningId":"Tergantung pada; hingga","formation":"Noun + のいかんだ/Noun + のいかんでは","formationId":"Kata Benda + のいかんだ/Kata Benda + のいかんでは","examples":[{"jp":"彼が来るのいかんで決めよう。","romaji":"Kare ga kuru no ikan de kimeyou.","en":"Let's decide depending on whether he comes or not.","id":"Mari kita putuskan tergantung apakah dia datang atau tidak."},{"jp":"試験の結果のいかんで留年が決まります。","romaji":"Shiken no kekka no ikan de ryuunen ga kimarimasu.","en":"Whether you repeat a year or not depends on the test results.","id":"Apakah Anda mengulang satu tahun atau tidak tergantung pada hasil tes."},{"jp":"天気のいかんでは、ピクニックをキャンセルします。","romaji":"Tenki no ikan de wa, pikunikku o kyanseru shimasu.","en":"I'll cancel the picnic depending on the weather.","id":"Saya akan membatalkan piknik tergantung cuaca."},{"jp":"彼の回答のいかんで、我々の次の行動が決まる。","romaji":"Kare no kaitou no ikan de, wareware no tsugi no koudou ga kimaru.","en":"Our next action depends on his response.","id":"Tindakan kita selanjutnya bergantung pada tanggapannya."}]},{"pattern":"Noun のいかんでは","meaning":"It depends on the Noun","meaningId":"Itu tergantung pada Kata Benda","formation":"Noun + のいかんでは","formationId":"Kata benda + のいかんでは","examples":[{"jp":"試験の結果のいかんでは、大学の入学許可を得られるかどうかが決まります。","romaji":"Shiken no kekka no ikan dewa, daigaku no nyuugaku kyoka o erareru ka douka ga kimarimasu.","en":"Whether you can get permission to enter university depends on the result of the exam.","id":"Apakah Anda bisa mendapatkan izin masuk universitas tergantung pada hasil ujiannya."},{"jp":"天気のいかんでは、ピクニックを延期するかもしれません。","romaji":"Tenki no ikan dewa, pikunikku o enki suru kamoshiremasen.","en":"Depending on the weather, we might delay the picnic.","id":"Tergantung pada cuaca, kami mungkin menunda piknik."},{"jp":"交通事情のいかんでは、遅れることがあります。","romaji":"Koutsuujijou no ikan dewa, okureru koto ga arimasu.","en":"Depending on the traffic conditions, I might be late.","id":"Tergantung pada kondisi lalu lintas, saya mungkin terlambat."},{"jp":"経済の状況のいかんでは、会社の将来は決まります。","romaji":"Keizai no joukyou no ikan dewa, kaisha no shourai wa kimarimasu.","en":"Depending on the state of the economy, the company's future is determined.","id":"Tergantung pada keadaan perekonomian, masa depan perusahaan ditentukan."}]},{"pattern":"Noun のいかんにかかわらず","meaning":"Regardless of, irrespective of.","meaningId":"Terlepas dari itu, terlepas dari itu.","formation":"Noun + のいかんにかかわらず","formationId":"Kata Benda + のいかんにかかわらず","examples":[{"jp":"結果のいかんにかかわらず、彼は決定を後悔しなかった。","romaji":"Kekka no ikan ni kakawarazu, kare wa kettei wo koukai shinakatta.","en":"Regardless of the outcome, he didn't regret his decision.","id":"Apapun hasilnya, dia tidak menyesali keputusannya."},{"jp":"年齢のいかんにかかわらず、どんな人でも学ぶことは可能です。","romaji":"Nenrei no ikan ni kakawarazu, donna hito demo manabu koto wa kanou desu.","en":"Regardless of age, anyone can learn.","id":"Tanpa memandang usia, siapa pun bisa belajar."},{"jp":"経験のいかんにかかわらず、始めることが大切です。","romaji":"Keiken no ikan ni kakawarazu, hajimeru koto ga taisetsu desu.","en":"Regardless of experience, it's important to start.","id":"Terlepas dari pengalaman, penting untuk memulai."},{"jp":"天候のいかんにかかわらず、ハイキングは予定通りに行われます。","romaji":"Tenkou no ikan ni kakawarazu, haikingu wa yotei doori ni okonawaremasu.","en":"Regardless of the weather, the hiking will take place as scheduled.","id":"Terlepas dari cuacanya, pendakian akan berlangsung sesuai jadwal."}]},{"pattern":"Noun のいかんによっては","meaning":"Depending on the matter; depending on noun","meaningId":"Tergantung pada masalahnya; tergantung pada kata benda","formation":"Noun + のいかんによっては","formationId":"Kata Benda + のいかんによっては","examples":[{"jp":"天気のいかんによっては、ピクニックを延期しましょう。","romaji":"Tenki no ikan ni yotte wa, pikunikku o enki shimashou.","en":"Depending on the weather, we should postpone the picnic.","id":"Tergantung cuaca, kita sebaiknya menunda piknik."},{"jp":"試験の結果のいかんによっては、進学できます。","romaji":"Shiken no kekka no ikan ni yotte wa, shingaku dekimasu.","en":"You can go on to further education, depending on the result of the exam.","id":"Anda dapat melanjutkan ke pendidikan lebih lanjut, tergantung pada hasil ujiannya."},{"jp":"状況のいかんによっては、早期退職を考えます。","romaji":"Joukyou no ikan ni yotte wa, souki taishoku o kangaemasu.","en":"Depending on the situation, I will consider early retirement.","id":"Tergantung situasinya, saya akan mempertimbangkan pensiun dini."},{"jp":"彼の反応のいかんによっては、私たちの次の行動を決めます。","romaji":"Kare no hannou no ikan ni yotte wa, watashitachi no tsugi no koudou o kimemasu.","en":"Depending on his reaction, we will decide our next move.","id":"Bergantung pada reaksinya, kami akan memutuskan langkah selanjutnya."}]},{"pattern":"Noun のいかんによらず","meaning":"Means 'regardless of', 'irrespective of', or 'no matter'","meaningId":"Berarti 'terlepas dari', 'terlepas dari', atau 'tidak peduli'","formation":"Noun + のいかんによらず","formationId":"Kata Benda + のいかんによらず","examples":[{"jp":"試験の結果のいかんによらず、自分を信じ続けてください。","romaji":"Shiken no kekka no ikan ni yorazu, jibun o shinji tsudzukete kudasai.","en":"Regardless of the test results, keep believing in yourself.","id":"Apapun hasil tesnya, tetaplah percaya pada diri sendiri."},{"jp":"天気のいかんによらず、毎日、ジョギングをします。","romaji":"Tenki no ikan ni yorazu, mainichi, jogingu o shimasu.","en":"Regardless of the weather, I jog every day.","id":"Terlepas dari cuacanya, saya jogging setiap hari."},{"jp":"彼の年齢のいかんによらず、彼は非常に経験豊富です。","romaji":"Kare no nenrei no ikan ni yorazu, kare wa hijou ni keikenhoufu desu.","en":"Regardless of his age, he is very experienced.","id":"Terlepas dari usianya, dia sangat berpengalaman."},{"jp":"国籍のいかんによらず、誰でもイベントに参加できます。","romaji":"Kokuseki no ikan ni yorazu, daredemo ibento ni sanka dekimasu.","en":"Regardless of nationality, anyone can participate in the event.","id":"Terlepas dari kebangsaannya, siapa pun dapat berpartisipasi dalam acara tersebut."}]},{"pattern":"Noun のごとき Noun","meaning":"Expresses 'like' or 'as if'; something/someone resembles something else strongly.","meaningId":"Mengekspresikan 'seperti' atau 'seolah-olah'; sesuatu/seseorang sangat mirip dengan sesuatu yang lain.","formation":"Noun1 + のごとき + Noun2","formationId":"Kata Benda1 + のごとき + Kata Benda2","examples":[{"jp":"彼は神のごとき存在だ。","romaji":"Kare wa kami no gotoki sonzai da.","en":"He is an existence like a god.","id":"Dia adalah eksistensi seperti dewa."},{"jp":"彼女の美しさは花のごときものだ。","romaji":"Kanojo no utsukushisa wa hana no gotoki mono da.","en":"Her beauty is like a flower.","id":"Kecantikannya bagaikan bunga."},{"jp":"彼は悪魔のごとき行動をした。","romaji":"Kare wa akuma no gotoki koudou o shita.","en":"He acted like a devil.","id":"Dia bertindak seperti iblis."},{"jp":"この地方は春のごとき気候だ。","romaji":"Kono chiho wa haru no gotoki kiko da.","en":"This region has a climate like spring.","id":"Wilayah ini mempunyai iklim seperti musim semi."}]},{"pattern":"Noun のことだから (〜no koto dakara)","meaning":"Because it is about ~, considering it's ~","meaningId":"Karena ini tentang ~, mengingat itu ~","formation":"Noun + のことだから","formationId":"Kata benda + のことだから","examples":[{"jp":"彼のことだから、きっと大丈夫だと思う。","romaji":"Kare no koto dakara, kitto daijoubu da to omou.","en":"Because it's him, I think it will certainly be fine.","id":"Karena itu dia, menurutku pasti akan baik-baik saja."},{"jp":"この店のことだから、料理は美味しいはずです。","romaji":"Kono mise no koto dakara, ryouri wa oishii hazu desu.","en":"Considering it's this restaurant, the food should be delicious.","id":"Mengingat ini restorannya, makanannya pasti enak."},{"jp":"彼女のことだから、もうすぐ到着するでしょう。","romaji":"Kanojo no koto dakara, mou sugu touchaku suru deshou.","en":"Since it's her, she will probably arrive soon.","id":"Karena itu dia, dia mungkin akan segera tiba."},{"jp":"この会社のことだから、もうすぐ新製品が発表されるでしょう。","romaji":"Kono kaisha no koto dakara, mou sugu shinseihin ga happyou sareru deshou.","en":"Given this company, a new product will probably be announced soon.","id":"Mengingat perusahaan ini, produk baru mungkin akan segera diumumkan."}]},{"pattern":"Noun の 嫌いがある","meaning":"Have a dislike for a particular Noun","meaningId":"Tidak menyukai Kata Benda tertentu","formation":"Noun + の嫌いがある","formationId":"Kata benda + の嫌いがある","examples":[{"jp":"彼は魚の嫌いがあるので、寿司を食べません。","romaji":"Kare wa sakana no kirai ga aru node, sushi o tabemasen.","en":"He has a dislike for fish, so he doesn't eat sushi.","id":"Dia tidak menyukai ikan, jadi dia tidak makan sushi."},{"jp":"彼女は高いところの嫌いがあるから、山登りはしない。","romaji":"Kanojo wa takai tokoro no kirai ga aru kara, yamanobori wa shinai.","en":"She has a dislike for high places, so she doesn't go mountain climbing.","id":"Dia tidak menyukai tempat tinggi, jadi dia tidak pergi mendaki gunung."},{"jp":"私の父は人ごみの嫌いがあるので、混雑した場所には行かない。","romaji":"Watashi no chichi wa hitogomi no kirai ga aru node, konzatsu shita basho ni wa ikanai.","en":"My father has a dislike for crowds, so he doesn't go to crowded places.","id":"Ayah saya tidak menyukai keramaian, jadi dia tidak pergi ke tempat keramaian."},{"jp":"子供の頃、私は野菜の嫌いがあったが、今は好きだ。","romaji":"Kodomo no koro, watashi wa yasai no kirai ga atta ga, ima wa suki da.","en":"When I was a child, I had a dislike for vegetables, but now I like them.","id":"Ketika saya masih kecil, saya tidak menyukai sayur-sayuran, tetapi sekarang saya menyukainya."}]},{"pattern":"Noun の手前","meaning":"Expresses the idea of 'Before doing something; on the verge of'.","meaningId":"Mengungkapkan gagasan 'Sebelum melakukan sesuatu; di ambang '.","formation":"Noun + の手前","formationId":"Kata benda + の手前","examples":[{"jp":"試験の手前、遊びに行くのはやめた方がいい。","romaji":"Shiken no temae, asobi ni iku no wa yameta hou ga ii.","en":"Just before the exam, it's better to stop going out to play.","id":"Sesaat sebelum ujian, lebih baik berhenti bermain."},{"jp":"彼女と別れる手前、思い直しました。","romaji":"Kanojo to wakareru temae, omoinaoshimashita.","en":"Just before breaking up with her, I changed my mind.","id":"Tepat sebelum putus dengannya, saya berubah pikiran."},{"jp":"締め切りの手前で、やっとレポートが完成しました。","romaji":"Shimekiri no temae de, yatto repooto ga kansei shimashita.","en":"I finally finished the report just before the deadline.","id":"Saya akhirnya menyelesaikan laporannya tepat sebelum batas waktu."},{"jp":"選挙の手前、政治の話が多くなります。","romaji":"Senkyo no temae, seiji no hanashi ga ooku narimasu.","en":"Just before the election, there will be a lot of political talk.","id":"Menjelang pemilu, akan banyak perbincangan politik."}]},{"pattern":"Noun の極み (〜no kiwami)","meaning":"Used to express the extreme or utmost point of something.","meaningId":"Digunakan untuk menyatakan titik ekstrim atau paling penting dari sesuatu.","formation":"Noun + の極み","formationId":"Kata benda + の極み","examples":[{"jp":"彼の料理の極みは、誰もマネできない。","romaji":"Kare no ryouri no kiwami wa, daremo mane dekinai.","en":"The pinnacle of his cooking is something nobody can imitate.","id":"Puncak dari masakannya adalah sesuatu yang tidak dapat ditiru oleh siapa pun."},{"jp":"彼女の努力の極みが、この成功を作り出した。","romaji":"Kanojo no doryoku no kiwami ga, kono seikou wo tsukuridashita.","en":"The extreme of her effort has created this success.","id":"Upaya ekstrimnya telah menciptakan kesuksesan ini."},{"jp":"彼は音楽の極みを追求し続けている。","romaji":"Kare wa ongaku no kiwami o tsuikyuu shitsuzukete iru.","en":"He continues to pursue the pinnacle of music.","id":"Dia terus mengejar puncak musik."},{"jp":"この風景は美の極みだ。","romaji":"Kono fuukei wa bi no kiwami da.","en":"This scenery is the epitome of beauty.","id":"Pemandangan ini adalah lambang keindahan."}]},{"pattern":"Noun の 至り","meaning":"Expresses 'the height of', 'the extreme of' something.","meaningId":"Mengekspresikan 'ketinggian', 'ekstrim dari' sesuatu.","formation":"Noun + の至り","formationId":"Kata benda + の至り","examples":[{"jp":"彼の冗談には驚きの至りだ。","romaji":"Kare no joudan ni wa odoroki no itari da.","en":"His jokes are the height of surprise.","id":"Leluconnya sangat mengejutkan."},{"jp":"父がプロジェクトのリーダーになったのは、光栄の至りです。","romaji":"Chichi ga purojekuto no riidaa ni natta no wa, kouei no itari desu.","en":"It is the height of honor that my father became the project leader.","id":"Merupakan suatu kehormatan besar bagi ayah saya untuk menjadi pemimpin proyek."},{"jp":"彼女の素晴らしい演技には感動の至りだった。","romaji":"Kanojo no subarashii engi ni wa kandou no itari datta.","en":"Her wonderful performance was the height of emotion.","id":"Penampilannya yang luar biasa adalah puncak emosi."},{"jp":"その失敗は恥ずかしさの至りだった。","romaji":"Sono shippai wa hazukashisa no itari datta.","en":"That failure was the height of embarrassment.","id":"Kegagalan itu merupakan puncak rasa malunya."}]},{"pattern":"Noun はいざ知らず","meaning":"‘I can understand it for ~, but for …? (surprising)’","meaningId":"‘Aku bisa memahaminya untuk ~, tapi untuk…? (mengejutkan)’","formation":"Noun + はいざ知らず, Noun + とは/なんて/しかし etc.","formationId":"Kata Benda + はいざ知らず, Kata Benda + とは/なんて/しかし dll.","examples":[{"jp":"彼が遅れるのはいざ知らず、彼女まで遅刻するとは意外だ。","romaji":"Kare ga okureru no wa iza shirazu, kanojo made chikoku suru to wa igai da.","en":"Well, I can understand him being late, but even her...? That's surprising.","id":"Yah, aku bisa memahami dia terlambat, tapi bahkan dia...? Itu mengejutkan."},{"jp":"夏はいざ知らず、冬にアイスクリームを食べるのは寒すぎませんか？","romaji":"Natsu wa iza shirazu, fuyu ni aisukuriimu o taberu no wa samusugimasen ka?","en":"I can see eating ice cream in summer, but in winter…isn't it too cold?","id":"Saya bisa melihat makan es krim di musim panas, tetapi di musim dingin…bukankah terlalu dingin?"},{"jp":"子供がテレビゲームに夢中になるのはいざ知らず、大人までそんなに夢中になるとは思わなかった。","romaji":"Kodomo ga terebi geemu ni muchuu ni naru no wa iza shirazu, otona made sonnani muchuu ni naru to wa omowanakatta.","en":"I can see why kids get hooked on video games, but I didn't think even adults would get that absorbed.","id":"Saya paham kenapa anak-anak ketagihan video game, tapi menurut saya orang dewasa pun tidak akan begitu tertarik."},{"jp":"苦しい時はいざ知らず、平時でもそんなに努力するなんてすばらしい。","romaji":"Kurushii toki wa iza shirazu, heiji demo sonnani doryoku suru nante subarashii.","en":"Well, I can understand working hard in tough times, but to do so even in normal times is impressive.","id":"Yah, aku bisa mengerti bekerja keras di masa-masa sulit, tapi melakukannya bahkan di saat-saat normal sangatlah mengesankan."}]},{"pattern":"Noun はおろか～すら","meaning":"Expresses 'not to mention ~, even ~'.","meaningId":"Menyatakan 'belum lagi ~, bahkan ~'.","formation":"Noun1 はおろか, Noun2 すら/さえ ～","formationId":"Kata Benda1 はおろか, Kata Benda2 すら/さえ ～","examples":[{"jp":"彼は走るはおろか、速く歩くことすらできない。","romaji":"Kare wa hashiru wa oroka, hayaku aruku koto sura dekinai.","en":"He can't even walk fast, let alone run.","id":"Ia bahkan tidak bisa berjalan cepat, apalagi berlari."},{"jp":"日本語はおろか、英語さえ話しません。","romaji":"Nihongo wa oroka, eigo sae hanashimasen.","en":"He doesn't even speak English, let alone Japanese.","id":"Dia bahkan tidak bisa berbahasa Inggris, apalagi bahasa Jepang."},{"jp":"彼は食事はおろか、一日中何も飲まなかった。","romaji":"Kare wa shokuji wa oroka, ichinichijuu nani mo nomanakatta.","en":"He didn't even drink anything all day, let alone eat a meal.","id":"Dia bahkan tidak minum apapun sepanjang hari, apalagi makan."},{"jp":"このレストランは味はおろか、サービスさえ悪い。","romaji":"Kono resutoran wa aji wa oroka, saabisu sae warui.","en":"Never mind the taste; even the service is bad.","id":"Jangan pedulikan rasanya; bahkan layanannya buruk."}]},{"pattern":"Noun はおろか～まで","meaning":"Means 'not just A, but even B'; 'let alone A, even B'.","meaningId":"Berarti 'bukan hanya A, tapi bahkan B'; 'apalagi A, bahkan B'.","formation":"Noun1 + はおろか + Noun2 + まで","formationId":"Kata Benda1 + はおろか + Kata Benda2 + まで","examples":[{"jp":"彼は英語はおろか、日本語までペラペラなんです。","romaji":"Kare wa eigo wa oroka, nihongo made perapera nan desu.","en":"He is not just fluent in English, but even in Japanese.","id":"Dia tidak hanya fasih berbahasa Inggris, tapi bahkan berbahasa Jepang."},{"jp":"彼女は数学はおろか、物理まで得意なんです。","romaji":"Kanojo wa suugaku wa oroka, butsuri made tokui nan desu.","en":"She is not just good at math, but even at physics.","id":"Dia tidak hanya pandai matematika, tetapi bahkan fisika."},{"jp":"この料理は見た目はおろか、味まで最高だ。","romaji":"Kono ryouri wa mitame wa oroka, aji made saikou da.","en":"This dish is not only visually appealing, but it even tastes fantastic.","id":"Hidangan ini tidak hanya menarik secara visual, tetapi rasanya juga luar biasa."},{"jp":"彼は歌はおろか、ダンスまで上手だ。","romaji":"Kare wa uta wa oroka, dansu made umai da.","en":"He is not just good at singing, but even at dancing.","id":"Dia tidak hanya pandai menyanyi, tapi bahkan menari."}]},{"pattern":"Noun はおろか～も","meaning":"'Not only...but also', 'not to mention', 'to say nothing of'","meaningId":"'Tidak hanya...tapi juga', 'belum lagi', 'belum lagi'","formation":"Noun + はおろか + Noun + も","formationId":"Kata Benda + はおろか + Kata Benda + も","examples":[{"jp":"絵を描くことはおろか、字さえ書けない。","romaji":"E wo kaku koto wa oroka, ji sae kakenai.","en":"Needless to say drawing pictures, he can’t even write letters.","id":"Tak perlu dikatakan lagi menggambar, dia bahkan tidak bisa menulis surat."},{"jp":"彼は英語はおろか、日本語もわからない。","romaji":"Kare wa eigo wa oroka, nihongo mo wakaranai.","en":"Needless to say English, he doesn’t even understand Japanese.","id":"Tak perlu dikatakan lagi bahasa Inggris, dia bahkan tidak mengerti bahasa Jepang."},{"jp":"彼女は数学はおろか、算数も得意ではない。","romaji":"Kanojo wa suugaku wa oroka, sansuu mo tokui dewa nai.","en":"Needless to say mathematics, she isn’t even good at arithmetic.","id":"Tak perlu dikatakan lagi matematika, dia bahkan tidak pandai berhitung."},{"jp":"彼は走ることはおろか、歩くことも難しい。","romaji":"Kare wa hashiru koto wa oroka, aruku koto mo muzukashii.","en":"Needless to say running, he finds even walking difficult.","id":"Tak perlu dikatakan lagi berlari, dia bahkan merasa sulit untuk berjalan."}]},{"pattern":"Noun はさておき","meaning":"Means 'putting aside', 'aside from', 'notwithstanding'.","meaningId":"Berarti 'mengesampingkan', 'mengesampingkan', 'meskipun demikian'.","formation":"Noun + はさておき","formationId":"Kata benda + はさておき","examples":[{"jp":"試験の結果はさておき、この学期はとても学ぶことが多かった。","romaji":"Shiken no kekka wa sateoki, kono gakki wa totemo manabu koto ga ookatta.","en":"Aside from the exam results, I learned a lot this semester.","id":"Selain hasil ujian, saya belajar banyak semester ini."},{"jp":"天候はさておき、明日のピクニックは楽しみにしています。","romaji":"Tenkou wa sateoki, ashita no pikunikku wa tanoshimi ni shiteimasu.","en":"Putting aside the weather, I am looking forward to tomorrow's picnic.","id":"Mengesampingkan cuaca, saya menantikan piknik besok."},{"jp":"彼の性格はさておき、彼のスキルは認めざるを得ない。","romaji":"Kare no seikaku wa sateoki, kare no sukiru wa mitomezaru wo enai.","en":"Notwithstanding his personality, his skills are undeniable.","id":"Terlepas dari kepribadiannya, keterampilannya tidak dapat disangkal."},{"jp":"彼があまりにも遅いことはさておき、彼が来ると思われること自体が問題だ。","romaji":"Kare ga amari ni mo osoi koto wa sateoki, kare ga kuru to omowareru koto jitai ga mondai da.","en":"Aside from him being late, the issue is that he is expected to come at all.","id":"Selain dia terlambat, masalahnya adalah dia diharapkan datang."}]},{"pattern":"Noun + はどうであれ","meaning":"This phrase means 'regardless of' or 'no matter how…'.","meaningId":"Frasa ini berarti 'terlepas dari' atau 'tidak peduli bagaimana…'.","formation":"Noun + はどうであれ","formationId":"Kata Benda + はどうであれ","examples":[{"jp":"天候はどうであれ、試合は行われます。","romaji":"Tenkou wa dou de are, shiai wa okonawaremasu.","en":"No matter what the weather is, the match will be held.","id":"Tidak peduli bagaimana cuacanya, pertandingan akan tetap digelar."},{"jp":"結果はどうであれ、最善を尽くすだけです。","romaji":"Kekka wa dou de are, saizen wo tsukusu dake desu.","en":"No matter what the result is, all we can do is try our best.","id":"Apa pun hasilnya, yang bisa kita lakukan hanyalah berusaha semaksimal mungkin."},{"jp":"あなたの意見はどうであれ、私は彼を信じます。","romaji":"Anata no iken wa dou de are, watashi wa kare wo shinjimasu.","en":"No matter what your opinion is, I believe him.","id":"Tidak peduli apa pendapatmu, aku percaya padanya."},{"jp":"試験の結果はどうであれ、あなたには何も変わりません。","romaji":"Shiken no kekka wa dou de are, anata ni wa nani mo kawarimasen.","en":"No matter what the result of the test is, nothing will change for you.","id":"Apa pun hasil tesnya, tidak ada yang berubah bagi Anda."}]},{"pattern":"Noun まみれ","meaning":"Expresses a state in which something is entirely covered or filled with something else.","meaningId":"Menyatakan keadaan di mana sesuatu tertutup seluruhnya atau terisi oleh sesuatu yang lain.","formation":"Noun + まみれ","formationId":"Kata benda + まみれ","examples":[{"jp":"彼は泥まみれになって帰ってきた。","romaji":"Kare wa doro mamire ni natte kaette kita.","en":"He returned home covered in mud.","id":"Dia kembali ke rumah dalam keadaan berlumuran lumpur."},{"jp":"彼女は涙まみれになりながら告白した。","romaji":"Kanojo wa namida mamire ni narinagara kokuhaku shita.","en":"She confessed while crying her eyes out.","id":"Dia mengaku sambil menangis."},{"jp":"その事件後、彼はスキャンダルまみれになった。","romaji":"Sono jiken go, kare wa sukandaru mamire ni natta.","en":"After that incident, he was completely embroiled in scandal.","id":"Setelah kejadian itu, dia terlibat skandal."},{"jp":"この部屋は埃まみれだ。","romaji":"Kono heya wa hokori mamire da.","en":"This room is covered in dust.","id":"Ruangan ini tertutup debu."}]},{"pattern":"Noun もさることながら Noun も","meaning":"Means 'not only... but also'; the second noun is especially emphasized.","meaningId":"Berarti 'tidak hanya... tetapi juga'; kata benda kedua secara khusus ditekankan.","formation":"Noun1 + もさることながら + Noun2 + も","formationId":"Kata Benda1 + もさることながら + Kata Benda2 + も","examples":[{"jp":"彼の歌唱力もさることながら、ダンスも素晴らしい。","romaji":"Kare no kashou-ryoku mo saru koto nagara, dansu mo subarashii.","en":"Not only his singing ability but also his dancing is wonderful.","id":"Tidak hanya kemampuan menyanyinya tetapi juga tariannya yang luar biasa."},{"jp":"このレストラン、味もさることながら、サービスもすばらしい。","romaji":"Kono resutoran, aji mo saru koto nagara, saabisu mo subarashii.","en":"At this restaurant, not only the taste but also the service is wonderful.","id":"Di restoran ini, tidak hanya rasanya tetapi juga layanannya luar biasa."},{"jp":"彼女の美しさもさることながら、その知性も魅力的だ。","romaji":"Kanojo no utsukushisa mo saru koto nagara, sono chisei mo miryoku-teki da.","en":"Not only her beauty but also her intelligence is attractive.","id":"Tidak hanya kecantikannya tetapi kecerdasannya juga menarik."},{"jp":"その映画、ストーリーもさることながら、音楽も素晴らしかった。","romaji":"Sono eiga, sutoorii mo saru koto nagara, ongaku mo subarashikatta.","en":"In that movie, not only the story but also the music was wonderful.","id":"Dalam film itu, tidak hanya ceritanya tetapi juga musiknya sangat indah."}]},{"pattern":"Noun も兼ねて","meaning":"Used to express 'as well as', 'also', or 'at the same time'.","meaningId":"Digunakan untuk menyatakan 'serta', 'juga', atau 'pada saat yang sama'.","formation":"Noun + も兼ねて","formationId":"Kata benda + も兼ねて","examples":[{"jp":"散歩も兼ねて、公園に行きました。","romaji":"Sanpo mo kanete, kouen ni ikimashita.","en":"I went to the park, also for a walk.","id":"Saya pergi ke taman, juga berjalan-jalan."},{"jp":"今日は日本語の勉強も兼ねて、日本の映画を見ます。","romaji":"Kyou wa Nihongo no benkyou mo kanete, Nihon no eiga wo mimasu.","en":"Today, I will watch a Japanese movie, also to study Japanese.","id":"Hari ini saya akan menonton film Jepang, juga untuk belajar bahasa Jepang."},{"jp":"仕事も兼ねて、海外に行く予定です。","romaji":"Shigoto mo kanete, kaigai ni iku yotei desu.","en":"I plan to go abroad, also for work.","id":"Saya berencana pergi ke luar negeri, juga untuk bekerja."},{"jp":"旅行も兼ねて、友人の結婚式に出席します。","romaji":"Ryokou mo kanete, yuujin no kekkonshiki ni shusseki shimasu.","en":"I will attend a friend's wedding, also as a trip.","id":"Saya akan menghadiri pernikahan seorang teman, juga sebagai perjalanan."}]},{"pattern":"Noun も相まって","meaning":"Used to express that combined with something else, it caused a certain outcome.","meaningId":"Digunakan untuk menyatakan bahwa dikombinasikan dengan sesuatu yang lain, hal itu menyebabkan hasil tertentu.","formation":"Noun + も相まって","formationId":"Kata benda + も相まって","examples":[{"jp":"気候も相まって、この地域は農業に適しています。","romaji":"Kikou mo aimatte, kono chiiki wa nougyou ni tekishiteimasu.","en":"Combined with the climate, this area is suitable for agriculture.","id":"Dikombinasikan dengan iklim, kawasan ini cocok untuk pertanian."},{"jp":"彼の才能も相まって、彼は急速に昇進した。","romaji":"Kare no sainou mo aimatte, kare wa kyuusoku ni shoushin shita.","en":"Combined with his talent, he was rapidly promoted.","id":"Dikombinasikan dengan bakatnya, dia dipromosikan dengan cepat."},{"jp":"技術進歩も相まって、私たちはより効率的に仕事をこなすことができるようになりました。","romaji":"Gijutsu shinpo mo aimatte, watashitachi wa yori kouritsu-teki ni shigoto wo konasu koto ga dekiru you ni narimashita.","en":"Combined with technological progress, we have become able to handle our work more efficiently.","id":"Dikombinasikan dengan kemajuan teknologi, kita menjadi mampu menangani pekerjaan kita dengan lebih efisien."},{"jp":"彼の努力も相まって、プロジェクトは成功しました。","romaji":"Kare no doryoku mo aimatte, purojekuto wa seikou shimashita.","en":"Combined with his efforts, the project was successful.","id":"Dikombinasikan dengan usahanya, proyek ini berhasil."}]},{"pattern":"Noun を おいて他に Verb ない (〜wo oite hoka ni〜nai)","meaning":"Means 'apart from ~ there's nothing else,' implying the Noun is the best or most suitable choice.","meaningId":"Berarti 'selain ~ tidak ada yang lain', menyiratkan Kata Benda adalah pilihan yang terbaik atau paling cocok.","formation":"Noun + をおいて他に + Verb negative form","formationId":"Kata benda + をおいて他に + Kata kerja bentuk negatif","examples":[{"jp":"この仕事を彼に任せる人をおいて他にいない。","romaji":"Kono shigoto wo kare ni makaseru hito wo oite hoka ni inai.","en":"Apart from him, there's no one else to entrust this job to.","id":"Selain dia, tidak ada orang lain yang bisa mempercayakan pekerjaan ini."},{"jp":"この問題を解決できるのは彼をおいて他にいない。","romaji":"Kono mondai wo kaiketsu dekiru no wa kare o oite hoka ni inai.","en":"Apart from him, there's no one else who can solve this problem.","id":"Selain dia, tidak ada orang lain yang bisa menyelesaikan masalah ini."},{"jp":"この地域で美味しい麺を作る店をおいて他にない。","romaji":"Kono chiiki de oishii men o tsukuru mise o oite hoka ni nai.","en":"There is no other restaurant in this area that makes delicious noodles apart from this one.","id":"Tidak ada restoran lain di daerah ini yang membuat mie enak selain yang satu ini."},{"jp":"彼女の歌声を超える歌手をおいて他にいない。","romaji":"Kanojo no utagoe o koeru kashu o oite hoka ni inai.","en":"There is no other singer who could surpass her singing voice.","id":"Tidak ada penyanyi lain yang mampu melampaui suara nyanyiannya."}]},{"pattern":"Noun をもって","meaning":"Used to indicate means, methods, or time; 'with', 'by means of', 'at'.","meaningId":"Digunakan untuk menunjukkan cara, metode, atau waktu; 'dengan', 'melalui', 'pada'.","formation":"Noun + をもって","formationId":"Kata benda + をもって","examples":[{"jp":"彼は誠実さをもって人々に信頼されています。","romaji":"Kare wa seijitsusa wo motte hitobito ni shinrai sarete imasu.","en":"He is trusted by people with his honesty.","id":"Ia dipercaya oleh orang-orang karena kejujurannya."},{"jp":"この賞をもって、彼女の努力が認められました。","romaji":"Kono shou wo motte, kanojo no doryoku ga mitomeraremashita.","en":"With this award, her efforts were recognized.","id":"Dengan penghargaan ini, usahanya diakui."},{"jp":"彼は強い決意をもって問題に取り組んだ。","romaji":"Kare wa tsuyoi ketsui wo motte mondai ni torikunda.","en":"He tackled the problem with strong determination.","id":"Dia mengatasi masalah tersebut dengan tekad yang kuat."},{"jp":"3月をもって、この店は閉店します。","romaji":"Sangatsu wo motte, kono mise wa heiten shimasu.","en":"This store will close at the end of March.","id":"Toko ini akan tutup pada akhir Maret."}]},{"pattern":"Noun をものともせずに","meaning":"Expresses the idea that 'despite something, action was carried out', translating to 'without being fazed by something'.","meaningId":"Mengekspresikan gagasan bahwa 'meskipun ada sesuatu, tindakan telah dilakukan', yang diterjemahkan menjadi 'tanpa terganggu oleh sesuatu'.","formation":"Noun + をものともせずに","formationId":"Kata Benda + をものともせずに","examples":[{"jp":"彼女は怖さをものともせずに、暗闇の中へ進んで行った。","romaji":"Kanojo wa kowasa wo mono tomo sezu ni, kurayami no naka e susunde itta.","en":"Despite her fear, she went ahead into the darkness.","id":"Meskipun dia takut, dia terus berjalan menuju kegelapan."},{"jp":"試験のプレッシャーをものともせずに、彼は自信満々に答えた。","romaji":"Shiken no puresshaa wo mono tomo sezu ni, kare wa jishin manman ni kotaeta.","en":"Unfazed by the pressure of the exam, he answered with full confidence.","id":"Tidak terpengaruh oleh tekanan ujian, dia menjawab dengan penuh percaya diri."},{"jp":"彼は風雪をものともせずに山を登った。","romaji":"Kare wa fuusetsu wo mono tomo sezu ni, yama wo nobotta.","en":"He climbed the mountain unfazed by the wind and snow.","id":"Dia mendaki gunung tanpa terpengaruh oleh angin dan salju."},{"jp":"彼は失敗をものともせずに、前に進み続けた。","romaji":"Kare wa shippai wo mono tomo sezu ni, mae ni susumi tsuzuketa.","en":"He continued to move forward, undeterred by failure.","id":"Dia terus bergerak maju, tidak terpengaruh oleh kegagalan."}]},{"pattern":"Noun をよそに","meaning":"Despite; Notwithstanding; Regardless of","meaningId":"Meskipun; Meskipun; Terlepas dari","formation":"Noun + をよそに","formationId":"Kata benda + をよそに","examples":[{"jp":"経済危機をよそに、彼は高級な車を買った。","romaji":"Keizai kiki wo yoso ni, kare wa koukyuu na kuruma wo katta.","en":"Despite the economic crisis, he bought a luxury car.","id":"Meski krisis ekonomi, ia membeli mobil mewah."},{"jp":"試験が迫るをよそに、彼は遊び続けている。","romaji":"Shiken ga semaru wo yoso ni, kare wa asobi tsuzukete iru.","en":"Despite the approaching test, he keeps on playing.","id":"Meskipun ujian semakin dekat, dia terus bermain."},{"jp":"親の反対をよそに、彼女は彼と結婚しました。","romaji":"Oya no hantai wo yoso ni, kanojo wa kare to kekkon shimashita.","en":"Despite her parents' opposition, she married him.","id":"Meskipun ditentang oleh orang tuanya, dia menikah dengannya."},{"jp":"その国の経済状況をよそに、多くの企業が進出し続けている。","romaji":"Sono kuni no keizai joukyou wo yoso ni, ooku no kigyou ga shinshutsu shi tsuzukete iru.","en":"Despite the country's economic situation, many companies continue to expand.","id":"Terlepas dari situasi perekonomian negara, banyak perusahaan terus melakukan ekspansi."}]},{"pattern":"Noun を余儀なくされる","meaning":"Expresses the idea of being forced into a certain situation, 'to be compelled', 'to be obliged'.","meaningId":"Mengungkapkan gagasan dipaksa dalam situasi tertentu, 'dipaksa', 'diwajibkan'.","formation":"Noun + を + 余儀なくされる","formationId":"Kata benda + を + 余儀なくされる","examples":[{"jp":"彼は経済的困難により、退学を余儀なくされた。","romaji":"Kare wa keizai-teki konnan ni yori, taigaku wo yogi naku saremashita.","en":"Due to financial difficulties, he was forced to drop out of school.","id":"Karena kesulitan keuangan, ia terpaksa putus sekolah."},{"jp":"厳しい天候によって、私たちは遠足を中止する余儀なくされた。","romaji":"Kibishi tenkou ni yotte, watashitachi wa ensoku wo chushi suru yogi naku sareta.","en":"We were forced to cancel the excursion due to the severe weather.","id":"Kami terpaksa membatalkan perjalanan karena cuaca buruk."},{"jp":"怪我のため、彼は入院を余儀なくされた。","romaji":"Kega no tame, kare wa nyuuin wo yogi naku sareta.","en":"Due to his injury, he was forced to be hospitalized.","id":"Karena cederanya, dia terpaksa dirawat di rumah sakit."},{"jp":"リストラの恐怖により、多くの従業員が転職を余儀なくされた。","romaji":"Risutora no kyoufu ni yori, ooku no juugyouin ga tenshoku wo yogi naku sareta.","en":"Fear of layoffs forced many employees to change jobs.","id":"Ketakutan akan PHK memaksa banyak karyawan untuk berganti pekerjaan."}]},{"pattern":"Noun を前提として","meaning":"Used to express 'on the assumption of', 'based on'.","meaningId":"Digunakan untuk menyatakan 'atas asumsi', 'berdasarkan'.","formation":"Noun + を前提として","formationId":"Kata benda + を前提として","examples":[{"jp":"成功を前提として、ビジネスプランを作成しました。","romaji":"Seikou wo zentei toshite, bijinesu puran wo sakusei shimashita.","en":"We made a business plan on the assumption of success.","id":"Kami membuat rencana bisnis dengan asumsi kesuksesan."},{"jp":"彼の勝利を前提として、パーティーの準備を始めました。","romaji":"Kare no shouri wo zentei toshite, paatii no junbi wo hajimemashita.","en":"We started preparing for the party assuming his victory.","id":"Kami mulai mempersiapkan pesta dengan asumsi kemenangannya."},{"jp":"両親の理解を前提として、旅行計画を進めます。","romaji":"Ryoushin no rikai wo zentei toshite, ryokou keikaku wo susumemasu.","en":"I will proceed with the travel plan based on my parents’ understanding.","id":"Saya akan melanjutkan rencana perjalanan berdasarkan pemahaman orang tua saya."},{"jp":"このプロジェクトは、資金が揃うことを前提としています。","romaji":"Kono purojekuto wa, shikin ga sorou koto wo zentei toshiteimasu.","en":"This project assumes that the funds will be in place.","id":"Proyek ini mengasumsikan bahwa dana akan tersedia."}]},{"pattern":"Noun を前提にして","meaning":"Assuming; presupposing; on the assumption of.","meaningId":"Dengan asumsi; mengandaikan; dengan asumsi.","formation":"Noun + を前提にして","formationId":"Kata benda + を前提にして","examples":[{"jp":"好天を前提にして、明日のピクニックの計画を立てました。","romaji":"Kouten wo zentei ni shite, ashita no pikunikku no keikaku wo tatemashita.","en":"We planned tomorrow's picnic assuming fine weather.","id":"Kami merencanakan piknik besok dengan asumsi cuaca cerah."},{"jp":"彼女の合格を前提にして、祝いのパーティーの準備を始めました。","romaji":"Kanojo no goukaku wo zentei ni shite, iwai no paatii no junbi wo hajimemashita.","en":"We started preparing for the celebration party assuming she would pass the exam.","id":"Kami mulai mempersiapkan pesta perayaan dengan asumsi dia akan lulus ujian."},{"jp":"経済成長を前提にして、予算案が作られた。","romaji":"Keizai seichou wo zentei ni shite, yosan-an ga tsukurareta.","en":"The budget was made on the assumption of economic growth.","id":"Anggaran dibuat dengan asumsi pertumbuhan ekonomi."},{"jp":"彼の参加を前提にして、会議の日程を決めました。","romaji":"Kare no sanka wo zentei ni shite, kaigi no nittei wo kimemashita.","en":"We decided the meeting schedule assuming his participation.","id":"Kami memutuskan jadwal pertemuan dengan asumsi partisipasinya."}]},{"pattern":"Noun を境にして","meaning":"Means 'as a turning point', 'since (time)', or 'from (time) on'.","meaningId":"Berarti 'sebagai titik balik', 'sejak (waktu)', atau 'sejak (waktu) sampai'.","formation":"Noun + を境に(して)","formationId":"Kata Benda + を境に(して)","examples":[{"jp":"父の死を境にして、彼の性格が一変した。","romaji":"Chichi no shi wo sakai ni shite, kare no seikaku ga ippen shita.","en":"His personality changed completely since his father's death.","id":"Kepribadiannya berubah total sejak kematian ayahnya."},{"jp":"試験を境にして、休暇を取る予定です。","romaji":"Shiken wo sakai ni shite, kyuka wo toru yotei desu.","en":"I plan to take a vacation after the exam.","id":"Saya berencana untuk mengambil liburan setelah ujian."},{"jp":"春を境にして、新しい生活を始めるつもりだ。","romaji":"Haru wo sakai ni shite, atarashii seikatsu o hajimeru tsumori da.","en":"I intend to start a new life from spring onwards.","id":"Saya berniat memulai hidup baru mulai musim semi dan seterusnya."},{"jp":"彼女は入学を境にして、ファッションに興味を持ち始めた。","romaji":"Kanojo wa nyuugaku wo sakai ni shite, fasshon ni kyoumi o mochi hajimeta.","en":"She began to take an interest in fashion from the time she entered school.","id":"Dia mulai tertarik pada fashion sejak dia masuk sekolah."}]},{"pattern":"Noun を機にして","meaning":"To take the opportunity to; taking the occasion to; on the occasion of.","meaningId":"Untuk mengambil kesempatan untuk; mengambil kesempatan untuk; pada kesempatan.","formation":"Noun + を機にして","formationId":"Kata benda + を機にして","examples":[{"jp":"引っ越しを機にして、家具を新しくしました。","romaji":"Hikkoshi wo ki ni shite, kagu wo atarashiku shimashita.","en":"I took the opportunity of moving to get new furniture.","id":"Saya mengambil kesempatan pindah untuk mendapatkan furnitur baru."},{"jp":"卒業を機にして、新しい仕事を探し始めた。","romaji":"Sotsugyou wo ki ni shite, atarashii shigoto wo sagashi hajimeta.","en":"I started looking for a new job on the occasion of graduation.","id":"Saya mulai mencari pekerjaan baru pada saat kelulusan."},{"jp":"このプロジェクトの失敗を機にして、会社全体の仕事のやり方を見直すことにした。","romaji":"Kono purojekuto no shippai wo ki ni shite, kaisha zentai no shigoto no yarikata wo minaosu koto ni shita.","en":"We decided to review the way the entire company works, taking this project's failure as an opportunity.","id":"Kami memutuskan untuk meninjau cara kerja seluruh perusahaan, dan menganggap kegagalan proyek ini sebagai sebuah peluang."},{"jp":"結婚を機にして、私たちは新しい町へ引っ越しました。","romaji":"Kekkon wo ki ni shite, watashitachi wa atarashii machi e hikkoshimashita.","en":"We moved to a new town on the occasion of our marriage.","id":"Kami pindah ke kota baru pada kesempatan pernikahan kami."}]},{"pattern":"Noun を皮切りに / を皮切りにして","meaning":"Used to indicate the starting point of some series of events or actions; 'starting with', 'beginning with'.","meaningId":"Digunakan untuk menunjukkan titik awal dari beberapa rangkaian peristiwa atau tindakan; 'dimulai dengan', 'dimulai dengan'.","formation":"Noun + を皮切りに / を皮切りにして","formationId":"Kata benda + を皮切りに / を皮切りにして","examples":[{"jp":"彼はその論文を皮切りにして複数の研究を開始した。","romaji":"Kare wa sono ronbun o kawakiri ni shite fukusū no kenkyū o kaishi shita.","en":"Starting with that thesis, he started multiple research projects.","id":"Dimulai dengan tesis itu, ia memulai berbagai proyek penelitian."},{"jp":"彼女はこのコンペティションを皮切りにして彼女のダンスキャリアが飛躍的に成長した。","romaji":"Kanojo wa kono konpetishon o kawakiri ni shite kanojo no dansu kyaria ga hiyakuteki ni seichō shita.","en":"Starting with this competition, her dance career drastically grew.","id":"Berawal dari kompetisi ini, karir menarinya berkembang pesat."},{"jp":"この映画を皮切りに、彼は人気俳優としての立場を確立した。","romaji":"Kono eiga o kawakiri ni, kare wa ninki haiyū to shite no tachiba o kakuritsu shita.","en":"Starting with this movie, he established his position as a popular actor.","id":"Dimulai dengan film ini, ia memantapkan posisinya sebagai aktor populer."},{"jp":"このプロジェクトを皮切りにして、会社は新たな方向性を示し始めた。","romaji":"Kono purojekuto o kawakiri ni shite, kaisha wa arata na hōkōsei o shimeshi hajimeta.","en":"Starting with this project, the company began to show a new direction.","id":"Dimulai dengan proyek ini, perusahaan mulai menunjukkan arah baru."}]},{"pattern":"Noun を皮切りにして","meaning":"Used to express 'Starting with', 'Beginning with'","meaningId":"Digunakan untuk menyatakan 'Dimulai dengan', 'Dimulai dengan'","formation":"Noun + を皮切りに (して)","formationId":"Kata benda + を皮切りに (して)","examples":[{"jp":"彼はその日を皮切りにして毎日ジムに通い始めました。","romaji":"Kare wa sono hi o kawakiri ni shite mainichi jimu ni kayoi hajimemashita.","en":"Starting from that day, he began to go to the gym every day.","id":"Mulai hari itu, dia mulai pergi ke gym setiap hari."},{"jp":"新年会を皮切りにして、今年はたくさんのイベントが開催されます。","romaji":"Shinnenkai o kawakiri ni shite, kotoshi wa takusan no ibento ga kaisai saremasu.","en":"Starting with the New Year's party, a lot of events will be held this year.","id":"Dimulai dengan pesta tahun baru, banyak sekali acara yang akan diadakan tahun ini."},{"jp":"この映画を皮切りにして彼の人気は急上昇しました。","romaji":"Kono eiga o kawakiri ni shite kare no ninki wa kyūjōshō shimashita.","en":"Beginning with this movie, his popularity skyrocketed.","id":"Diawali dengan film ini, popularitasnya melejit."},{"jp":"東京を皮切りにして、彼の展示会は全国で開かれる予定です。","romaji":"Tōkyō o kawakiri ni shite, kare no tenjikai wa zenkoku de hirakareru yotei desu.","en":"Starting in Tokyo, his exhibitions are set to be held nationwide.","id":"Dimulai di Tokyo, pamerannya akan diadakan secara nasional."}]},{"pattern":"Noun を禁じ得ない (〜wo kinjienai)","meaning":"'Cannot help but do', or 'inevitable'","meaningId":"'Mau tidak mau harus melakukan', atau 'tak terhindarkan'","formation":"Noun + を禁じ得ない","formationId":"Kata Benda + を禁じ得ない","examples":[{"jp":"この結果には驚きを禁じ得ない。","romaji":"Kono kekka ni wa odoroki o kinjienai.","en":"I can't help but be surprised at this result.","id":"Saya terkejut dengan hasil ini."},{"jp":"そのニュースを聞いて、彼の成功を祝福する気持ちを禁じ得ない。","romaji":"Sono nyūsu o kiite, kare no seikō o shukufuku suru kimochi o kinjienai.","en":"Hearing that news, I can't help but feel the urge to celebrate his success.","id":"Mendengar berita itu, mau tidak mau saya merasakan dorongan untuk merayakan kesuksesannya."},{"jp":"彼女の美しさには感動を禁じ得ない。","romaji":"Kanojo no utsukushisa ni wa kandō o kinjienai.","en":"I can't help but be moved by her beauty.","id":"Saya tidak bisa tidak tergerak oleh kecantikannya."},{"jp":"彼の話を聞いて、笑いを禁じ得ない。","romaji":"Kare no hanashi o kiite, warai o kinjienai.","en":"Hearing his story, I can't help but laugh.","id":"Mendengar ceritanya, saya tidak bisa menahan tawa."}]},{"pattern":"Noun を経て (〜wo hete)","meaning":"Expresses the idea of 'through' or 'via'; going through some process or phase.","meaningId":"Mengekspresikan gagasan 'melalui' atau 'melalui'; melalui beberapa proses atau fase.","formation":"Noun + を経て","formationId":"Kata benda + を経て","examples":[{"jp":"彼は苦労を経て成功を手に入れた。","romaji":"Kare wa kurō o hete seikō o te ni ireta.","en":"He achieved success through hardships.","id":"Dia mencapai kesuksesan melalui kesulitan."},{"jp":"彼女はニューヨークを経て日本に帰国した。","romaji":"Kanojo wa Nyūyōku o hete Nihon ni kikoku shita.","en":"She returned to Japan via New York.","id":"Dia kembali ke Jepang melalui New York."},{"jp":"私達は長い議論を経て決定を下した。","romaji":"Watashitachi wa nagai giron o hete kettei o kudashita.","en":"We made a decision through a long discussion.","id":"Kami mengambil keputusan melalui diskusi panjang."},{"jp":"多くの修練を経て、彼は達人のレベルになった。","romaji":"Ōku no shuren o hete, kare wa tatsujin no reberu ni natta.","en":"Through a lot of training, he reached a master's level.","id":"Melalui banyak pelatihan, ia mencapai tingkat master."}]},{"pattern":"Noun を踏まえて (〜wo fumaete)","meaning":"Based on; taking into account; in light of","meaningId":"Berdasarkan; dengan mempertimbangkan; dalam terang","formation":"Noun + を踏まえて","formationId":"Kata benda + を踏まえて","examples":[{"jp":"過去の結果を踏まえて、新たな計画を立てました。","romaji":"Kako no kekka o fumaete, aratana keikaku o tatemashita.","en":"Based on previous results, we have made a new plan.","id":"Berdasarkan hasil sebelumnya, kami telah membuat rencana baru."},{"jp":"現地の文化を踏まえて、プレゼンテーションを準備します。","romaji":"Genchi no bunka o fumaete, purezentēshon o junbi shimasu.","en":"I will prepare a presentation taking into account the local culture.","id":"Saya akan menyiapkan presentasi dengan mempertimbangkan budaya lokal."},{"jp":"教師の意見を踏まえて、規則を変更しました。","romaji":"Kyōshi no iken o fumaete, kisoku o henkō shimashita.","en":"We changed the rules in light of the teachers' opinions.","id":"Kami mengubah peraturan berdasarkan pendapat guru."},{"jp":"最新の研究結果を踏まえて、新しい薬が開発されました。","romaji":"Saishin no kenkyū kekka o fumaete, atarashii kusuri ga kaihatsu saremashita.","en":"Considering the latest research findings, a new medicine has been developed.","id":"Mengingat temuan penelitian terbaru, obat baru telah dikembangkan."}]},{"pattern":"Noun を限りに","meaning":"Expresses the idea of 'as of', 'with', or 'from', indicating the end of something or a point of change.","meaningId":"Mengekspresikan gagasan 'pada', 'dengan', atau 'dari', yang menunjukkan akhir dari sesuatu atau titik perubahan.","formation":"Noun + を限りに","formationId":"Kata benda + を限りに","examples":[{"jp":"今年度を限りに、この大学での教授活動を終えるつもりです。","romaji":"Konnendo o kagiri ni, kono daigaku de no kyouju katsudou o oeru tsumori desu.","en":"I intend to end my teaching activities at this university as of this academic year.","id":"Saya bermaksud untuk mengakhiri kegiatan mengajar saya di universitas ini pada tahun ajaran ini."},{"jp":"今日を限りに、タバコを吸うのをやめます。","romaji":"Kyou o kagiri ni, tabako o suu no o yamemasu.","en":"As of today, I will stop smoking.","id":"Mulai hari ini, saya akan berhenti merokok."},{"jp":"3月31日を限りに、会社を退職します。","romaji":"3-gatsu 31-nichi o kagiri ni, kaisha o taishoku shimasu.","en":"I will leave the company as of March 31.","id":"Saya akan meninggalkan perusahaan pada tanggal 31 Maret."},{"jp":"来週を限りに、この番組は終了します。","romaji":"Raishuu o kagiri ni, kono bangumi wa shuuryou shimasu.","en":"This program will end as of next week.","id":"Program ini akan berakhir pada minggu depan."}]},{"pattern":"Noun 並み","meaning":"Indicates 'like' or 'as' something or someone; 'equivalent to', 'around'.","meaningId":"Menunjukkan 'seperti' atau 'sebagai' sesuatu atau seseorang; 'setara dengan', 'sekitar'.","formation":"Noun + 並み","formationId":"Kata benda +並み","examples":[{"jp":"彼はプロのボクサー並みの力を持っています。","romaji":"Kare wa puro no bokusaa nami no chikara o motte imasu.","en":"He has power equivalent to a professional boxer.","id":"Ia memiliki kekuatan yang setara dengan petinju profesional."},{"jp":"彼女の料理の腕前はレストラン並みです。","romaji":"Kanojo no ryouri no udemae wa resutoran nami desu.","en":"Her cooking skills are like those of a restaurant.","id":"Keterampilan memasaknya seperti di restoran."},{"jp":"このエリアの夏は砂漠並みの暑さです。","romaji":"Kono eria no natsu wa sabaku nami no atsusa desu.","en":"The summer heat in this area is like a desert.","id":"Panasnya musim panas di kawasan ini seperti gurun pasir."},{"jp":"今日の仕事は社長並みの忙しさだった。","romaji":"Kyou no shigoto wa shachou nami no isogashisa datta.","en":"Today's work was as busy as a president's.","id":"Pekerjaan hari ini sama sibuknya dengan pekerjaan presiden."}]},{"pattern":"Noun + 前提で (Noun + zentei de)","meaning":"Expresses a condition or requirement for something to be established: 'on the assumption that', 'under the condition of'.","meaningId":"Menyatakan suatu kondisi atau persyaratan agar sesuatu dapat ditetapkan: 'dengan asumsi itu', 'di bawah kondisi'.","formation":"Noun + 前提で","formationId":"Kata benda + 前提で","examples":[{"jp":"説明できる英語力がある前提で、この仕事を引き受けてください。","romaji":"Setsumei dekiru eigo-ryoku ga aru zentei de, kono shigoto o hikiukete kudasai.","en":"Please take on this job on the assumption that you have enough English skills to explain.","id":"Silakan mengambil pekerjaan ini dengan asumsi Anda memiliki kemampuan bahasa Inggris yang cukup untuk menjelaskannya."},{"jp":"彼が一緒に行く前提で、旅行の計画を立てました。","romaji":"Kare ga issho ni iku zentei de, ryokou no keikaku o tatemashita.","en":"I planned the trip on the assumption that he would go together.","id":"Saya merencanakan perjalanan dengan asumsi dia akan pergi bersama."},{"jp":"成功する前提で、このプロジェクトを進めています。","romaji":"Seikou suru zentei de, kono purojekuto o susumete imasu.","en":"We are moving forward with this project on the assumption that we will succeed.","id":"Kami melanjutkan proyek ini dengan asumsi bahwa kami akan berhasil."},{"jp":"雨が降らない前提で、ピクニックの準備をしました。","romaji":"Ame ga furanai zentei de, pikunikku no junbi o shimashita.","en":"I prepared for the picnic under the condition that it wouldn't rain.","id":"Saya bersiap untuk piknik dengan syarat tidak hujan."}]},{"pattern":"Verbる / Noun(である) + 限り(は) (kagiri (wa))","meaning":"Expresses 'as long as', 'while this condition is true'.","meaningId":"Menyatakan 'selama', 'selama kondisi ini benar'.","formation":"Verb-dictionary form + 限り(は)\nNoun(である) + 限り(は)","formationId":"Bentuk kamus kata kerja + 限り(は)\nKata Benda(である) + 限り(は)","examples":[{"jp":"私が生きている限りは、あなたを支えます。","romaji":"Watashi ga ikite iru kagiri wa, anata o sasaemasu.","en":"As long as I'm alive, I will support you.","id":"Selama aku masih hidup, aku akan mendukungmu."},{"jp":"子供が学校に通っている限り、私たちは彼らを守ります。","romaji":"Kodomo ga gakkou ni kayotte iru kagiri, watashitachi wa karera o mamorimasu.","en":"As long as the kids are going to school, we will protect them.","id":"Selama anak-anak masih bersekolah, kami akan melindungi mereka."},{"jp":"能力がある限り、最善を尽くします。","romaji":"Nouryoku ga aru kagiri, saizen o tsukushimasu.","en":"I will do my best as long as I have the ability.","id":"Saya akan melakukan yang terbaik selama saya memiliki kemampuan."},{"jp":"あなたがここにいる限り、私は安心です。","romaji":"Anata ga koko ni iru kagiri, watashi wa anshin desu.","en":"As long as you're here, I feel safe.","id":"Selama kamu di sini, aku merasa aman."}]},{"pattern":"Verb がてら","meaning":"Expresses doing something while doing another; 'while', 'on the occasion of'.","meaningId":"Mengekspresikan melakukan sesuatu sambil melakukan yang lain; 'sementara', 'pada kesempatan'.","formation":"Verb (dictionary or -ます stem) + がてら","formationId":"Kata kerja (kamus atau batang -ます) + がてら","examples":[{"jp":"散歩がてらに郵便局へ行った。","romaji":"Sanpo gatera ni yūbinkyoku e itta.","en":"I went to the post office while taking a walk.","id":"Saya pergi ke kantor pos sambil berjalan-jalan."},{"jp":"買い物がてらに友達に会いに行った。","romaji":"Kaimono gatera ni tomodachi ni ai ni itta.","en":"I went to see a friend while doing some shopping.","id":"Saya pergi menemui seorang teman sambil berbelanja."},{"jp":"ジョギングがてらに新聞を買いに行った。","romaji":"Jogingu gatera ni shinbun o kai ni itta.","en":"I went to buy a newspaper while jogging.","id":"Saya pergi membeli koran sambil jogging."},{"jp":"公園でピクニックがてら読書をした。","romaji":"Kōen de pikunikku gatera dokusho o shita.","en":"I read a book while having a picnic in the park.","id":"Saya membaca buku sambil piknik di taman."}]},{"pattern":"Verb こそすれ","meaning":"Often used in the pattern 'Xこそすれ、Y〜ない', meaning 'One might do X, but definitely not Y'.","meaningId":"Sering digunakan dalam pola 'Xこそすれ、Y〜ない', yang berarti 'Seseorang mungkin melakukan X, tapi jelas bukan Y'.","formation":"Verb-ますstem + こそすれ、(絶対に)～ない","formationId":"Kata kerja-ますbatang + こそすれ、(絶対に)～ない","examples":[{"jp":"彼は友達を助けこそすれ、自分を卑下することはありません。","romaji":"Kare wa tomodachi o tasuke koso sure, jibun o higesuru koto wa arimasen.","en":"He might help his friends, but he never belittles himself.","id":"Dia mungkin membantu teman-temannya, tapi dia tidak pernah meremehkan dirinya sendiri."},{"jp":"彼女は料理こそすれ、掃除はほとんどしない。","romaji":"Kanojo wa ryōri koso sure, sōji wa hotondo shinai.","en":"She might cook, but she rarely cleans.","id":"Dia mungkin memasak, tapi dia jarang bersih-bersih."},{"jp":"私の兄は勉強こそすれ、遊ぶ時間がほとんどない。","romaji":"Watashi no ani wa benkyō koso sure, asobu jikan ga hotondo nai.","en":"He might study a lot, but he barely has time to have fun.","id":"Dia mungkin banyak belajar, tapi dia hampir tidak punya waktu untuk bersenang-senang."},{"jp":"母は働きこそすれ、自分のために時間を使うことはほとんどない。","romaji":"Haha wa hataraki koso sure, jibun no tame ni jikan o tsukau koto wa hotondo nai.","en":"My mother might work a lot, but she hardly spends any time on herself.","id":"Ibuku mungkin banyak bekerja, tapi dia jarang meluangkan waktu untuk dirinya sendiri."}]},{"pattern":"Verb させられる","meaning":"Expresses 'being forced to do something' or 'being made to do something'.","meaningId":"Mengekspresikan 'dipaksa melakukan sesuatu' atau 'dipaksa melakukan sesuatu'.","formation":"Verb-casual (non-past) + させられる","formationId":"Kata kerja-kasual (bukan masa lalu) + させられる","examples":[{"jp":"彼に無理やり飲ませられた。","romaji":"Kare ni muriyari nomaserareta.","en":"He forced me to drink against my will.","id":"Dia memaksaku untuk minum di luar keinginanku."},{"jp":"私は父に勉強させられました。","romaji":"Watashi wa chichi ni benkyō saseraremashita.","en":"My father made me study.","id":"Ayahku menyuruhku belajar."},{"jp":"子供たちは毎日ピアノを弾かせられる。","romaji":"Kodomo-tachi wa mainichi piano o hikaserareru.","en":"The kids are made to play the piano every day.","id":"Anak-anak disuruh bermain piano setiap hari."},{"jp":"私たちは強制的に早起きさせられました。","romaji":"Watashitachi wa kyōsei-teki ni hayaoki saseraremashita.","en":"We were forcibly made to wake up early.","id":"Kami dipaksa bangun pagi-pagi."}]},{"pattern":"Verb ざるを得ない","meaning":"'Cannot but', 'have no choice but to', 'forced to'","meaningId":"'Tidak bisa tapi', 'tidak punya pilihan selain', 'terpaksa'","formation":"Verb-dictionary form + ざるを得ない (する → せざるを得ない)","formationId":"Bentuk kamus kata kerja + ざるを得ない (する → せざるを得ない)","examples":[{"jp":"この仕事が嫌ならもう辞めざるを得ない。","romaji":"Kono shigoto ga iya nara mō yamezaru o enai.","en":"If you hate this job, you have no choice but to quit.","id":"Jika Anda membenci pekerjaan ini, Anda tidak punya pilihan selain berhenti."},{"jp":"試験が近いので、夜遅くまで勉強せざるを得ない。","romaji":"Shiken ga chikai no de, yoru osoku made benkyō sezaru o enai.","en":"The exam is near, so I have no choice but to study late into the night.","id":"Ujiannya sudah dekat, jadi aku tidak punya pilihan selain belajar hingga larut malam."},{"jp":"涙が止まらない。泣かざるを得ない。","romaji":"Namida ga tomaranai. Nakazaru o enai.","en":"My tears won't stop. I can't help but cry.","id":"Air mataku tidak mau berhenti. Saya tidak bisa menahan tangis."},{"jp":"先生の命令だから、従わざるを得ない。","romaji":"Sensei no meirei dakara, shitagawazaru o enai.","en":"It's the teacher's order, so I have no choice but to comply.","id":"Itu perintah guru, jadi aku tidak punya pilihan selain menurutinya."}]},{"pattern":"Verb ずじまい","meaning":"Expressing regret for not having done something; not being able to; missing the chance to do it.","meaningId":"Mengekspresikan penyesalan karena tidak melakukan sesuatu; tidak bisa; kehilangan kesempatan untuk melakukannya.","formation":"Verb-ない form (remove ない) + ずじまい","formationId":"Bentuk kata kerja-ない (hapus ない) + ずじまい","examples":[{"jp":"日本へ来たのに、一度も富士山を見ずじまいで帰国してしまった。","romaji":"Nihon e kita noni, ichidomo Fuji-san o mizu jimai de kikoku shite shimatta.","en":"I came to Japan but ended up going home without ever getting to see Mt. Fuji.","id":"Saya datang ke Jepang tetapi akhirnya pulang ke rumah tanpa pernah melihat Gunung Fuji."},{"jp":"出張のため、彼女に会わずじまいだった。","romaji":"Shucchō no tame, kanojo ni awazu jimai datta.","en":"Because I was on a business trip, I ended up not meeting her.","id":"Karena saya sedang dalam perjalanan bisnis, saya akhirnya tidak bertemu dengannya."},{"jp":"昨日は疲れすぎて、宿題をせずじまいだ。","romaji":"Kinō wa tsukare-sugite, shukudai o sezu jimai da.","en":"I was too tired yesterday and ended up not doing my homework.","id":"Saya terlalu lelah kemarin dan akhirnya tidak mengerjakan pekerjaan rumah saya."},{"jp":"着物を買ったが、結局、一度も着ずじまいだ。","romaji":"Kimono o katta ga, kekkyoku, ichido mo kizu jimai da.","en":"I bought a kimono, but in the end, I never got the chance to wear it.","id":"Saya membeli kimono, tetapi pada akhirnya saya tidak pernah sempat memakainya."}]},{"pattern":"Verb ずとも (〜zu tomo)","meaning":"Means 'Even without doing (X), (Y) can still happen'.","meaningId":"Berarti 'Bahkan tanpa melakukan (X), (Y) masih bisa terjadi'.","formation":"Verb-negative stem + ずとも","formationId":"Batang kata kerja negatif + ずとも","examples":[{"jp":"朝ごはんを食べずとも、働くことができます。","romaji":"Asagohan o tabezu tomo, hataraku koto ga dekimasu.","en":"Even without eating breakfast, I can work.","id":"Bahkan tanpa sarapan pun, saya bisa bekerja."},{"jp":"車がなくとも、バスで行くことができます。","romaji":"Kuruma ga nakutomo, basu de iku koto ga dekimasu.","en":"Even without a car, you can go by bus.","id":"Meski tanpa mobil, Anda bisa naik bus."},{"jp":"お金がなくとも、幸せになれる。","romaji":"Okane ga nakutomo, shiawase ni nareru.","en":"Even without money, one can be happy.","id":"Tanpa uang pun seseorang bisa bahagia."},{"jp":"インターネットがなくとも、情報を得る方法はいくつかあります。","romaji":"Intānetto ga nakutomo, jōhō o eru hōhō wa ikutsu ka arimasu.","en":"Even without the internet, there are several ways to obtain information.","id":"Meski tanpa internet, ada beberapa cara untuk memperoleh informasi."}]},{"pattern":"Verb ずにはおかない","meaning":"Expresses 'cannot help but...', 'will definitely...', or 'must do something'.","meaningId":"Menyatakan 'tidak dapat membantu tetapi...', 'pasti akan...', atau 'harus melakukan sesuatu'.","formation":"Verb-ない form (remove ない) + ずにはおかない","formationId":"Bentuk kata kerja-ない (hapus ない) + ずにはおかない","examples":[{"jp":"彼が困っていると聞いたら、助けずにはおかない。","romaji":"Kare ga komatte iru to kiitara, tasukezuni wa okanai.","en":"If I hear he is in trouble, I cannot help but assist him.","id":"Jika saya mendengar dia dalam kesulitan, saya tidak bisa tidak membantunya."},{"jp":"食事の準備がこのままだと、手伝わずにはおかないだろう。","romaji":"Shokuji no junbi ga kono mama da to, tetsudawazuni wa okanai darō.","en":"If the meal prep stays like this, I won't be able to stop myself from helping.","id":"Jika persiapan makannya tetap seperti ini, aku tidak akan bisa menahan diri untuk membantu."},{"jp":"この問題が解決しないなら、改善策を考えずにはおかない。","romaji":"Kono mondai ga kaiketsu shinai nara, kaizen-saku o kangaezuni wa okanai.","en":"If this issue isn't resolved, I can't help but think of a solution.","id":"Jika masalah ini tidak terselesaikan, saya tidak bisa tidak memikirkan solusinya."},{"jp":"彼女が泣いているのを見たら、慰めずにはおかない。","romaji":"Kanojo ga naite iru no o mitara, nagusamezuni wa okanai.","en":"When I see her crying, I cannot help but comfort her.","id":"Ketika saya melihatnya menangis, saya tidak bisa tidak menghiburnya."}]},{"pattern":"Verb ずにはすまない","meaning":"'Cannot do without...', 'unavoidable', 'have to'.","meaningId":"'Tidak dapat dilakukan tanpa...', 'tidak dapat dihindari', 'harus'.","formation":"Verb-ない form (remove ない) + ずにはすまない","formationId":"Bentuk kata kerja-ない (hapus ない) + ずにはすまない","examples":[{"jp":"この問題を解決しないと、社会全体が影響を受けるので、解決せずにはすまない。","romaji":"Kono mondai o kaiketsu shinai to, shakai zentai ga eikyō o ukeru node, kaiketsu sezu ni wa sumanai.","en":"Since this issue will affect the entire society if not resolved, we cannot do without solving it.","id":"Karena masalah ini akan berdampak pada seluruh masyarakat jika tidak diselesaikan, kita tidak dapat melakukan tanpa menyelesaikannya."},{"jp":"これは子供たちの未来を思うと、教育改革を行わずにはすまないことだ。","romaji":"Kore wa kodomo-tachi no mirai o omou to, kyōiku kaikaku o okonawazu ni wa sumanai koto da.","en":"For the sake of the children’s future, we cannot avoid carrying out educational reforms.","id":"Demi masa depan anak, kita tidak bisa menghindari melakukan reformasi pendidikan."},{"jp":"この件については、彼に謝らずにはすまない。","romaji":"Kono ken ni tsuite wa, kare ni ayamarazu ni wa sumanai.","en":"Regarding this matter, I can’t do without apologizing to him.","id":"Mengenai masalah ini, aku tidak bisa melakukannya tanpa meminta maaf padanya."},{"jp":"結婚式に出席するなら、プレゼントを渡さずにはすまない。","romaji":"Kekkonshiki ni shusseki suru nara, purezento o watasazu ni wa sumanai.","en":"If you attend a wedding, you have to bring a gift.","id":"Jika Anda menghadiri pesta pernikahan, Anda wajib membawa oleh-oleh."}]},{"pattern":"Verb そうにない","meaning":"Expresses unlikelihood or that something does not seem likely to happen.","meaningId":"Mengekspresikan kemungkinan atau sesuatu yang tampaknya tidak mungkin terjadi.","formation":"Verb-ますstem + そうにない","formationId":"Kata kerja-ますbatang + そうにない","examples":[{"jp":"彼はそんなに早く走れそうにない。","romaji":"Kare wa sonna ni hayaku hashire sō ni nai.","en":"He doesn't seem likely to run that fast.","id":"Sepertinya dia tidak akan berlari secepat itu."},{"jp":"この書類を明日までに終わりそうにない。","romaji":"Kono shorui o ashita made ni owarisō ni nai.","en":"It doesn’t seem like I’ll be able to finish these documents by tomorrow.","id":"Sepertinya saya tidak akan bisa menyelesaikan dokumen-dokumen ini besok."},{"jp":"今日雨が降りそうにない。","romaji":"Kyō ame ga furisō ni nai.","en":"It doesn't look like it will rain today.","id":"Sepertinya hari ini tidak akan turun hujan."},{"jp":"彼女は間違えそうにない。","romaji":"Kanojo wa machigae sō ni nai.","en":"She doesn’t seem likely to make a mistake.","id":"Sepertinya dia tidak akan melakukan kesalahan."}]},{"pattern":"Verb そうもない (〜sou mo nai)","meaning":"Expresses negative potential; 'it doesn't seem like...', 'it's not likely...'.","meaningId":"Mengekspresikan potensi negatif; 'sepertinya tidak...', 'tidak mungkin...'.","formation":"Verb-ますstem + そうもない","formationId":"Kata Kerja-ますbatang + そうもない","examples":[{"jp":"今日中に仕事を終えそうもない。","romaji":"Kyōjū ni shigoto o oesō mo nai.","en":"It doesn't seem like I'll finish my work today.","id":"Sepertinya aku tidak akan menyelesaikan pekerjaanku hari ini."},{"jp":"雨が止みそうもない。","romaji":"Ame ga yamisō mo nai.","en":"It doesn't seem like the rain will stop.","id":"Sepertinya hujan tidak akan berhenti."},{"jp":"彼が約束を守りそうもない。","romaji":"Kare ga yakusoku o mamorisō mo nai.","en":"It doesn't seem like he will keep his promise.","id":"Sepertinya dia tidak akan menepati janjinya."},{"jp":"この難しい問題は解決しそうもない。","romaji":"Kono muzukashii mondai wa kaiketsu shisō mo nai.","en":"It doesn't seem like this difficult problem will be solved.","id":"Masalah sulit ini sepertinya tidak akan terselesaikan."}]},{"pattern":"Verb そばから (〜soba kara)","meaning":"Expresses that as soon as one action finishes, another begins immediately.","meaningId":"Menyatakan bahwa segera setelah satu tindakan selesai, tindakan lainnya segera dimulai.","formation":"Verb-ますstem + そばから","formationId":"Kata kerja-ますbatang + そばから","examples":[{"jp":"掃除をするそばから子供たちが散らかす。","romaji":"Sōji o suru soba kara kodomo-tachi ga chirakasu.","en":"As soon as I clean, the kids mess it up.","id":"Begitu saya bersih-bersih, anak-anak mengacaukannya."},{"jp":"仕事を終えるそばから新たな仕事が舞い込んできた。","romaji":"Shigoto o oeru soba kara aratana shigoto ga maikonde kita.","en":"As soon as I finished my work, a new task came in.","id":"Segera setelah saya menyelesaikan pekerjaan saya, tugas baru masuk."},{"jp":"それを解決するそばからまた別の問題が出てきた。","romaji":"Sore o kaiketsu suru soba kara mata betsu no mondai ga detekita.","en":"As soon as we solve that, another problem arises.","id":"Begitu kita menyelesaikannya, masalah lain muncul."},{"jp":"眠りにつくそばから電話が鳴った。","romaji":"Nemuri ni tsuku soba kara denwa ga natta.","en":"The phone rang as soon as I fell asleep.","id":"Telepon berdering segera setelah saya tertidur."}]},{"pattern":"Verb たが最後 (〜ta ga saigo)","meaning":"Emphasizes 'once something happens, there is no going back'; 'once', 'as soon as', etc.","meaningId":"Menekankan 'sekali sesuatu terjadi, tidak ada jalan untuk kembali'; 'sekali', 'segera', dan seterusnya.","formation":"Verb-casual, past (た form) + が最後","formationId":"Kata kerja kasual, lampau (bentuk た) + が最後","examples":[{"jp":"彼が一度怒ったが最後、誰も彼を止めることはできません。","romaji":"Kare ga ichido okotta ga saigo, dare mo kare o tomeru koto wa dekimasen.","en":"Once he gets angry, no one can stop him.","id":"Begitu dia marah, tidak ada yang bisa menghentikannya."},{"jp":"このゲームを始めたが最後、一晩中やり続けた。","romaji":"Kono gēmu o hajimeta ga saigo, hitobanjū yari tsuzuketa.","en":"As soon as I started this game, I played it all night.","id":"Segera setelah saya memulai permainan ini, saya memainkannya sepanjang malam."},{"jp":"彼女が部屋を出たが最後、二度と戻ってこなかった。","romaji":"Kanojo ga heya o deta ga saigo, nido to modotte konakatta.","en":"The moment she left the room, she never came back.","id":"Saat dia meninggalkan ruangan, dia tidak pernah kembali."},{"jp":"私がその橋を渡ったが最後、それが最後の別れだった。","romaji":"Watashi ga sono hashi o watatta ga saigo, sore ga saigo no wakare datta.","en":"Once I crossed that bridge, it was our final goodbye.","id":"Begitu saya menyeberangi jembatan itu, itu adalah perpisahan terakhir kami."}]},{"pattern":"Verb たことにしてください","meaning":"Asking someone to pretend or accept that something has already happened or taken a certain state.","meaningId":"Meminta seseorang untuk berpura-pura atau menerima bahwa sesuatu telah terjadi atau terjadi keadaan tertentu.","formation":"Verb (past, casual) + ことにしてください","formationId":"Kata kerja (masa lalu, santai) + ことにしてください","examples":[{"jp":"昨日のことは忘れたことにしてください。","romaji":"Kinou no koto wa wasureta koto ni shite kudasai.","en":"Please act as if you have forgotten about yesterday.","id":"Tolong bersikaplah seolah-olah kamu sudah melupakan kejadian kemarin."},{"jp":"私がここに来たことを誰にも言わないで、秘密にしたことにしてください。","romaji":"Watashi ga koko ni kita koto o dare ni mo iwanaide, himitsu ni shita koto ni shite kudasai.","en":"Please don't tell anyone that I came here; act as if it’s a secret.","id":"Tolong jangan beri tahu siapa pun bahwa saya datang ke sini; bertindak seolah-olah itu adalah rahasia."},{"jp":"彼が間違えたと思ったことにしてください。","romaji":"Kare ga machigaeta to omotta koto ni shite kudasai.","en":"Please pretend that you think he made a mistake.","id":"Silakan berpura-pura bahwa menurut Anda dia melakukan kesalahan."},{"jp":"彼女が帰ったことにしてください。","romaji":"Kanojo ga kaetta koto ni shite kudasai.","en":"Let’s pretend that she has gone home.","id":"Anggap saja dia sudah pulang."}]},{"pattern":"Verb たら Verb たで","meaning":"Conveys that if something happens (or doesn’t happen), there is a particular consequence or situation either way.","meaningId":"Menyampaikan bahwa jika sesuatu terjadi (atau tidak terjadi), pasti ada konsekuensi atau situasi tertentu.","formation":"Verb-た form + ら + (same Verb-た form) + で","formationId":"Bentuk kata kerja-た + ら + (bentuk kata kerja-た yang sama) + で","examples":[{"jp":"行ったら行ったで大変だし、行かなかったら行かなかったで後悔しそうだ。","romaji":"Ittara itta de taihen da shi, ikanakattara ikanakatta de kōkai shisō da.","en":"If I go, it’s a hassle; if I don’t go, I’ll regret it.","id":"Jika saya pergi, itu merepotkan; jika aku tidak pergi, aku akan menyesalinya."},{"jp":"買ったら買ったでお金がなくなるし、買わなかったら買わなかったで後で欲しくなる。","romaji":"Kattara katta de okane ga naku naru shi, kawanakattara kawanakatta de ato de hoshiku naru.","en":"If I buy it, I’ll run out of money; if I don’t buy it, I’ll want it later.","id":"Jika saya membelinya, saya akan kehabisan uang; jika saya tidak membelinya, saya akan menginginkannya nanti."},{"jp":"作ったら作ったで食べきれないし、作らなかったら作らなかったでお腹が空く。","romaji":"Tsukuttara tsukutta de tabekirenai shi, tsukuranakattara tsukuranakatta de onaka ga suku.","en":"If I cook, I can’t finish it all; if I don’t, I’ll be hungry.","id":"Jika saya memasak, saya tidak bisa menghabiskan semuanya; jika tidak, aku akan lapar."},{"jp":"旅行に出かけたら出かけたで疲れるし、家にいたらいたで退屈する。","romaji":"Ryokō ni dekaketara dekaketa de tsukareru shi, ie ni itara itada de taikutsu suru.","en":"If I go on a trip, I'll get tired, but if I stay home, I'll be bored.","id":"Jika aku bepergian, aku akan lelah, tetapi jika aku berdiam diri di rumah, aku akan bosan."}]},{"pattern":"Verb たら きりがない","meaning":"Indicates an endless or unending cycle once an action is started; 'if one starts doing something, it will not stop.'","meaningId":"Menunjukkan siklus tanpa akhir atau tanpa akhir setelah suatu tindakan dimulai; 'jika seseorang mulai melakukan sesuatu, ia tidak akan berhenti.'","formation":"Verb-た form + ら + きりがない","formationId":"Bentuk kata kerja-た + ら + きりがない","examples":[{"jp":"このエンジンを修理したら、またすぐ壊れて、直したらきりがない。","romaji":"Kono enjin o shuuri shitara, mata sugu kowarete, naoshitara kiri ga nai.","en":"If I fix this engine, it breaks again, and if I fix it again, it never ends.","id":"Kalau saya perbaiki mesin ini rusak lagi, dan kalau saya perbaiki lagi tidak ada habisnya."},{"jp":"飲み始めたらきりがない。","romaji":"Nomihajimetara kiri ga nai.","en":"Once I start drinking, I never stop.","id":"Begitu saya mulai minum, saya tidak pernah berhenti."},{"jp":"彼女にお金を貸したら、きりがない。","romaji":"Kanojo ni okane o kashitara, kiri ga nai.","en":"If I lend her money, there will be no end to it.","id":"Jika saya meminjamkan uang kepadanya, tidak akan ada habisnya."},{"jp":"彼の話を聞き始めたらきりがない。","romaji":"Kare no hanashi o kikihajimetara kiri ga nai.","en":"Once you start listening to his stories, it never ends.","id":"Begitu Anda mulai mendengarkan ceritanya, itu tidak akan pernah berakhir."}]},{"pattern":"Verb たら最後 (〜tara saigo)","meaning":"Expresses that once a certain action happens, the situation changes irreversibly—usually in a negative way.","meaningId":"Menyatakan bahwa ketika suatu tindakan tertentu terjadi, situasinya akan berubah secara permanen—biasanya dalam arah yang negatif.","formation":"Verb-た form + ら最後","formationId":"Bentuk kata kerja-た + ら最後","examples":[{"jp":"このゲームを始めたら最後、時間の経つのを忘れてしまいます。","romaji":"Kono gēmu o hajimetara saigo, jikan no tatsu no o wasurete shimaimasu.","en":"Once you start this game, you completely lose track of time.","id":"Begitu Anda memulai permainan ini, Anda benar-benar lupa waktu."},{"jp":"彼はビールを一杯飲み始めたら最後、止まらなくなります。","romaji":"Kare wa bīru o ippai nomihajimetara saigo, tomaranaku narimasu.","en":"Once he starts drinking a beer, he can't stop.","id":"Begitu dia mulai minum bir, dia tidak bisa berhenti."},{"jp":"この本を読み始めたら最後、一気に読破してしまいました。","romaji":"Kono hon o yomihajimetara saigo, ikki ni dokuha shite shimaimashita.","en":"Once I started reading this book, I ended up finishing it in one go.","id":"Begitu saya mulai membaca buku ini, saya akhirnya menyelesaikannya sekaligus."},{"jp":"彼を怒らせたら最後、なかなか許してもらえないよ。","romaji":"Kare o okorasetara saigo, nakanaka yurushite moraenai yo.","en":"Once you make him angry, he won't forgive you so easily.","id":"Sekali Anda membuatnya marah, dia tidak akan memaafkan Anda dengan mudah."}]},{"pattern":"Verb つ Verb つ","meaning":"Expresses two alternating actions happening repeatedly.","meaningId":"Mengekspresikan dua tindakan bergantian yang terjadi berulang kali.","formation":"Verb-ますstem + つ + Verb-ますstem + つ","formationId":"Kata Kerja-ますbatang + つ + Kata Kerja-ますbatang + つ","examples":[{"jp":"朝から晩まで働きつ勉強しつで、疲れてしまった。","romaji":"Asa kara ban made hataraki tsu benkyō shi tsu de, tsukarete shimatta.","en":"I’ve been working and studying from morning till night, and now I’m exhausted.","id":"Saya telah bekerja dan belajar dari pagi hingga malam, dan sekarang saya kelelahan."},{"jp":"彼は話しつ笑いつして楽しんでいた。","romaji":"Kare wa hanashi tsu warai tsu shite tanoshinde ita.","en":"He was talking and laughing, having a good time.","id":"Dia berbicara dan tertawa, bersenang-senang."},{"jp":"子供たちは食べつ遊びつしていた。","romaji":"Kodomo-tachi wa tabe tsu asobi tsu shite ita.","en":"The children were eating and playing.","id":"Anak-anak sedang makan dan bermain."},{"jp":"私は読みつ書きつして過ごした。","romaji":"Watashi wa yomi tsu kaki tsu shite sugoshita.","en":"I spent my time reading and writing.","id":"Aku menghabiskan waktuku dengan membaca dan menulis."}]},{"pattern":"Verb てからというもの","meaning":"Expresses that ever since a certain event happened, a condition has continued until now.","meaningId":"Mengungkapkan bahwa sejak suatu peristiwa tertentu terjadi, suatu kondisi terus berlanjut hingga saat ini.","formation":"Verb-て form + からというもの","formationId":"Bentuk kata kerja-て + からというもの","examples":[{"jp":"彼女と別れてからというもの、一人で過ごす時間が増えました。","romaji":"Kanojo to wakarete kara to iu mono, hitori de sugosu jikan ga fuemashita.","en":"Ever since I broke up with her, I've spent more time alone.","id":"Sejak aku putus dengannya, aku menghabiskan lebih banyak waktu sendirian."},{"jp":"子供が生まれてからというもの、自由な時間がなくなった。","romaji":"Kodomo ga umarete kara to iu mono, jiyū na jikan ga nakunatta.","en":"Since the baby was born, I have had no free time.","id":"Sejak bayi saya lahir, saya tidak punya waktu luang."},{"jp":"新しい仕事を始めてからというもの、毎日忙しくなりました。","romaji":"Atarashii shigoto o hajimete kara to iu mono, mainichi isogashiku narimashita.","en":"Ever since I started my new job, I've been busy every day.","id":"Sejak saya memulai pekerjaan baru saya, saya sibuk setiap hari."},{"jp":"大学に入ってからというもの、スポーツをする時間がなくなった。","romaji":"Daigaku ni haitte kara to iu mono, supōtsu o suru jikan ga nakunatta.","en":"I haven’t had time to play sports since I entered university.","id":"Saya belum punya waktu untuk berolahraga sejak saya masuk universitas."}]},{"pattern":"Verb てこそ","meaning":"Emphasizes 'only by doing something, a certain result or realization can occur.'","meaningId":"Menekankan 'hanya dengan melakukan sesuatu, hasil atau realisasi tertentu dapat terjadi.'","formation":"Verb-て form + こそ","formationId":"Bentuk kata kerja-て + こそ","examples":[{"jp":"実際に使ってこそ、その価値を理解できる。","romaji":"Jissai ni tsukatte koso, sono kachi o rikai dekiru.","en":"You can only understand its value by actually using it.","id":"Anda hanya dapat memahami nilainya dengan benar-benar menggunakannya."},{"jp":"自分で経験してこそ、大切なことが学べる。","romaji":"Jibun de keiken shite koso, taisetsu na koto ga manaberu.","en":"Only by experiencing it yourself can you learn what’s truly important.","id":"Hanya dengan mengalaminya sendiri Anda dapat mempelajari apa yang benar-benar penting."},{"jp":"失敗してこそ、成功の味がわかる。","romaji":"Shippai shite koso, seikō no aji ga wakaru.","en":"Only by failing do you really understand the taste of success.","id":"Hanya dengan kegagalan Anda benar-benar memahami rasa kesuksesan."},{"jp":"努力してこそ、何かを成し遂げることができる。","romaji":"Doryoku shite koso, nanika o nashitogeru koto ga dekiru.","en":"Only through making an effort can you accomplish anything.","id":"Hanya dengan berusaha Anda dapat mencapai apa pun."}]},{"pattern":"Verb ては","meaning":"Expresses a repeated pattern or cycle, often implying a frustrating outcome; 'whenever X happens, Y happens again.'","meaningId":"Mengekspresikan pola atau siklus yang berulang, sering kali menyiratkan hasil yang membuat frustrasi; 'setiap kali X terjadi, Y terjadi lagi.'","formation":"Verb-て form + は","formationId":"Bentuk kata kerja-て + は","examples":[{"jp":"彼女に会っては、いつも緊張してしまいます。","romaji":"Kanojo ni atte wa, itsumo kinchō shite shimaimasu.","en":"Whenever I meet her, I get nervous.","id":"Setiap kali saya bertemu dengannya, saya merasa gugup."},{"jp":"この部屋を掃除しては乱雑になり、片づけては散らかる。","romaji":"Kono heya o sōji shite wa konzatsu ni nari, katadzukete wa chirakaru.","en":"Whenever I clean this room, it gets messy again, and whenever I tidy it, it gets cluttered again.","id":"Setiap kali saya membersihkan ruangan ini, ruangan ini menjadi berantakan lagi, dan setiap kali saya merapikannya, ruangan ini menjadi berantakan lagi."},{"jp":"運動しては食べ、食べては運動する生活が続いている。","romaji":"Undō shite wa tabe, tabete wa undō suru seikatsu ga tsudzuite iru.","en":"I keep exercising and then eating, and then eating and exercising.","id":"Saya terus berolahraga, lalu makan, lalu makan dan berolahraga."},{"jp":"勉強しては寝て、寝ては勉強する日々です。","romaji":"Benkyō shite wa nete, nete wa benkyō suru hibi desu.","en":"My days are spent studying and then sleeping, and then sleeping and studying.","id":"Hari-hariku dihabiskan dengan belajar lalu tidur, lalu tidur dan belajar."}]},{"pattern":"Verb ては Verb","meaning":"Expresses a repeated pattern of action; translates as 'every time', 'whenever', etc.","meaningId":"Mengekspresikan pola tindakan yang berulang; diterjemahkan sebagai 'setiap saat', 'kapan saja', dll.","formation":"Verb-て form + は + Verb","formationId":"Bentuk kata kerja-て + は + Kata Kerja","examples":[{"jp":"私が通勤しては、電子書籍を読んでいます。","romaji":"Watashi ga tsūkin shite wa, denshi shoseki o yonde imasu.","en":"Whenever I commute, I read e-books.","id":"Setiap kali saya bepergian, saya membaca e-book."},{"jp":"友達が部屋に来ては、ゲームをしています。","romaji":"Tomodachi ga heya ni kite wa, gēmu o shite imasu.","en":"Every time my friend comes to my room, we play games.","id":"Setiap kali teman saya datang ke kamar saya, kami bermain game."},{"jp":"彼が酒を飲んでは、運転を止めさせています。","romaji":"Kare ga sake o nonde wa, unten o tome sasete imasu.","en":"Whenever he drinks alcohol, I make him stop driving.","id":"Setiap kali dia minum alkohol, saya membuatnya berhenti mengemudi."},{"jp":"私が新しい曲を作っては、すぐに録音します。","romaji":"Watashi ga atarashii kyoku o tsukutte wa, sugu ni rokuon shimasu.","en":"Every time I create a new song, I record it immediately.","id":"Setiap kali saya membuat lagu baru, saya langsung merekamnya."}]},{"pattern":"Verb てまでも","meaning":"Expresses 'even if it means doing...', 'no matter what it takes'.","meaningId":"Menyatakan 'bahkan jika itu berarti melakukan...', 'tidak peduli apa pun yang diperlukan'.","formation":"Verb-て form + までも","formationId":"Bentuk kata kerja-て + までも","examples":[{"jp":"試験に合格するために、寝る時間を削ってまでも勉強します。","romaji":"Shiken ni gōkaku suru tame ni, neru jikan o kezutte mademo benkyō shimasu.","en":"I will study to pass the exam, even if it means cutting down on sleep.","id":"Saya akan belajar untuk lulus ujian, meskipun itu berarti mengurangi waktu tidur."},{"jp":"彼女と結婚できるなら、どんな苦労をしてまでもお金を貯めたい。","romaji":"Kanojo to kekkon dekiru nara, donna kurō o shite mademo okane o tametai.","en":"If I can marry her, I'll save money no matter what hardships it takes.","id":"Jika saya bisa menikahinya, saya akan menghemat uang tidak peduli seberapa sulitnya."},{"jp":"この会社で働きたいので、長時間かけてまでも通います。","romaji":"Kono kaisha de hatarakitai node, chōjikan kakete mademo kayoimasu.","en":"Because I want to work at this company, I'll commute even if it means spending hours traveling.","id":"Karena saya ingin bekerja di perusahaan ini, saya akan bepergian walaupun harus menghabiskan waktu berjam-jam di perjalanan."},{"jp":"彼の快復のためなら、何をしてまでも支えたい。","romaji":"Kare no kaifuku no tame nara, nani o shite mademo sasaetai.","en":"For his recovery, I'll support him no matter what it takes.","id":"Untuk kesembuhannya, saya akan mendukungnya apa pun yang terjadi."}]},{"pattern":"Verb てみせる","meaning":"'Show by doing', 'demonstrate', 'prove by action'.","meaningId":"'Tunjukkan dengan melakukan', 'menunjukkan', 'membuktikan dengan tindakan'.","formation":"Verb-て form + みせる","formationId":"Bentuk kata kerja-て + みせる","examples":[{"jp":"彼はそのパズルを解いてみせた。","romaji":"Kare wa sono pazuru o toite miseta.","en":"He solved the puzzle to show me.","id":"Dia memecahkan teka-teki untuk ditunjukkan kepadaku."},{"jp":"私はこの仕事ができることをやってみせます。","romaji":"Watashi wa kono shigoto ga dekiru koto o yatte misemasu.","en":"I will do this job to prove that I can.","id":"Saya akan melakukan pekerjaan ini untuk membuktikan bahwa saya bisa."},{"jp":"彼女は試験に合格するために一生懸命勉強してみせました。","romaji":"Kanojo wa shiken ni gōkaku suru tame ni isshōkenmei benkyō shite misemashita.","en":"She studied hard to prove she could pass the exam.","id":"Dia belajar keras untuk membuktikan bahwa dia bisa lulus ujian."},{"jp":"彼は自分が何も恐れていないと跳んでみせた。","romaji":"Kare wa jibun ga nanimo osorete inai to tonde miseta.","en":"He jumped to show he wasn’t afraid of anything.","id":"Dia melompat untuk menunjukkan bahwa dia tidak takut pada apa pun."}]},{"pattern":"Verb てやまない","meaning":"Used with certain emotional/mental verbs to show a strong, unceasing emotion: 'can't stop', 'never cease to'.","meaningId":"Digunakan dengan kata kerja emosional/mental tertentu untuk menunjukkan emosi yang kuat dan tak henti-hentinya: 'tidak bisa berhenti', 'tidak pernah berhenti'.","formation":"Verb-て form + やまない (common with certain verbs)","formationId":"Bentuk kata kerja-て + やまない (umum dengan kata kerja tertentu)","examples":[{"jp":"私は母を思ってやまない。","romaji":"Watashi wa haha o omotte yamanai.","en":"I can't stop thinking of my mother.","id":"Aku tidak bisa berhenti memikirkan ibuku."},{"jp":"彼は彼女を愛してやまない。","romaji":"Kare wa kanojo o aishite yamanai.","en":"He loves her beyond measure.","id":"Dia mencintainya melebihi batas."},{"jp":"彼は日本の文化を尊敬してやまない。","romaji":"Kare wa Nihon no bunka o sonkei shite yamanai.","en":"He has unceasing respect for Japanese culture.","id":"Dia sangat menghormati budaya Jepang."},{"jp":"彼女の成功を願ってやまない。","romaji":"Kanojo no seikō o negatte yamanai.","en":"I can’t stop hoping for her success.","id":"Saya tidak bisa berhenti berharap untuk kesuksesannya."}]},{"pattern":"Verb ないではおかない","meaning":"Means 'cannot help but do', 'will definitely do', or 'is bound to happen'.","meaningId":"Berarti 'tidak bisa tidak melakukan', 'pasti akan melakukan', atau 'pasti terjadi'.","formation":"Verb-ない form + ではおかない","formationId":"Bentuk kata kerja-ない + ではおかない","examples":[{"jp":"彼女は毎回遅刻をしては、先生に怒られないではおかない。","romaji":"Kanojo wa maikai chikoku o shite wa, sensei ni okorarenaide wa okanai.","en":"Every time she's late, she inevitably gets scolded by the teacher.","id":"Setiap kali dia terlambat, dia pasti akan dimarahi oleh gurunya."},{"jp":"美味しいものがあれば、彼は食べないではおかない。","romaji":"Oishii mono ga areba, kare wa tabenai de wa okanai.","en":"If there's delicious food, he can't help but eat it.","id":"Jika ada makanan enak, mau tak mau dia memakannya."},{"jp":"この小説は感動的で、読めば涙を流さないではおかない。","romaji":"Kono shōsetsu wa kandōteki de, yomeba namida o nagasanai de wa okanai.","en":"This novel is so moving that you can't help but shed tears when you read it.","id":"Novel ini begitu mengharukan sehingga Anda tidak bisa menahan tangis saat membacanya."},{"jp":"毎日練習しているから、試合では勝たないではおかないだろう。","romaji":"Mainichi renshū shite iru kara, shiai de wa katanai de wa okanai darō.","en":"He practices every day, so he's bound to win the match.","id":"Dia berlatih setiap hari, jadi dia pasti akan memenangkan pertandingan."}]},{"pattern":"Verb ないではすまない","meaning":"'Cannot end without doing', 'must do'—an unavoidable moral or social necessity.","meaningId":"'Tidak dapat berakhir tanpa melakukan', 'harus melakukan'—suatu keharusan moral atau sosial yang tidak dapat dihindari.","formation":"Verb-ない form + ではすまない","formationId":"Bentuk kata kerja-ない + ではすまない","examples":[{"jp":"失敗をしたら、謝らないではすまない。","romaji":"Shippai o shitara, ayamaranai de wa sumanai.","en":"If you make a mistake, you have to apologize—there’s no way around it.","id":"Jika Anda melakukan kesalahan, Anda harus meminta maaf—tidak ada jalan lain."},{"jp":"この問題は重大なので、報告しないではすまない。","romaji":"Kono mondai wa jūdai na node, hōkoku shinai de wa sumanai.","en":"This issue is so serious that I must report it.","id":"Masalah ini sangat serius sehingga saya harus melaporkannya."},{"jp":"この映画はとても感動的で、泣かないではすまない。","romaji":"Kono eiga wa totemo kandōteki de, nakanai de wa sumanai.","en":"This movie is so moving that you can’t help but cry.","id":"Film ini sangat mengharukan sehingga Anda tidak bisa menahan tangis."},{"jp":"子供が間違えたら、教えないではすまない。","romaji":"Kodomo ga machigaetara, oshienai de wa sumanai.","en":"If a child makes a mistake, you must correct them—there’s no avoiding it.","id":"Jika seorang anak melakukan kesalahan, Anda harus memperbaikinya—tidak ada cara untuk menghindarinya."}]},{"pattern":"Verb ないまでも","meaning":"'Even if not to the extent of...', 'although not completely...'.","meaningId":"'Walaupun tidak sebatas...', 'walaupun tidak sepenuhnya...'.","formation":"Verb-ない form + までも","formationId":"Bentuk kata kerja-ない + までも","examples":[{"jp":"全てを理解しないまでも、基本的なことは分かってほしい。","romaji":"Subete o rikai shinai made mo, kihonteki na koto wa wakatte hoshii.","en":"Even if you don't understand everything, I'd like you at least to grasp the basics.","id":"Meskipun Anda tidak memahami semuanya, saya ingin Anda setidaknya memahami dasar-dasarnya."},{"jp":"会えないまでも、電話で声を聞きたい。","romaji":"Aenai made mo, denwa de koe o kikitai.","en":"Even if we can’t meet, I still want to hear your voice over the phone.","id":"Meski kita tidak bisa bertemu, aku tetap ingin mendengar suaramu melalui telepon."},{"jp":"毎日は無理にしても、週に一度くらいはジョギングを続けたい。","romaji":"Mainichi wa muri ni shite mo, shū ni ichido kurai wa jogingu o tsuzuketai.","en":"Even if I can't do it every day, I want to at least keep jogging once a week.","id":"Meskipun saya tidak bisa melakukannya setiap hari, saya ingin tetap jogging setidaknya seminggu sekali."},{"jp":"全員に気に入られないまでも、誠実に向き合いたい。","romaji":"Zen'in ni ki ni irarenai made mo, seijitsu ni mukiai tai.","en":"Even if not everyone will like me, I still want to face them sincerely.","id":"Meski tidak semua orang menyukaiku, aku tetap ingin menghadapinya dengan tulus."}]},{"pattern":"Verb ないものだろうか","meaning":"Expressing hope or wonder if something can be done: 'Isn't there a way...?', 'Can't we...?'","meaningId":"Mengekspresikan harapan atau keheranan apakah sesuatu dapat dilakukan: 'Apakah tidak ada jalan...?', 'Tidak bisakah kita...?'","formation":"Verb-negative (often negative potential) + ものだろうか","formationId":"Kata kerja-negatif (seringkali potensial negatif) + ものだろうか","examples":[{"jp":"もっと時間があれば、ここに来られないものだろうか。","romaji":"Motto jikan ga areba, koko ni korarenai mono darou ka.","en":"If I had more time, wouldn't it be possible to come here?","id":"Jika saya punya lebih banyak waktu, bukankah mungkin untuk datang ke sini?"},{"jp":"彼女にもっとよく説明すれば、理解できないものだろうか。","romaji":"Kanojo ni motto yoku setsumei sureba, rikai dekinai mono darou ka.","en":"If I explain it better to her, wouldn't she understand?","id":"Jika aku menjelaskannya dengan lebih baik padanya, bukankah dia akan mengerti?"},{"jp":"この問題を解決する方法はないものだろうか。","romaji":"Kono mondai o kaiketsu suru houhou wa nai mono darou ka.","en":"Isn't there a way to solve this problem?","id":"Apakah tidak ada cara untuk mengatasi masalah ini?"},{"jp":"自分の間違いを認められないものだろうか。","romaji":"Jibun no machigai o mitomerarenai mono darou ka.","en":"Can't I admit my own mistakes?","id":"Tidak bisakah aku mengakui kesalahanku sendiri?"}]},{"pattern":"Verb ないものでもない","meaning":"Expresses the idea that it's not entirely impossible or non-existent: 'It's not that I don't...', 'It's not that there aren't...'","meaningId":"Mengekspresikan gagasan bahwa hal tersebut tidak sepenuhnya mustahil atau tidak ada: 'Bukannya saya tidak...', 'Bukan berarti tidak ada...'","formation":"Verb-negative form (ない form) + ものでもない","formationId":"Bentuk kata kerja negatif (bentuk ない) + ものでもない","examples":[{"jp":"旅行に行きたいと思わないものでもない。","romaji":"Ryokou ni ikitai to omowanai mono demo nai.","en":"It's not that I never want to travel.","id":"Bukannya saya tidak pernah ingin bepergian."},{"jp":"彼の言ったこと全部が間違いないものでもない。","romaji":"Kare no itta koto zenbu ga machigai nai mono demo nai.","en":"It's not that everything he said is completely free from mistakes.","id":"Bukan berarti semua yang diucapkannya sepenuhnya bebas dari kesalahan."},{"jp":"その問題が解けないものでもない。","romaji":"Sono mondai ga tokenai mono demo nai.","en":"It's not that the problem can't be solved.","id":"Bukan berarti masalahnya tidak bisa diselesaikan."},{"jp":"彼に会いたくないものでもない。","romaji":"Kare ni aitakunai mono demo nai.","en":"It's not that I don't want to see him.","id":"Bukannya aku tidak ingin bertemu dengannya."}]},{"pattern":"Verb の ない Noun","meaning":"Used to modify a noun with a negative verb form; 'a Noun without (Verb)'.","meaningId":"Digunakan untuk memodifikasi kata benda dengan bentuk kata kerja negatif; 'kata benda tanpa (kata kerja)'.","formation":"Verb in negative form + の + Noun","formationId":"Kata kerja dalam bentuk negatif + の + Kata Benda","examples":[{"jp":"笑いのない人生は、つまらない。","romaji":"Warai no nai jinsei wa, tsumaranai.","en":"A life without laughter is boring.","id":"Hidup tanpa tawa itu membosankan."},{"jp":"水のない場所には、人は住めない。","romaji":"Mizu no nai basho ni wa, hito wa sumenai.","en":"People cannot live in a place without water.","id":"Manusia tidak bisa hidup di suatu tempat tanpa air."},{"jp":"言葉のない世界は、想像するのが難しい。","romaji":"Kotoba no nai sekai wa, souzou suru no ga muzukashii.","en":"It's hard to imagine a world without words.","id":"Sulit membayangkan dunia tanpa kata-kata."},{"jp":"愛のない結婚は、長続きしない。","romaji":"Ai no nai kekkon wa, nagatsudzuki shinai.","en":"A marriage without love will not last.","id":"Pernikahan tanpa cinta tidak akan bertahan lama."}]},{"pattern":"Verb ば きりがない (〜ba kiri ga nai)","meaning":"Indicates there's no end once you start listing, doing, or saying something: 'If one starts to..., there will be no end.'","meaningId":"Menunjukkan tidak adanya akhir setelah Anda mulai membuat daftar, melakukan, atau mengatakan sesuatu: 'Jika seseorang mulai..., tidak akan ada akhir.'","formation":"Verb-conditional form (ば) + きりがない","formationId":"Bentuk kata kerja kondisional (ば) + きりがない","examples":[{"jp":"悪口を言い始めればきりがない。","romaji":"Waruguchi o iihajimereba kiri ga nai.","en":"Once I start speaking ill of someone, there's no end.","id":"Begitu saya mulai menjelek-jelekkan seseorang, tidak ada habisnya."},{"jp":"彼の欠点を数えればきりがない。","romaji":"Kare no ketten o kazoereba kiri ga nai.","en":"If I start counting his flaws, there will be no end.","id":"Jika saya mulai menghitung kekurangannya, tidak akan ada habisnya."},{"jp":"この国の美しい場所は、挙げればきりがない。","romaji":"Kono kuni no utsukushii basho wa, agereba kiri ga nai.","en":"If I start listing this country's beautiful places, there's no end.","id":"Jika saya mulai membuat daftar tempat-tempat indah di negara ini, tidak ada habisnya."},{"jp":"ほかにも例を挙げればきりがない。","romaji":"Hoka ni mo rei o agereba kiri ga nai.","en":"If I start giving more examples, there will be no end.","id":"Jika saya mulai memberi lebih banyak contoh, tidak akan ada habisnya."}]},{"pattern":"Verb もしないで","meaning":"Means 'without even doing'.","meaningId":"Berarti 'bahkan tanpa melakukan'.","formation":"Verb (masu stem) + もしないで","formationId":"Kata Kerja (batang masu) + もしないで","examples":[{"jp":"調べもしないで、答えを書きました。","romaji":"Shirabe mo shinai de, kotae o kakimashita.","en":"I wrote the answer without even investigating.","id":"Saya menulis jawabannya tanpa menyelidiki."},{"jp":"彼は試験を勉強もしないで、テストに合格した。","romaji":"Kare wa shiken o benkyou mo shinai de, tesuto ni goukaku shita.","en":"He passed the test without even studying.","id":"Dia lulus ujian bahkan tanpa belajar."},{"jp":"彼女はその本を読みもしないで、レポートを書いた。","romaji":"Kanojo wa sono hon o yomi mo shinai de, repooto o kaita.","en":"She wrote her report without even reading the book.","id":"Dia menulis laporannya bahkan tanpa membaca bukunya."},{"jp":"準備もしないで、プレゼンテーションを始めました。","romaji":"Junbi mo shinai de, purezenteeshon o hajimemashita.","en":"He started the presentation without even preparing.","id":"Dia memulai presentasi bahkan tanpa persiapan."}]},{"pattern":"Verb やしない","meaning":"Expresses a strong denial or refusal: 'I would never...', 'No way I would...'.","meaningId":"Mengekspresikan penyangkalan atau penolakan yang kuat: 'Saya tidak akan pernah...', 'Tidak mungkin saya akan...'.","formation":"Verb (masu stem) + やしない","formationId":"Kata kerja (batang masu) + やしない","examples":[{"jp":"こんな時に泣きやしない。","romaji":"Konna toki ni naki-yashinai.","en":"I would never cry at a time like this.","id":"Aku tidak akan pernah menangis di saat seperti ini."},{"jp":"私が彼を助けやしない。","romaji":"Watashi ga kare o tasuke-yashinai.","en":"There's no way I'd help him.","id":"Tidak mungkin aku membantunya."},{"jp":"彼がそんなことを言いやしない。","romaji":"Kare ga sonna koto o ii-yashinai.","en":"He would never say such a thing.","id":"Dia tidak akan pernah mengatakan hal seperti itu."},{"jp":"私がそんな高価なものを買いやしない。","romaji":"Watashi ga sonna kouka na mono o kai-yashinai.","en":"There's no way I'd buy something so expensive.","id":"Tidak mungkin aku membeli sesuatu yang semahal itu."}]},{"pattern":"Verb よう","meaning":"Expresses 'the way/manner of doing something' or 'in order to / so that / try to'.","meaningId":"Menyatakan 'cara/cara melakukan sesuatu' atau 'untuk / agar / mencoba'.","formation":"Verb (dictionary or negative form) + ように (する / etc.)","formationId":"Kata kerja (kamus atau bentuk negatif) + ように (する / dll.)","examples":[{"jp":"この問題を解くように努力します。","romaji":"Kono mondai o toku you ni doryoku shimasu.","en":"I will try to solve this problem.","id":"Saya akan mencoba menyelesaikan masalah ini."},{"jp":"彼が言ったようにやりましょう。","romaji":"Kare ga itta you ni yarimashou.","en":"Let's do it the way he said.","id":"Mari kita lakukan seperti yang dia katakan."},{"jp":"毎日走るようにしています。","romaji":"Mainichi hashiru you ni shiteimasu.","en":"I make it a point to run every day.","id":"Saya bertekad untuk berlari setiap hari."},{"jp":"自分の心を大切にするように。","romaji":"Jibun no kokoro o taisetsu ni suru you ni.","en":"Try to take care of your own heart.","id":"Cobalah untuk menjaga hatimu sendiri."}]},{"pattern":"Verb ようか Verbるまいか","meaning":"Expresses indecision: 'Should I do it or not?'.","meaningId":"Mengekspresikan keragu-raguan: 'Haruskah saya melakukannya atau tidak?'.","formation":"Verb-volitional form + か + Verb-volitional negative form (まい) + か","formationId":"Bentuk verba-kehendak + か + Bentuk verba-kehendak negatif (まい) + か","examples":[{"jp":"彼に話そうか話すまいか、本当に迷っている。","romaji":"Kare ni hanasou ka hanasu mai ka, hontou ni mayotte iru.","en":"I'm really unsure whether to talk to him or not.","id":"Aku benar-benar bingung apakah harus berbicara dengannya atau tidak."},{"jp":"試験を受けようか受けまいか迷っています。","romaji":"Shiken o ukeyou ka ukemai ka mayotte imasu.","en":"I'm wondering whether to take the exam or not.","id":"Saya bertanya-tanya apakah akan mengikuti ujian atau tidak."},{"jp":"あの人に謝ろうか謝るまいか考えています。","romaji":"Ano hito ni ayamarou ka ayamaru mai ka kangaete imasu.","en":"I'm considering whether to apologize to that person or not.","id":"Saya sedang mempertimbangkan apakah akan meminta maaf kepada orang itu atau tidak."},{"jp":"進学しようかしまいか悩んでいる。","romaji":"Shingaku shiyou ka shimai ka nayande iru.","en":"I'm worried about whether to continue my studies or not.","id":"Saya khawatir apakah saya akan melanjutkan studi saya atau tidak."}]},{"pattern":"Verb ようが Verb るまいが","meaning":"Expresses 'whether or not', 'no matter if something happens or not'.","meaningId":"Mengekspresikan 'apakah atau tidak', 'tidak peduli apakah sesuatu terjadi atau tidak'.","formation":"Verb-volitional form + が + Verb-negative volitional form + が","formationId":"Bentuk kehendak verba + が + Bentuk kehendak verba-negatif + が","examples":[{"jp":"彼が来ようが来るまいが、パーティーは始まります。","romaji":"Kare ga koyou ga kurumai ga, paatii wa hajimarimasu.","en":"Whether he comes or not, the party will start.","id":"Apakah dia datang atau tidak, pesta akan dimulai."},{"jp":"勉強しようがしまいが、テストの結果は変わらない。","romaji":"Benkyou shiyou ga shimai ga, tesuto no kekka wa kawaranai.","en":"Whether you study or not, the test results won't change.","id":"Apakah Anda belajar atau tidak, hasil tes tidak akan berubah."},{"jp":"雨が降ろうが降るまいが、ピクニックに行きます。","romaji":"Ame ga furou ga furumai ga, pikunikku ni ikimasu.","en":"Whether it rains or not, we're going on a picnic.","id":"Entah hujan atau tidak, kami akan piknik."},{"jp":"暑かろうが寒かろうが、毎日ジョギングします。","romaji":"Atsukarou ga samukarou ga, mainichi jogingu shimasu.","en":"Whether it's hot or cold, I jog every day.","id":"Entah panas atau dingin, saya jogging setiap hari."}]},{"pattern":"Verb ようがない (〜you ga nai)","meaning":"Expresses 'no way to do something,' 'impossible to do'.","meaningId":"Menyatakan 'tidak mungkin melakukan sesuatu', 'tidak mungkin melakukan'.","formation":"Verb (masu stem) + ようがない","formationId":"Kata Kerja (batang masu) + ようがない","examples":[{"jp":"電車が混んでいて、動きようがない。","romaji":"Densha ga konde ite, ugoki you ga nai.","en":"The train is so crowded that I can't move.","id":"Keretanya sangat penuh sehingga saya tidak bisa bergerak."},{"jp":"彼はとても早く走るので、追いつきようがない。","romaji":"Kare wa totemo hayaku hashiru no de, oitsuki you ga nai.","en":"He runs so fast, there's no way I can catch up.","id":"Dia berlari sangat cepat, tidak mungkin aku bisa mengejarnya."},{"jp":"私には理解しようがない。","romaji":"Watashi ni wa rikai shiyou ga nai.","en":"There's no way for me to understand it.","id":"Tidak ada cara bagiku untuk memahaminya."},{"jp":"どうやっても、これを直しようがない。","romaji":"Dou yatte mo, kore o naoshi you ga nai.","en":"No matter what I try, there's no way to fix this.","id":"Apa pun yang saya coba, tidak ada cara untuk memperbaikinya."}]},{"pattern":"Verb ようと Verbる まいと","meaning":"This structure indicates that regardless of whether one does (verb) or not, the outcome/attitude remains unchanged.","meaningId":"Struktur ini menunjukkan bahwa terlepas dari apakah seseorang melakukan (kata kerja) atau tidak, hasil/sikapnya tetap tidak berubah.","formation":"Verb-volitional + と + Verb-negative volitional (～まい) + と","formationId":"Verba-volitional + と + Verba-negatif volitional (～まい) + と","examples":[{"jp":"あなたが来ようと来るまいと、パーティーは予定通りに始まります。","romaji":"Anata ga koyou to kuru mai to, paatii wa yotei doori ni hajimarimasu.","en":"Whether you come or not, the party will start as scheduled.","id":"Apakah Anda datang atau tidak, pesta akan dimulai sesuai jadwal."},{"jp":"彼があそこに行こうと行くまいと、私たちは止めることができません。","romaji":"Kare ga asoko ni ikou to iku mai to, watashitachi wa tomeru koto ga dekimasen.","en":"Whether he tries to go there or not, we can't stop him.","id":"Apakah dia mencoba pergi ke sana atau tidak, kita tidak bisa menghentikannya."},{"jp":"彼女が謝ろうと謝るまいと、事実は変わらない。","romaji":"Kanojo ga ayamarou to ayamaru mai to, jijitsu wa kawaranai.","en":"Whether she apologizes or not, the fact won't change.","id":"Apakah dia meminta maaf atau tidak, faktanya tidak akan berubah."},{"jp":"試験を受けようと受けるまいと、親として私はあなたを支えます。","romaji":"Shiken o ukeyou to ukeru mai to, oya to shite watashi wa anata o sasaemasu.","en":"Whether you take the exam or not, I will support you as your parent.","id":"Apakah kamu mengikuti ujian atau tidak, aku akan mendukungmu sebagai orang tuamu."}]},{"pattern":"Verb ようにも (〜you ni mo)","meaning":"Used to express 'even though one wants to do something, one can't for some reason'.","meaningId":"Digunakan untuk mengungkapkan 'walaupun seseorang ingin melakukan sesuatu, namun karena alasan tertentu ia tidak dapat melakukannya'.","formation":"Verb-volitional form + にも + (reason/potential negative, etc.)","formationId":"Bentuk kata kerja-kehendak + にも + (alasan/potensi negatif, dll.)","examples":[{"jp":"もう少し速く走ろうにも、足が痛くて無理だ。","romaji":"Mou sukoshi hayaku hashirou ni mo, ashi ga itakute muri da.","en":"I'd like to run a bit faster, but I can’t because my leg hurts.","id":"Aku ingin berlari sedikit lebih cepat, tapi aku tidak bisa karena kakiku sakit."},{"jp":"彼に話そうにも、彼は私を無視している。","romaji":"Kare ni hanasou ni mo, kare wa watashi o mushi shite iru.","en":"I want to talk to him, but he's ignoring me.","id":"Aku ingin berbicara dengannya, tapi dia mengabaikanku."},{"jp":"もっと勉強しようにも、時間がない。","romaji":"Motto benkyou shiyou ni mo, jikan ga nai.","en":"I want to study more, but I have no time.","id":"Saya ingin belajar lebih banyak, tetapi saya tidak punya waktu."},{"jp":"彼女に謝ろうにも、彼女はもう怒っている。","romaji":"Kanojo ni ayamarou ni mo, kanojo wa mou okotte iru.","en":"I would like to apologize to her, but she's already angry.","id":"Saya ingin meminta maaf padanya, tapi dia sudah marah."}]},{"pattern":"Verb ようにも Verb れない (〜you ni mo 〜renai)","meaning":"Expresses the inability to do something even if one wants/tries.","meaningId":"Mengekspresikan ketidakmampuan untuk melakukan sesuatu meskipun seseorang ingin/mencoba.","formation":"Verb-volitional form + にも + (potential negative form / reason)","formationId":"Bentuk kata kerja-kehendak + にも + (potensi bentuk/alasan negatif)","examples":[{"jp":"彼を信じようにも信じられない証拠がある。","romaji":"Kare o shinjiyou ni mo shinjirarenai shouko ga aru.","en":"Even if I want to believe him, there's evidence that prevents me from doing so.","id":"Sekalipun saya ingin memercayainya, ada bukti yang menghalangi saya untuk mempercayainya."},{"jp":"早く出発しようにも車が故障してしまった。","romaji":"Hayaku shuppatsu shiyou ni mo kuruma ga koshou shite shimatta.","en":"Even if I want to leave early, my car has broken down.","id":"Bahkan jika saya ingin berangkat lebih awal, mobil saya mogok."},{"jp":"彼に電話しようにも電話番号を知らない。","romaji":"Kare ni denwa shiyou ni mo denwa bangou o shiranai.","en":"I want to call him, but I don’t know his phone number.","id":"Aku ingin menelponnya, tapi aku tidak tahu nomor teleponnya."},{"jp":"もっと勉強しようにも時間がない。","romaji":"Motto benkyou shiyou ni mo jikan ga nai.","en":"I want to study more, but there is no time.","id":"Saya ingin belajar lebih banyak, tetapi tidak ada waktu."}]},{"pattern":"Verb ようもない","meaning":"Expresses 'it's impossible to do something'.","meaningId":"Mengekspresikan 'tidak mungkin melakukan sesuatu'.","formation":"Verb-ます stem + ようもない","formationId":"Kata kerja-ます batang + ようもない","examples":[{"jp":"この問題は解きようもない。","romaji":"Kono mondai wa toki you mo nai.","en":"It's impossible to solve this problem.","id":"Tidak mungkin menyelesaikan masalah ini."},{"jp":"これ以上我慢しようもない。","romaji":"Kore ijou gaman shiyou mo nai.","en":"It's impossible to endure any further.","id":"Tidak mungkin untuk bertahan lebih jauh lagi."},{"jp":"彼には通じようもない。","romaji":"Kare ni wa tsuujiyou mo nai.","en":"There's no way to get through to him.","id":"Tidak ada cara untuk menghubunginya."},{"jp":"その薬は飲みようもない。","romaji":"Sono kusuri wa nomiyou mo nai.","en":"It's impossible to take (swallow) that medicine.","id":"Tidak mungkin meminum (menelan) obat itu."}]},{"pattern":"Verbる がままに (〜ga mama ni)","meaning":"Expresses 'letting something happen as it is'; 'just as something does'.","meaningId":"Menyatakan 'membiarkan sesuatu terjadi apa adanya'; 'seperti yang terjadi pada sesuatu'.","formation":"Verb-dictionary form + がままに","formationId":"Bentuk kamus kata kerja + がままに","examples":[{"jp":"窓を開けるがままにしておいたら、風が部屋に入ってきました。","romaji":"Mado o akeru ga mama ni shite oitara, kaze ga heya ni haitte kimashita.","en":"I left the window open as it was, and the wind came into the room.","id":"Saya membiarkan jendela terbuka apa adanya, dan angin masuk ke dalam ruangan."},{"jp":"彼女は涙を流すがままに、ただ黙って座っていた。","romaji":"Kanojo wa namida o nagasu ga mama ni, tada damatte suwatte ita.","en":"She just sat quietly, letting her tears flow.","id":"Dia hanya duduk diam, membiarkan air matanya mengalir."},{"jp":"子供たちは笑うがままに、公園で走り回っていた。","romaji":"Kodomo-tachi wa warau ga mama ni, kouen de hashirimawatte ita.","en":"The children ran around the park, laughing freely as they pleased.","id":"Anak-anak berlarian mengelilingi taman sambil tertawa lepas sesuka hati."},{"jp":"日が沈むがままに、私たちは海辺で話し続けました。","romaji":"Hi ga shizumu ga mama ni, watashitachi wa umibe de hanashi tsudzukemashita.","en":"We kept talking by the sea, letting the sun set as it would.","id":"Kami terus berbincang di tepi laut, membiarkan matahari terbenam sebagaimana mestinya."}]},{"pattern":"Verbる が早いか (verb-ru ga hayai ka)","meaning":"Expresses 'as soon as...' or 'the moment when...'.","meaningId":"Menyatakan 'segera setelah...' atau 'saat ketika...'.","formation":"Verb-dictionary form + が早いか","formationId":"Bentuk kamus kata kerja + が早いか","examples":[{"jp":"部屋に入るが早いか、彼はテレビをつけた。","romaji":"Heya ni hairu ga hayai ka, kare wa terebi o tsuketa.","en":"No sooner had he entered the room than he turned on the TV.","id":"Begitu dia memasuki ruangan, dia menyalakan TV."},{"jp":"電車に乗るが早いか、私はすぐに眠ってしまった。","romaji":"Densha ni noru ga hayai ka, watashi wa sugu ni nemutte shimatta.","en":"As soon as I got on the train, I immediately fell asleep.","id":"Begitu saya naik kereta, saya langsung tertidur."},{"jp":"彼女が見るが早いか、すぐに泣き始めた。","romaji":"Kanojo ga miru ga hayai ka, sugu ni naki hajimeta.","en":"The moment she looked, she began to cry.","id":"Saat dia melihat, dia mulai menangis."},{"jp":"給料をもらうが早いか、全て使い果たしてしまった。","romaji":"Kyuuryou o morau ga hayai ka, subete tsukaihatashite shimatta.","en":"No sooner had I received my salary than I spent it all.","id":"Tidak lama setelah saya menerima gaji saya, saya menghabiskan semuanya."}]},{"pattern":"Verbる くらいなら (〜ru kurai nara)","meaning":"Expresses preference to avoid something: 'rather than...', 'if it comes to doing X, I'd rather...'.","meaningId":"Mengekspresikan preferensi untuk menghindari sesuatu: 'daripada...', 'jika harus melakukan X, saya lebih suka...'.","formation":"Verb-dictionary form + くらいなら","formationId":"Bentuk kamus kata kerja + くらいなら","examples":[{"jp":"一人で行くくらいなら、家にいるほうがましです。","romaji":"Hitori de iku kurai nara, ie ni iru hou ga mashi desu.","en":"I'd rather stay at home than go alone.","id":"Aku lebih memilih diam di rumah daripada pergi sendiri."},{"jp":"負けるくらいなら、試合をしないほうがいい。","romaji":"Makeru kurai nara, shiai o shinai hou ga ii.","en":"Rather than lose, it's better not to compete.","id":"Daripada kalah, lebih baik tidak berkompetisi."},{"jp":"遅刻するくらいなら、一日休んだほうがいい。","romaji":"Chikoku suru kurai nara, ichinichi yasunda hou ga ii.","en":"It's better to take a day off than to be late.","id":"Lebih baik mengambil cuti daripada terlambat."},{"jp":"痛い目に遭うくらいなら、そのリスクは避けます。","romaji":"Itai me ni au kurai nara, sono risuku wa sakemasu.","en":"I'd rather avoid that risk than suffer the consequences.","id":"Saya lebih baik menghindari risiko itu daripada menanggung akibatnya."}]},{"pattern":"Verbる こと なし に (Verb-ru koto nashi ni)","meaning":"Used to express 'without doing something'.","meaningId":"Digunakan untuk menyatakan 'tanpa melakukan sesuatu'.","formation":"Verb-dictionary form + ことなしに","formationId":"Bentuk kamus kata kerja + ことなしに","examples":[{"jp":"試験を勉強することなしに、合格しました。","romaji":"Shiken o benkyou suru koto nashi ni, goukaku shimashita.","en":"I passed the exam without studying.","id":"Saya lulus ujian tanpa belajar."},{"jp":"試着することなしに、服を買いました。","romaji":"Shichaku suru koto nashi ni, fuku o kaimashita.","en":"I bought the clothes without trying them on.","id":"Saya membeli pakaian itu tanpa mencobanya."},{"jp":"彼は働くことなしに生活しています。","romaji":"Kare wa hataraku koto nashi ni seikatsu shite imasu.","en":"He is living without working.","id":"Dia hidup tanpa bekerja."},{"jp":"手続きをすることなしに、退職しました。","romaji":"Tetsuzuki o suru koto nashi ni, taishoku shimashita.","en":"I retired without going through any procedures.","id":"Saya pensiun tanpa melalui prosedur apa pun."}]},{"pattern":"Verbる ことのないように (Verb-ru koto no nai you ni)","meaning":"Expresses the desire or effort to prevent something: 'so as not to...', 'to avoid...'.","meaningId":"Menyatakan keinginan atau usaha untuk mencegah sesuatu: 'agar tidak...', 'menghindari...'.","formation":"Verb-dictionary form + ことのないように","formationId":"Bentuk kamus kata kerja + ことのないように","examples":[{"jp":"車をなくすことのないように、駐車場で必ずロックしましょう。","romaji":"Kuruma o nakusu koto no nai you ni, chuushajou de kanarazu rokku shimashou.","en":"Lock your car in the parking lot so you don't lose it.","id":"Kunci mobil Anda di tempat parkir agar tidak hilang."},{"jp":"風邪を引くことのないように、手をよく洗いましょう。","romaji":"Kaze o hiku koto no nai you ni, te o yoku araimashou.","en":"Wash your hands well so you don't catch a cold.","id":"Cuci tangan Anda dengan baik agar Anda tidak masuk angin."},{"jp":"試験に落ちることのないように、毎日勉強しましょう。","romaji":"Shiken ni ochiru koto no nai you ni, mainichi benkyou shimashou.","en":"Study every day so you don't fail the exam.","id":"Belajarlah setiap hari agar tidak gagal dalam ujian."},{"jp":"間違いをすることのないように、仕事を慎重に行いましょう。","romaji":"Machigai o suru koto no nai you ni, shigoto o shinchou ni okonaimashou.","en":"Let's work carefully to avoid making mistakes.","id":"Mari bekerja dengan hati-hati agar tidak terjadi kesalahan."}]},{"pattern":"Verbる ときりがない (verb-ru to kiri ga nai)","meaning":"Used to indicate that something can go on endlessly or without limits.","meaningId":"Digunakan untuk menunjukkan bahwa sesuatu dapat berlangsung tanpa henti atau tanpa batas.","formation":"Verb-casual + と + きりがない","formationId":"Kata kerja kasual + と + きりがない","examples":[{"jp":"彼の悪口を言うときりがない。","romaji":"Kare no waruguchi o iu to kiri ga nai.","en":"If we start talking about his faults, there's no end.","id":"Jika kita mulai membicarakan kesalahannya, tidak ada habisnya."},{"jp":"その問題を考えるときりがない。","romaji":"Sono mondai o kangaeru to kiri ga nai.","en":"If you start thinking about that problem, there's no end.","id":"Jika Anda mulai memikirkan masalah itu, tidak ada habisnya."},{"jp":"彼女の美点を挙げるときりがない。","romaji":"Kanojo no biten o ageru to kiri ga nai.","en":"If you start listing her virtues, there would be no end.","id":"Jika Anda mulai membuat daftar kelebihannya, tidak akan ada habisnya."},{"jp":"この世でおいしいものを食べるときりがない。","romaji":"Kono yo de oishii mono o taberu to kiri ga nai.","en":"If you start eating all the delicious things in this world, there's no end.","id":"Jika Anda mulai memakan semua hal lezat di dunia ini, tidak akan ada habisnya."}]},{"pattern":"Verbる ともなく Verb (Verb-ru tomonaku Verb)","meaning":"Used to express 'without a particular intention', 'unconsciously', or 'before one knows it'.","meaningId":"Digunakan untuk menyatakan 'tanpa maksud tertentu', 'tanpa sadar', atau 'sebelum ada yang menyadarinya'.","formation":"Verb-dictionary form + ともなく + Verb","formationId":"Bentuk kamus kata kerja + ともなく + Kata Kerja","examples":[{"jp":"遠くを見るともなく窓の外を眺めた。","romaji":"Tooku o miru tomonaku mado no soto o nagameta.","en":"I found myself gazing out the window, not really looking at anything in particular.","id":"Aku mendapati diriku memandang ke luar jendela, tidak benar-benar melihat apa pun secara khusus."},{"jp":"知るともなく、彼が去ったことを感じた。","romaji":"Shiru tomonaku, kare ga satta koto o kanjita.","en":"Without really knowing, I felt that he had left.","id":"Tanpa kusadari, aku merasa dia telah pergi."},{"jp":"本を読むともなく、ページをめくっていた。","romaji":"Hon o yomu tomonaku, peiji o mekutte ita.","en":"Without intending to read, I was just flipping through the pages of the book.","id":"Tanpa niat membaca, saya hanya membolak-balik halaman buku tersebut."},{"jp":"寝るともなく、ベッドに横になっていた。","romaji":"Neru tomonaku, beddo ni yoko ni natte ita.","en":"I was lying in bed without really intending to sleep.","id":"Aku sedang berbaring di tempat tidur tanpa benar-benar berniat untuk tidur."}]},{"pattern":"Verbる ともなしに Verb (Verb-ru tomonashi ni Verb)","meaning":"Expresses doing something unintentionally or without conscious thought.","meaningId":"Mengekspresikan melakukan sesuatu secara tidak sengaja atau tanpa pikiran sadar.","formation":"Verb-dictionary form + ともなしに + Verb","formationId":"Bentuk kamus kata kerja + ともなしに + Kata Kerja","examples":[{"jp":"本を読むともなしに眠ってしまった。","romaji":"Hon o yomu tomonashi ni nemutte shimatta.","en":"I ended up falling asleep while reading the book without really meaning to.","id":"Saya akhirnya tertidur saat membaca buku tanpa sengaja."},{"jp":"軽い気持ちで手紙を書くともなしに、彼に本心を告白した。","romaji":"Karui kimochi de tegami o kaku tomonashi ni, kare ni honshin o kokuhaku shita.","en":"While writing a letter casually, I ended up confessing my true feelings to him.","id":"Sambil menulis surat dengan santai, aku akhirnya mengakui perasaanku yang sebenarnya kepadanya."},{"jp":"散歩をするともなしに、新しいカフェを見つけた。","romaji":"Sanpo o suru tomonashi ni, atarashii kafe o mitsuketa.","en":"While I was walking with no particular destination, I found a new cafe.","id":"Saat saya berjalan tanpa tujuan tertentu, saya menemukan sebuah kafe baru."},{"jp":"洋服を整理するともなしに、昔の写真を見つけた。","romaji":"Youfuku o seiri suru tomonashi ni, mukashi no shashin o mitsuketa.","en":"As I was absentmindedly organizing clothes, I came across some old photos.","id":"Saat saya tanpa sadar mengatur pakaian, saya menemukan beberapa foto lama."}]},{"pattern":"Verbる なり (Verb-ru nari)","meaning":"Expresses 'as soon as' or 'the moment'.","meaningId":"Menyatakan 'segera' atau 'saat itu'.","formation":"Verb-dictionary form + なり","formationId":"Bentuk kamus kata kerja + なり","examples":[{"jp":"家に帰るなり、すぐに寝た。","romaji":"Ie ni kaeru nari, sugu ni neta.","en":"As soon as I got home, I went to sleep.","id":"Begitu sampai di rumah, saya langsung tidur."},{"jp":"彼が駅に着くなり、電話をかけてきた。","romaji":"Kare ga eki ni tsuku nari, denwa o kakete kita.","en":"He called me the moment he arrived at the station.","id":"Dia menelepon saya begitu dia tiba di stasiun."},{"jp":"ドアを開けるなり、犬が吠え始めた。","romaji":"Doa o akeru nari, inu ga hoe hajimeta.","en":"As soon as I opened the door, the dog started barking.","id":"Begitu saya membuka pintu, anjing itu mulai menggonggong."},{"jp":"テストが終わるなり、彼は教室を出て行った。","romaji":"Tesuto ga owaru nari, kare wa kyoushitsu o dete itta.","en":"He left the classroom the moment the test ended.","id":"Dia meninggalkan kelas saat ujian berakhir."}]},{"pattern":"Verbる にとどまらず～も (Verb-ru ni todomarazu ~ mo)","meaning":"Expresses 'not only… but also', 'not limited to…'.","meaningId":"Menyatakan 'tidak hanya… tetapi juga', 'tidak terbatas pada…'.","formation":"Noun / Verb-dictionary form + にとどまらず + も/ほかのこと","formationId":"Bentuk kamus Kata Benda / Kata Kerja + にとどまらず + も/ほかのこと","examples":[{"jp":"彼は仕事にとどまらず、ボランティア活動もしている。","romaji":"Kare wa shigoto ni todomarazu, borantia katsudou mo shite iru.","en":"He does not just work; he also does volunteer activities.","id":"Dia tidak hanya bekerja; dia juga melakukan kegiatan sukarela."},{"jp":"この機能は写真撮影にとどまらず、動画撮影も可能です。","romaji":"Kono kinou wa shashin satsuei ni todomarazu, douga satsuei mo kanou desu.","en":"This function is not limited to taking photos; it can also record videos.","id":"Fungsi ini tidak terbatas pada mengambil foto; itu juga dapat merekam video."},{"jp":"このレストランは日本料理にとどまらず、中華料理も提供しています。","romaji":"Kono resutoran wa Nihon ryouri ni todomarazu, Chuuka ryouri mo teikyou shiteimasu.","en":"This restaurant not only serves Japanese food, but also Chinese cuisine.","id":"Restoran ini tidak hanya menyajikan masakan Jepang, tetapi juga masakan Cina."},{"jp":"その企業は製造業にとどまらず、流通業務も手がけている。","romaji":"Sono kigyou wa seizougyou ni todomarazu, ryuutsuugyou mo tegakete iru.","en":"That company’s operations go beyond manufacturing; they also handle distribution.","id":"Operasi perusahaan tersebut lebih dari sekadar manufaktur; mereka juga menangani distribusi."}]},{"pattern":"Verbる にはあたらない (Verb-ru ni wa ataranai)","meaning":"Used to say 'there is no need to...', 'it’s not necessary to...'.","meaningId":"Biasa mengatakan 'tidak perlu...', 'tidak perlu...'.","formation":"Verb-dictionary form + にはあたらない","formationId":"Bentuk kamus kata kerja + にはあたらない","examples":[{"jp":"パニックに陥るにはあたらない。","romaji":"Panikku ni ochiiru ni wa ataranai.","en":"There’s no need to panic.","id":"Tidak perlu panik."},{"jp":"彼に謝るにはあたらない。","romaji":"Kare ni ayamaru ni wa ataranai.","en":"There’s no need to apologize to him.","id":"Tidak perlu meminta maaf padanya."},{"jp":"そのようなことを心配するにはあたらない。","romaji":"Sono you na koto o shinpai suru ni wa ataranai.","en":"It’s not worth worrying about such things.","id":"Tidak ada gunanya mengkhawatirkan hal-hal seperti itu."},{"jp":"それについて深く考えるにはあたらない。","romaji":"Sore ni tsuite fukaku kangaeru ni wa ataranai.","en":"There’s no need to think too deeply about it.","id":"Tidak perlu memikirkannya terlalu dalam."}]},{"pattern":"Verbる にも (Verb-ru ni mo)","meaning":"Indicates that doing the verb is impossible or difficult, even if one wants to.","meaningId":"Menunjukkan bahwa melakukan kata kerja itu mustahil atau sulit, meskipun seseorang menginginkannya.","formation":"Verb-dictionary form + にも + (reason it can't be done)","formationId":"Bentuk kamus kata kerja + にも + (alasan tidak bisa dilakukan)","examples":[{"jp":"明日雨が降ったとしても、傘を持つにも荷物が多すぎる。","romaji":"Ashita ame ga futta to shite mo, kasa o motsu ni mo nimotsu ga oosugiru.","en":"Even if it rains tomorrow, I have too much luggage to bring an umbrella.","id":"Kalaupun besok hujan, barang bawaan saya terlalu banyak untuk membawa payung."},{"jp":"試験に落ちたが、もう一度受けるにもお金が足りない。","romaji":"Shiken ni ochita ga, mou ichido ukeru ni mo okane ga tarinai.","en":"I failed the exam, but I don’t have the money to take it again even if I wanted to.","id":"Saya gagal dalam ujian, tetapi saya tidak mempunyai uang untuk mengikuti ujian lagi meskipun saya menginginkannya."},{"jp":"彼に会いたいと思っても、彼に会うにも難しい状況だ。","romaji":"Kare ni aitai to omotte mo, kare ni au ni mo muzukashii joukyou da.","en":"Even if I want to see him, it's a difficult situation to meet him.","id":"Bahkan jika aku ingin bertemu dengannya, sulit untuk bertemu dengannya."},{"jp":"この空港から彼女の家に行くにもタクシーが必要だ。","romaji":"Kono kuukou kara kanojo no ie ni iku ni mo takushii ga hitsuyou da.","en":"I'd need a taxi to get from this airport to her house, even if I wanted to go.","id":"Saya memerlukan taksi untuk pergi dari bandara ini ke rumahnya, meskipun saya ingin pergi."}]},{"pattern":"Verbる にも Verb れない (Verb-ru ni mo Verb-re nai)","meaning":"Expresses: 'Even if I try/want to do something, I cannot.'","meaningId":"Mengekspresikan: 'Bahkan jika saya mencoba/ingin melakukan sesuatu, saya tidak bisa.'","formation":"Verb-volitional + にも + Verb-potential negative","formationId":"Kata kerja-kehendak + にも + Kata kerja-potensial negatif","examples":[{"jp":"彼を理解しようにも理解できない。","romaji":"Kare o rikai shiyou ni mo rikai dekinai.","en":"Even if I try to understand him, I can't.","id":"Sekalipun aku mencoba memahaminya, aku tidak bisa."},{"jp":"走ろうにも走れない。","romaji":"Hashirou ni mo hashirenai.","en":"Even if I want to run, I can't.","id":"Walaupun aku ingin lari, aku tidak bisa."},{"jp":"泣こうにも泣けない。","romaji":"Nakou ni mo nakenai.","en":"Even if I want to cry, I can't.","id":"Walaupun aku ingin menangis, aku tidak bisa."},{"jp":"忘れようにも忘れられない。","romaji":"Wasureyou ni mo wasurerarenai.","en":"Even if I try to forget, I just can’t.","id":"Walaupun aku mencoba melupakannya, aku tidak bisa."}]},{"pattern":"Verbる べからざる Noun (Verb-ru bekara zaru Noun)","meaning":"Used to express what should not be done; 'must not', 'should not'.","meaningId":"Digunakan untuk menyatakan apa yang tidak boleh dilakukan; 'tidak boleh', 'tidak boleh'.","formation":"Verb-dictionary form + べからざる + Noun","formationId":"Bentuk kamus kata kerja + べからざる + Kata Benda","examples":[{"jp":"人を裏切るべからざる行為だ。","romaji":"Hito o uragiru bekara zaru koui da.","en":"Betraying others is an act that must not be done.","id":"Mengkhianati orang lain adalah tindakan yang tidak boleh dilakukan."},{"jp":"子供を傷つけるべからざる行動だ。","romaji":"Kodomo o kizutsukeru bekara zaru koudou da.","en":"Hurting a child is a behavior that must not happen.","id":"Menyakiti anak merupakan perilaku yang tidak boleh terjadi."},{"jp":"公に嘘をつくべからざる行動だ。","romaji":"Ooyake ni uso o tsuku bekara zaru koudou da.","en":"Lying publicly is an act that should not be done.","id":"Berbohong di muka umum merupakan tindakan yang tidak boleh dilakukan."},{"jp":"他人の財産を侵すべからざる行為だ。","romaji":"Tanin no zaisan o okasu bekara zaru koui da.","en":"Infringing on someone else’s property is an act that must not be performed.","id":"Melanggar hak milik orang lain adalah tindakan yang tidak boleh dilakukan."}]},{"pattern":"Verbる べからず (〜ru bekara zu)","meaning":"Expresses the idea of 'must not do' or 'should not do'.","meaningId":"Mengekspresikan gagasan 'tidak boleh melakukan' atau 'tidak boleh melakukan'.","formation":"Verb-ru + べからず","formationId":"Kata kerja-ru + べからず","examples":[{"jp":"嘘をつくべからず。","romaji":"Uso o tsuku bekara zu.","en":"One must not tell lies.","id":"Seseorang tidak boleh berbohong."},{"jp":"彼らの秘密を漏らすべからず。","romaji":"Karera no himitsu o morasu bekara zu.","en":"You must not leak their secrets.","id":"Anda tidak boleh membocorkan rahasia mereka."},{"jp":"ルールを破るべからず。","romaji":"Ruuru o yaburu bekara zu.","en":"You must not break the rules.","id":"Anda tidak boleh melanggar aturan."},{"jp":"勉強を怠るべからず。","romaji":"Benkyou o okotaru bekara zu.","en":"One must not neglect their studies.","id":"Seseorang tidak boleh mengabaikan studi mereka."}]},{"pattern":"Verbる べく (Verb-ru beku)","meaning":"Expresses the meaning of 'in order to', 'for the purpose of'.","meaningId":"Mengungkapkan arti 'untuk', 'untuk tujuan'.","formation":"Verb-dictionary form + べく","formationId":"Bentuk kamus kata kerja + べく","examples":[{"jp":"成功するべく、日々努力しています。","romaji":"Seikou suru beku, hibi doryoku shite imasu.","en":"In order to succeed, I am working hard every day.","id":"Agar berhasil, saya bekerja keras setiap hari."},{"jp":"健康を維持するべく、毎日運動をしています。","romaji":"Kenkou o iji suru beku, mainichi undou o shite imasu.","en":"In order to maintain my health, I exercise every day.","id":"Untuk menjaga kesehatan saya, saya berolahraga setiap hari."},{"jp":"彼は学位を得るべく、毎日勉強しています。","romaji":"Kare wa gakui o eru beku, mainichi benkyou shite imasu.","en":"He studies every day in order to get a degree.","id":"Dia belajar setiap hari untuk mendapatkan gelar."},{"jp":"早く目的地に到着するべく、タクシーを呼びました。","romaji":"Hayaku mokutekichi ni touchaku suru beku, takushii o yobimashita.","en":"I called a taxi in order to arrive at the destination quickly.","id":"Saya memanggil taksi agar cepat sampai di tujuan."}]},{"pattern":"Verbる べくもない (Verb-ru beku mo nai)","meaning":"Means 'it's impossible to...' or 'there's no way to...'.","meaningId":"Berarti 'tidak mungkin...' atau 'tidak mungkin...'.","formation":"Verb-dictionary form + べくもない","formationId":"Bentuk kamus kata kerja + べくもない","examples":[{"jp":"その問題はとても難しく、解くべくもない。","romaji":"Sono mondai wa totemo muzukashiku, toku beku mo nai.","en":"That problem is so difficult that it's impossible to solve.","id":"Masalah itu sangat sulit sehingga tidak mungkin untuk diselesaikan."},{"jp":"彼女はあまりに速く走って、追いつくべくもない。","romaji":"Kanojo wa amari ni hayaku hashitte, oitsuku beku mo nai.","en":"She runs so fast that there's no way to catch up.","id":"Dia berlari sangat cepat sehingga tidak ada cara untuk mengejarnya."},{"jp":"試験の筆記用具を忘れた。書くべくもない。","romaji":"Shiken no hikki yougu o wasureta. Kaku beku mo nai.","en":"I forgot my writing utensils for the test. It's impossible to write.","id":"Saya lupa peralatan menulis saya untuk ujian. Tidak mungkin untuk menulis."},{"jp":"彼はとても高く跳ぶ。追い越すべくもない。","romaji":"Kare wa totemo takaku tobu. Oikosu beku mo nai.","en":"He jumps so high that there's no way to surpass him.","id":"Dia melompat sangat tinggi sehingga tidak ada cara untuk melampauinya."}]},{"pattern":"Verbる までもない (〜ru made mo nai)","meaning":"It's not necessary to the extent of; no need to.","meaningId":"Hal ini tidak perlu sebatas; tidak perlu.","formation":"Verb-る + までもない","formationId":"Kata kerja-る + までもない","examples":[{"jp":"そんなに心配するまでもない。","romaji":"Sonna ni shinpai suru made mo nai.","en":"There's no need to worry that much.","id":"Tidak perlu terlalu khawatir."},{"jp":"電話するまでもないことだ。","romaji":"Denwa suru made mo nai koto da.","en":"It's not something you need to call about.","id":"Itu bukan sesuatu yang perlu Anda hubungi."},{"jp":"小さな失敗であきらめるまでもない。","romaji":"Chiisana shippai de akirameru made mo nai.","en":"You don't need to give up over a small mistake.","id":"Anda tidak perlu menyerah hanya karena kesalahan kecil."},{"jp":"この問題は、会議で話し合うまでもない。","romaji":"Kono mondai wa, kaigi de hanashiau made mo nai.","en":"This problem doesn't need to be discussed at a meeting.","id":"Masalah ini tidak perlu dibicarakan dalam rapat."}]},{"pattern":"Verbる ものとする (〜ru mono to suru)","meaning":"Assuming or deciding something as...","meaningId":"Mengasumsikan atau memutuskan sesuatu sebagai...","formation":"Verb-dictionary form + ものとする","formationId":"Bentuk kamus kata kerja + ものとする","examples":[{"jp":"ここでの話し合いは秘密とするものとします。","romaji":"Koko de no hanashiai wa himitsu to suru mono to shimasu.","en":"The discussions here are to be kept confidential.","id":"Diskusi di sini harus dirahasiakan."},{"jp":"この契約は明日から有効とするものとする。","romaji":"Kono keiyaku wa ashita kara yuukou to suru mono to suru.","en":"This contract shall become effective from tomorrow.","id":"Kontrak ini akan berlaku efektif mulai besok."},{"jp":"彼をチームのリーダーとするものとします。","romaji":"Kare o chiimu no riidaa to suru mono to shimasu.","en":"We will designate him as the team leader.","id":"Kami akan menunjuk dia sebagai pemimpin tim."},{"jp":"この件については終了とするものとする。","romaji":"Kono ken ni tsuite wa shuuryou to suru mono to suru.","en":"We will consider this matter closed.","id":"Kami akan menganggap masalah ini selesai."}]},{"pattern":"Verbる や否や (Verb-ru ya ina ya)","meaning":"Expresses the idea of 'as soon as', 'the moment...'.","meaningId":"Mengekspresikan gagasan 'segera', 'saat itu...'.","formation":"Verb-dictionary form + や否や","formationId":"Bentuk kamus kata kerja + や否や","examples":[{"jp":"彼女が家に帰るや否や、すぐにテレビをつけました。","romaji":"Kanojo ga ie ni kaeru ya ina ya, sugu ni terebi o tsukemashita.","en":"As soon as she returned home, she turned on the TV.","id":"Begitu dia kembali ke rumah, dia menyalakan TV."},{"jp":"私が郵便箱を開けるや否や、手紙が落ちました。","romaji":"Watashi ga yuubinbako o akeru ya ina ya, tegami ga ochimashita.","en":"The moment I opened the mailbox, the letters fell out.","id":"Saat saya membuka kotak surat, surat-surat itu berjatuhan."},{"jp":"子供たちは学校が終わるや否や、公園に走りました。","romaji":"Kodomo-tachi wa gakkou ga owaru ya ina ya, kouen ni hashirimashita.","en":"As soon as school was over, the children ran to the park.","id":"Begitu sekolah usai, anak-anak berlarian ke taman."},{"jp":"父が新聞を読むや否や、何かに震えていました。","romaji":"Chichi ga shinbun o yomu ya ina ya, nanika ni furuete imashita.","en":"The moment my father read the newspaper, he started trembling about something.","id":"Saat ayahku membaca koran, dia mulai gemetar karena sesuatu."}]},{"pattern":"Verbる 始末だ (〜ru shimatsu da)","meaning":"Indicates a (often unfortunate) result or conclusion of an action.","meaningId":"Menunjukkan hasil atau kesimpulan (sering kali disayangkan) dari suatu tindakan.","formation":"Verb-dictionary form + 始末だ","formationId":"Bentuk kamus kata kerja + 始末だ","examples":[{"jp":"忘れてしまって、パスポートを家に置いてくる始末だった。","romaji":"Wasurete shimatte, pasupooto o ie ni oite-kuru shimatsu datta.","en":"I ended up leaving my passport at home because I forgot.","id":"Saya akhirnya meninggalkan paspor saya di rumah karena saya lupa."},{"jp":"毎晩遅くまで働いて、倒れる始末だ。","romaji":"Maiban osoku made hataraite, taoreru shimatsu da.","en":"I work until late every night and end up collapsing.","id":"Saya bekerja sampai larut malam dan akhirnya pingsan."},{"jp":"勉強しなかったので、試験に落ちる始末だ。","romaji":"Benkyou shinakatta node, shiken ni ochiru shimatsu da.","en":"I didn't study, so I ended up failing the exam.","id":"Saya tidak belajar, jadi saya akhirnya gagal dalam ujian."},{"jp":"電車が遅れたため、会議に遅れる始末だ。","romaji":"Densha ga okureta tame, kaigi ni okureru shimatsu da.","en":"Because the train was delayed, I ended up being late for the meeting.","id":"Karena keretanya tertunda, saya akhirnya terlambat menghadiri pertemuan."}]},{"pattern":"Verbる 嫌いがある","meaning":"Tendency to do a negative action; have a bad habit of ~.","meaningId":"Kecenderungan untuk melakukan tindakan negatif; mempunyai kebiasaan buruk ~.","formation":"Verb-dictionary form + 嫌いがある","formationId":"Bentuk kamus kata kerja + 嫌いがある","examples":[{"jp":"彼女は遅刻する嫌いがある。","romaji":"Kanojo wa chikoku suru kirai ga aru.","en":"She has a tendency to be late.","id":"Dia mempunyai kecenderungan untuk terlambat."},{"jp":"私の父はお酒を飲み過ぎる嫌いがある。","romaji":"Watashi no chichi wa osake o nomisugiru kirai ga aru.","en":"My father has a habit of drinking too much alcohol.","id":"Ayah saya memiliki kebiasaan minum terlalu banyak alkohol."},{"jp":"彼は物をすぐ忘れる嫌いがある。","romaji":"Kare wa mono o sugu wasureru kirai ga aru.","en":"He tends to forget things quickly.","id":"Dia cenderung cepat melupakan sesuatu."},{"jp":"彼女は人の話を途中で切る嫌いがある。","romaji":"Kanojo wa hito no hanashi o tochuu de kiru kirai ga aru.","en":"She has a habit of interrupting people while they are speaking.","id":"Dia mempunyai kebiasaan menyela orang ketika mereka sedang berbicara."}]},{"pattern":"いつまで～のやら","meaning":"Expresses uncertainty regarding duration; 'don't know when... will end'.","meaningId":"Menyatakan ketidakpastian mengenai durasi; 'tidak tahu kapan... akan berakhir'.","formation":"いつまで + Verb (dictionary form) + のやら","formationId":"いつまで + Kata Kerja (bentuk kamus) + のやら","examples":[{"jp":"この試験勉強はいつまで続くのやら。","romaji":"Kono shiken benkyou wa itsumade tsuzuku no yara.","en":"I don't know when this exam study will end.","id":"Saya tidak tahu kapan ujian belajar ini akan berakhir."},{"jp":"彼の話がいつ終わるのやら、わからない。","romaji":"Kare no hanashi ga itsu owaru no yara, wakaranai.","en":"I don't know when his talk will finish.","id":"Saya tidak tahu kapan pembicaraannya akan selesai."},{"jp":"この雨がいつまで降り続くのやら。","romaji":"Kono ame ga itsumade furitsuzuku no yara.","en":"I don't know when this rain will stop.","id":"Entah kapan hujan ini akan berhenti."},{"jp":"コロナのパンデミックがいつまで続くのやら。","romaji":"Korona no pandemikku ga itsumade tsuzuku no yara.","en":"I don't know when this coronavirus pandemic will end.","id":"Saya tidak tahu kapan pandemi virus corona ini akan berakhir."}]},{"pattern":"～が Verb られる (〜ga Verb rareru)","meaning":"Expresses potential or ability to do something; 'can', 'able to'.","meaningId":"Mengekspresikan potensi atau kemampuan untuk melakukan sesuatu; 'bisa', 'mampu'.","formation":"❶ (Group 1) Verb:  書く → 書ける / 飲む → 飲める, etc.\n❷ (Group 2) Verb-ます stem + られる (食べる→食べられる、見る→見られる)","formationId":"❶ (Grup 1) Kata Kerja: 書く → 書ける / 飲む → 飲める, dst.\n❷ (Grup 2) Kata Kerja-ます batang + られる (食べる→食べられる、見る→見られる)","examples":[{"jp":"彼がこの問題を解けると思いますか？","romaji":"Kare ga kono mondai o tokeru to omoimasu ka?","en":"Do you think he can solve this problem?","id":"Apakah menurut Anda dia bisa menyelesaikan masalah ini?"},{"jp":"私がその大きな箱を運べるか？","romaji":"Watashi ga sono ookina hako o hakoberu ka?","en":"Can I carry that big box?","id":"Bisakah saya membawa kotak besar itu?"},{"jp":"彼が早く走れると思います。","romaji":"Kare ga hayaku hashireru to omoimasu.","en":"I think he can run fast.","id":"Menurutku dia bisa berlari dengan cepat."},{"jp":"彼女は日本語が話せる。","romaji":"Kanojo wa nihongo ga hanaseru.","en":"She can speak Japanese.","id":"Dia bisa berbicara bahasa Jepang."}]},{"pattern":"～かと思いきや (〜ka to omoikiya)","meaning":"Expressing unexpected outcomes; 'just when I thought...', 'but...'.","meaningId":"Mengekspresikan hasil yang tidak terduga; 'tepat ketika aku berpikir...', 'tapi...'.","formation":"Sentence + かと思いきや (Verb plain form, i-/na-Adjective, or Noun + だ + かと思いきや)","formationId":"Kalimat + かと思いきや (Kata kerja bentuk biasa, kata sifat i-/na, atau Kata Benda + だ + かと思いきや)","examples":[{"jp":"明日は晴れるかと思いきや、まさかの雨が降った。","romaji":"Ashita wa hareru ka to omoikiya, masaka no ame ga futta.","en":"I thought it would be sunny tomorrow, but unexpectedly it rained.","id":"Saya pikir besok akan cerah, tetapi tiba-tiba turun hujan."},{"jp":"彼が試験に落ちたかと思いきや、合格していた。","romaji":"Kare ga shiken ni ochita ka to omoikiya, goukaku shite ita.","en":"I thought he had failed the test, but he actually passed.","id":"Saya pikir dia telah gagal dalam ujian, tetapi dia benar-benar lulus."},{"jp":"このケーキは美味しそうだったかと思いきや、全然甘くなかった。","romaji":"Kono keeki wa oishisou datta ka to omoikiya, zenzen amakunakatta.","en":"I thought this cake would be delicious, but it wasn’t sweet at all.","id":"Saya pikir kue ini enak, tapi ternyata tidak manis sama sekali."},{"jp":"列車が遅れるかと思いきや、時間通りに到着した。","romaji":"Ressha ga okureru ka to omoikiya, jikan doori ni touchaku shita.","en":"I thought the train would be late, but it arrived on time.","id":"Saya pikir keretanya akan terlambat, tapi ternyata tiba tepat waktu."}]},{"pattern":"～がゆえに","meaning":"Expresses the reason or cause; 'because', 'due to', 'as a result of'.","meaningId":"Mengungkapkan alasan atau sebab; 'karena', 'akibat', 'akibat'.","formation":"Noun / Verb / Adjective + がゆえに","formationId":"Kata Benda / Kata Kerja / Kata Sifat + がゆえに","examples":[{"jp":"愛情がゆえに、彼は彼女を許した。","romaji":"Aijou ga yue ni, kare wa kanojo o yurushita.","en":"Because of love, he forgave her.","id":"Karena cinta, dia memaafkannya."},{"jp":"突然の雨がゆえに、試合は延期された。","romaji":"Totsuzen no ame ga yue ni, shiai wa enki sareta.","en":"Due to the sudden rain, the match was postponed.","id":"Karena hujan yang tiba-tiba, pertandingan ditunda."},{"jp":"彼の努力がゆえに、彼は成功を収めた。","romaji":"Kare no doryoku ga yue ni, kare wa seikou o osameta.","en":"Because of his efforts, he achieved success.","id":"Karena usahanya, ia mencapai kesuksesan."},{"jp":"彼の死がゆえに、彼の家族は深い悲しみに包まれた。","romaji":"Kare no shi ga yue ni, kare no kazoku wa fukai kanashimi ni tsutsumareta.","en":"Due to his death, his family was enveloped in deep sorrow.","id":"Atas kematiannya, keluarganya diliputi duka yang mendalam."}]},{"pattern":"～がゆえの Noun (〜ga yue no Noun)","meaning":"Expresses the reason or cause for something; 'because of', 'due to'.","meaningId":"Mengungkapkan alasan atau penyebab sesuatu; 'karena', 'karena'.","formation":"Noun / Verb-dictionary form + がゆえの + Noun","formationId":"Bentuk kamus Kata Benda / Kata Kerja + がゆえの + Kata Benda","examples":[{"jp":"愛がゆえの悲しみ。","romaji":"Ai ga yue no kanashimi.","en":"Sadness due to love.","id":"Kesedihan karena cinta."},{"jp":"健康がゆえの幸せ。","romaji":"Kenkou ga yue no shiawase.","en":"Happiness due to good health.","id":"Kebahagiaan karena kesehatan yang baik."},{"jp":"悪行がゆえの罰。","romaji":"Akugyou ga yue no batsu.","en":"Punishment due to wrongdoing.","id":"Hukuman karena kesalahan."},{"jp":"努力がゆえの成功。","romaji":"Doryoku ga yue no seikou.","en":"Success due to effort.","id":"Kesuksesan karena usaha."}]},{"pattern":"～から Noun に 至る まで (〜kara 〜ni itaru made)","meaning":"Expressing range from one thing to another; 'from...to', 'ranging from...to'.","meaningId":"Mengekspresikan rentang dari satu hal ke hal lainnya; 'dari...ke', 'mulai dari...ke'.","formation":"Noun (start) + から + Noun (end) + に至るまで","formationId":"Kata Benda (awal) + から + Kata Benda (akhir) + に至るまで","examples":[{"jp":"このバンドの曲は、青年から老人に至るまで、人々に愛されています。","romaji":"Kono bando no kyoku wa, seinen kara roujin ni itaru made, hitobito ni aisarete imasu.","en":"The songs of this band are loved by people ranging from the young to the elderly.","id":"Lagu-lagu band ini banyak digandrungi masyarakat mulai dari kalangan muda hingga orang tua."},{"jp":"小さい物件から大きな建物に至るまで、全てのプロパティの管理を我々が行います。","romaji":"Chiisai bukken kara ooki na tatemono ni itaru made, subete no property no kanri o wareware ga okonaimasu.","en":"We handle all property management, ranging from small units to large buildings.","id":"Kami menangani seluruh pengelolaan properti, mulai dari unit kecil hingga bangunan besar."},{"jp":"朝のニュース放送から夜のドラマに至るまで、テレビは毎日見ています。","romaji":"Asa no nyuusu housou kara yoru no dorama ni itaru made, terebi wa mainichi mite imasu.","en":"I watch TV every day, from the morning news broadcasts to the night dramas.","id":"Saya menonton TV setiap hari, dari siaran berita pagi hingga drama malam."},{"jp":"この地域は、春から冬に至るまで旅行者で賑わいます。","romaji":"Kono chiiki wa, haru kara fuyu ni itaru made ryokousha de nigiwaimasu.","en":"This area is bustling with tourists from spring to winter.","id":"Kawasan ini ramai dikunjungi wisatawan dari musim semi hingga musim dingin."}]},{"pattern":"～ごとく (〜gotoku)","meaning":"To seem like; as if; as though.","meaningId":"Sepertinya; seolah olah; seperti.","formation":"Verb-て + ごとく / Noun + の + ごとく","formationId":"Kata Kerja-て + ごとく / Kata Benda + の + ごとく","examples":[{"jp":"彼は鳥のごとく飛んでいるように見えた。","romaji":"Kare wa tori no gotoku tonde iru you ni mieta.","en":"He looked as though he was flying like a bird.","id":"Dia tampak seperti sedang terbang seperti burung."},{"jp":"彼は死んだごとく眠っていた。","romaji":"Kare wa shinda gotoku nemutte ita.","en":"He was sleeping as though he were dead.","id":"Dia tertidur seolah-olah dia sudah mati."},{"jp":"彼女はアイドルのごとく崇められている。","romaji":"Kanojo wa aidoru no gotoku agamerarete iru.","en":"She is revered as if she were an idol.","id":"Dia dihormati seolah-olah dia adalah seorang idola."},{"jp":"彼は風のごとく走った。","romaji":"Kare wa kaze no gotoku hashitta.","en":"He ran like the wind.","id":"Dia berlari seperti angin."}]},{"pattern":"～こととて (〜koto tote)","meaning":"Used to express the reason or premise for a decision or judgment; 'since', 'because'.","meaningId":"Digunakan untuk menyatakan alasan atau premis suatu keputusan atau penilaian; 'sejak', 'karena'.","formation":"Verb (plain form) + こととて / Noun + の + こととて / (な-Adjective + な) + こととて","formationId":"Kata Kerja (bentuk biasa) + こととて / Kata Benda + の + こととて / (な-Kata Sifat + な) + こととて","examples":[{"jp":"彼は裁判に勝つために全資産を使うこととて、弁護士に頼んだ。","romaji":"Kare wa saiban ni katsu tame ni zenshisan o tsukau koto tote, bengoshi ni tanonda.","en":"Since he's using all his assets to win the trial, he hired a lawyer.","id":"Karena dia menggunakan seluruh asetnya untuk memenangkan persidangan, dia menyewa seorang pengacara."},{"jp":"明日は大切な試験があることとて、今夜は早く寝ます。","romaji":"Ashita wa taisetsu na shiken ga aru koto tote, konya wa hayaku nemasu.","en":"Since I have an important exam tomorrow, I’m going to bed early tonight.","id":"Karena aku ada ujian penting besok, aku akan tidur lebih awal malam ini."},{"jp":"このプロジェクトの成功は会社の未来に影響することとて、全力を尽くします。","romaji":"Kono purojekuto no seikou wa kaisha no mirai ni eikyou suru koto tote, zenryoku o tsukushimasu.","en":"Because the success of this project will affect the company's future, I will do my best.","id":"Karena keberhasilan proyek ini akan mempengaruhi masa depan perusahaan, saya akan melakukan yang terbaik."},{"jp":"彼が有名人であることとて、プライバシーが保護されるべきだ。","romaji":"Kare ga yuumeijin de aru koto tote, puraibashii ga hogo sareru beki da.","en":"Since he is a celebrity, his privacy should be protected.","id":"Karena dia seorang selebriti, privasinya harus dilindungi."}]},{"pattern":"～ずにすんだ (〜zuni sunda)","meaning":"Expresses the idea of 'was able to do without'; 'managed to avoid'.","meaningId":"Mengekspresikan gagasan 'mampu melakukan tanpa'; 'berhasil menghindari'.","formation":"Verb-ず form + に + すんだ","formationId":"Bentuk kata kerja-ず + に + すんだ","examples":[{"jp":"彼は事故を起こさずにすんだ。","romaji":"Kare wa jiko o okosazu ni sunda.","en":"He managed to avoid having an accident.","id":"Dia berhasil menghindari kecelakaan."},{"jp":"私は手術せずにすんだ。","romaji":"Watashi wa shujutsu sezu ni sunda.","en":"I was able to do without surgery.","id":"Saya bisa melakukannya tanpa operasi."},{"jp":"雨が降らずにすんだ。","romaji":"Ame ga furazu ni sunda.","en":"We managed to avoid the rain.","id":"Kami berhasil menghindari hujan."},{"jp":"罰金を払わずにすんだ。","romaji":"Bakkin o harawazu ni sunda.","en":"I managed to avoid paying a fine.","id":"Saya berhasil menghindari membayar denda."}]},{"pattern":"～だろうとなかろうと (〜darou to nakarou to)","meaning":"Expresses 'regardless of whether it is or isn't'.","meaningId":"Mengekspresikan 'terlepas dari apakah itu benar atau tidak'.","formation":"Noun / i-Adjective / na-Adjective / Verb + だろうとなかろうと","formationId":"Kata Benda / Kata Sifat-i / Kata Sifat-na / Kata Kerja + だろうとなかろうと","examples":[{"jp":"試験が難しいだろうとなかろうと、全力で頑張ります。","romaji":"Shiken ga muzukashii darou to nakarou to, zenryoku de ganbarimasu.","en":"Regardless of whether the exam is difficult or not, I will do my best.","id":"Terlepas dari apakah ujiannya sulit atau tidak, saya akan melakukan yang terbaik."},{"jp":"彼が来るだろうとなかろうと、私たちは始めます。","romaji":"Kare ga kuru darou to nakarou to, watashitachi wa hajimemasu.","en":"Whether he comes or not, we will start.","id":"Apakah dia datang atau tidak, kami akan mulai."},{"jp":"この仕事が面白いだろうとなかろうと、私は続けます。","romaji":"Kono shigoto ga omoshiroi darou to nakarou to, watashi wa tsuzukemasu.","en":"Whether this job is interesting or not, I will continue.","id":"Menarik atau tidaknya pekerjaan ini, saya akan melanjutkannya."},{"jp":"彼が賛成するだろうとなかろうと、私たちは進行します。","romaji":"Kare ga sansei suru darou to nakarou to, watashitachi wa shinkou shimasu.","en":"Whether he agrees or not, we will proceed.","id":"Apakah dia setuju atau tidak, kami akan melanjutkan."}]},{"pattern":"～つもりだ (〜tsumori da)","meaning":"Expresses the speaker's intention or plan.","meaningId":"Mengungkapkan maksud atau rencana pembicara.","formation":"Verb-dictionary form + つもりだ","formationId":"Bentuk kamus kata kerja + つもりだ","examples":[{"jp":"明日は早く起きるつもりです。","romaji":"Ashita wa hayaku okiru tsumori desu.","en":"I plan to wake up early tomorrow.","id":"Saya berencana untuk bangun pagi-pagi besok."},{"jp":"私は日本語を勉強するつもりです。","romaji":"Watashi wa nihongo o benkyou suru tsumori desu.","en":"I intend to study Japanese.","id":"Saya berniat untuk belajar bahasa Jepang."},{"jp":"彼は留学するつもりだと言った。","romaji":"Kare wa ryuugaku suru tsumori da to itta.","en":"He said he plans to study abroad.","id":"Dia bilang dia berencana untuk belajar di luar negeri."},{"jp":"私は来週末に家族と旅行するつもりだ。","romaji":"Watashi wa raishuumatsu ni kazoku to ryokou suru tsumori da.","en":"I plan to travel with my family next weekend.","id":"Saya berencana untuk bepergian bersama keluarga saya akhir pekan depan."}]},{"pattern":"～つもりで (〜tsumori de)","meaning":"Expresses the speaker's intention or plan; 'with the intention of', 'planning to'.","meaningId":"Mengungkapkan maksud atau rencana pembicara; 'dengan maksud', 'berencana untuk'.","formation":"Verb-dictionary form + つもりで","formationId":"Bentuk kamus kata kerja + つもりで","examples":[{"jp":"私は日本に住むつもりで日本語を勉強しています。","romaji":"Watashi wa Nihon ni sumu tsumori de Nihongo o benkyou shiteimasu.","en":"I am studying Japanese with the intention of living in Japan.","id":"Saya belajar bahasa Jepang dengan tujuan tinggal di Jepang."},{"jp":"彼は全てを失うつもりでギャンブルをしました。","romaji":"Kare wa subete o ushinau tsumori de gyanburu o shimashita.","en":"He gambled with the intention of risking everything.","id":"Dia berjudi dengan tujuan mempertaruhkan segalanya."},{"jp":"明日のテストに合格するつもりで一生懸命勉強します。","romaji":"Ashita no tesuto ni goukaku suru tsumori de isshoukenmei benkyou shimasu.","en":"I will study hard with the intention of passing tomorrow’s test.","id":"Saya akan belajar keras dengan tujuan lulus ujian besok."},{"jp":"彼は早く起きるつもりで早く寝ました。","romaji":"Kare wa hayaku okiru tsumori de hayaku nemashita.","en":"He went to bed early with the intention of waking up early.","id":"Dia pergi tidur lebih awal dengan niat untuk bangun lebih awal."}]},{"pattern":"～ではすまない (〜dewa sumanai)","meaning":"Expresses that just doing something is not enough or will not suffice.","meaningId":"Menyatakan bahwa melakukan sesuatu saja tidak cukup atau tidak akan cukup.","formation":"Verb-dictionary form + ではすまない / い-Adjective + ではすまない / な-Adjective + ではすまない / Noun + ではすまない","formationId":"Bentuk kamus kata kerja + ではすまない / い-Kata Sifat + ではすまない / な-Kata Sifat + ではすまない / Kata Benda + ではすまない","examples":[{"jp":"ただ謝るではすまない。何か行動を取らなければならない。","romaji":"Tada ayamaru dewa sumanai. Nanika koudou o toranakereba naranai.","en":"Just apologizing will not suffice. Some action needs to be taken.","id":"Meminta maaf saja tidak akan cukup. Beberapa tindakan perlu diambil."},{"jp":"この問題は議論だけではすまない。具体的な計画が必要だ。","romaji":"Kono mondai wa giron dake dewa sumanai. Gutaiteki na keikaku ga hitsuyou da.","en":"This problem won't be solved with just discussions. A concrete plan is needed.","id":"Masalah ini tidak akan terselesaikan hanya dengan diskusi. Diperlukan rencana konkrit."},{"jp":"彼の失敗は注意だけではすまない。彼はその責任を取るべきだ。","romaji":"Kare no shippai wa chuui dake dewa sumanai. Kare wa sono sekinin o toru beki da.","en":"His failure won't be resolved with just a warning. He should take responsibility.","id":"Kegagalannya tidak akan terselesaikan hanya dengan peringatan. Dia harus mengambil tanggung jawab."},{"jp":"この失敗は金だけではすまない。信頼を取り戻すため、真心で謝罪するべきだ。","romaji":"Kono shippai wa kane dake dewa sumanai. Shinrai o torimodosu tame, magokoro de shazai suru beki da.","en":"This mistake cannot be settled with money alone. To regain trust, an earnest apology is needed.","id":"Kesalahan ini tidak bisa diselesaikan hanya dengan uang. Untuk mendapatkan kembali kepercayaan, diperlukan permintaan maaf yang tulus."}]},{"pattern":"～とあって (〜to atte)","meaning":"Expresses a special situation or event due to certain circumstances.","meaningId":"Mengekspresikan situasi atau peristiwa khusus karena keadaan tertentu.","formation":"Noun + とあって / (Sometimes Verb + とあって, depending on context)","formationId":"Kata Benda + とあって / (Terkadang Kata Kerja + とあって, tergantung konteksnya)","examples":[{"jp":"春休みとあって、公園は子供たちでいっぱいだ。","romaji":"Haruyasumi to atte, kouen wa kodomo-tachi de ippai da.","en":"Because it's spring break, the park is full of children.","id":"Karena ini liburan musim semi, taman ini penuh dengan anak-anak."},{"jp":"試験前とあって、図書館は学生で混んでいる。","romaji":"Shiken mae to atte, toshokan wa gakusei de konde iru.","en":"With exams coming up, the library is crowded with students.","id":"Menjelang ujian, perpustakaan dipenuhi siswa."},{"jp":"開店日とあって、その店にはたくさんの人が並んでいた。","romaji":"Kaitenbi to atte, sono mise ni wa takusan no hito ga narande ita.","en":"Because it was the store's opening day, a lot of people lined up.","id":"Karena ini hari pembukaan toko, banyak orang yang mengantri."},{"jp":"彼の誕生日とあって、友人たちはサプライズパーティーを計画した。","romaji":"Kare no tanjoubi to atte, yuujin-tachi wa sapuraizu paatii o keikaku shita.","en":"Because it was his birthday, his friends planned a surprise party.","id":"Karena ini hari ulang tahunnya, teman-temannya merencanakan pesta kejutan."}]},{"pattern":"～とあれば (〜to areba)","meaning":"Expresses a condition; 'if', 'when', 'since'.","meaningId":"Menyatakan suatu kondisi; 'jika', 'kapan', 'sejak'.","formation":"Verb-casual + とあれば / い-Adjective + とあれば / な-Adjective + だとあれば / Noun + だとあれば","formationId":"Kata Kerja-kasual + とあれば / い-Kata Sifat + とあれば / な-Kata Sifat + だとあれば / Kata Benda + だとあれば","examples":[{"jp":"無料とあれば、誰でも利用したいと思います。","romaji":"Muryou to areba, dare demo riyou shitai to omoimasu.","en":"If it's free, anyone would want to use it.","id":"Kalau gratis, siapa pun pasti mau menggunakannya."},{"jp":"この曲が流れるとあれば、彼は必ず踊り始めます。","romaji":"Kono kyoku ga nagareru to areba, kare wa kanarazu odorihajimemasu.","en":"If this song starts playing, he will definitely begin to dance.","id":"Jika lagu ini mulai diputar, dia pasti akan mulai menari."},{"jp":"明日が休日だとあれば、今夜は遅くまで起きていられます。","romaji":"Ashita ga kyuujitsu da to areba, konya wa osoku made okite iraremasu.","en":"If tomorrow is a holiday, I can stay up late tonight.","id":"Jika besok adalah hari libur, saya bisa begadang malam ini."},{"jp":"彼が参加するとあれば、このイベントは成功でしょう。","romaji":"Kare ga sanka suru to areba, kono ibento wa seikou deshou.","en":"If he participates, this event will surely be successful.","id":"Jika dia berpartisipasi, acara ini pasti sukses."}]},{"pattern":"～といえども (〜to iedomo)","meaning":"Even if it is said that; Even though; Although.","meaningId":"Sekalipun dikatakan demikian; Meskipun; Meskipun.","formation":"Noun + といえども / Verb-plain form + といえども / Adjective + といえども","formationId":"Kata benda + といえども / Kata kerja-bentuk biasa + といえども / Kata Sifat + といえども","examples":[{"jp":"彼が天才といえども、ミスをすることはあります。","romaji":"Kare ga tensai to iedomo, misu o suru koto wa arimasu.","en":"Even though he’s a genius, he still makes mistakes.","id":"Meskipun dia jenius, dia tetap saja melakukan kesalahan."},{"jp":"このパソコンが新しいといえども、問題があります。","romaji":"Kono pasokon ga atarashii to iedomo, mondai ga arimasu.","en":"Even though this computer is new, it has problems.","id":"Walaupun komputer ini masih baru, namun ada masalah."},{"jp":"春といえども、まだ寒い日があります。","romaji":"Haru to iedomo, mada samui hi ga arimasu.","en":"Even though it's spring, there are still cold days.","id":"Meskipun saat ini musim semi, hari-hari masih terasa dingin."},{"jp":"彼女が一番好きな人といえども、嫌なことは嫌です。","romaji":"Kanojo ga ichiban suki na hito to iedomo, iya na koto wa iya desu.","en":"Even though she’s my favorite person, unpleasant things are still unpleasant.","id":"Meskipun dia orang favoritku, hal-hal yang tidak menyenangkan tetaplah tidak menyenangkan."}]},{"pattern":"～といったらありはしない (〜to ittara ari wa shinai)","meaning":"Express extreme exclamation; 'extremely', 'unbelievable', 'unsurpassed'.","meaningId":"Ekspresikan seruan ekstrem; 'sangat', 'luar biasa', 'tak tertandingi'.","formation":"Noun + といったらありはしない / な-Adjective + といったらありはしない","formationId":"Kata Benda + といったらありはしない / な-Kata Sifat + といったらありはしない","examples":[{"jp":"彼の英語の上手さといったらありはしない。","romaji":"Kare no eigo no jouzusa to ittara ari wa shinai.","en":"His English is unbelievably good.","id":"Bahasa Inggrisnya luar biasa bagus."},{"jp":"このスイーツの美味しさといったらありはしない。","romaji":"Kono suiitsu no oishisa to ittara ari wa shinai.","en":"These sweets are unbelievably delicious.","id":"Permen ini luar biasa lezatnya."},{"jp":"その子の頭の良さといったらありはしない。","romaji":"Sono ko no atama no yosa to ittara ari wa shinai.","en":"That kid's intelligence is unsurpassed.","id":"Kecerdasan anak itu tidak tertandingi."},{"jp":"彼女の美しさといったらありはしない。","romaji":"Kanojo no utsukushisa to ittara ari wa shinai.","en":"Her beauty is beyond belief.","id":"Kecantikannya melampaui keyakinan."}]},{"pattern":"～といったらありゃしない (〜to ittara arya shinai)","meaning":"Emphasizes that something is to the extreme; 'you have no idea how...', 'it's incredibly...'.","meaningId":"Menekankan bahwa ada sesuatu yang ekstrem; 'Anda tidak tahu bagaimana...', 'ini luar biasa...'.","formation":"Verb-casual + といったらありゃしない / い-Adjective + といったらありゃしない / な-Adjective + だ + といったらありゃしない / Noun + だ + といったらありゃしない","formationId":"Kata Kerja-kasual + といったらありゃしない / い-Kata Sifat + といったらありゃしない / な-Kata Sifat + だ +といったらありゃしない / Kata Benda + だ + といったらありゃしない","examples":[{"jp":"その店のラーメンは美味しいといったらありゃしない。","romaji":"Sono mise no ramen wa oishii to ittara arya shinai.","en":"You have no idea how delicious the ramen at that shop is.","id":"Anda tidak tahu betapa lezatnya ramen di toko itu."},{"jp":"彼女の料理の腕前は上手だといったらありゃしない。","romaji":"Kanojo no ryouri no udemae wa jouzu da to ittara arya shinai.","en":"You have no idea how skilled she is at cooking.","id":"Anda tidak tahu betapa terampilnya dia dalam memasak."},{"jp":"この冬の寒さは厳しいといったらありゃしない。","romaji":"Kono fuyu no samusa wa kibishii to ittara arya shinai.","en":"You have no idea how harsh this winter's cold is.","id":"Anda tidak tahu betapa kerasnya musim dingin ini."},{"jp":"その小説は面白いといったらありゃしない。","romaji":"Sono shousetsu wa omoshiroi to ittara arya shinai.","en":"You have no idea how interesting that novel is.","id":"Anda tidak tahu betapa menariknya novel itu."}]},{"pattern":"～といったらない (〜to ittara nai)","meaning":"Expresses the extreme of something; 'nothing can be more ... than this'.","meaningId":"Mengekspresikan sesuatu yang ekstrim; 'tidak ada yang lebih...dari ini'.","formation":"い-Adjective + といったらない / な-Adjective + だといったらない / Noun + だといったらない","formationId":"い-Kata Sifat + といったらない / な-Kata Sifat + だといったらない / Kata Benda + だといったらない","examples":[{"jp":"今日は寒いといったらない。","romaji":"Kyou wa samui to ittara nai.","en":"It’s extremely cold today.","id":"Hari ini sangat dingin."},{"jp":"彼女の料理の美味しさといったらない。","romaji":"Kanojo no ryouri no oishisa to ittara nai.","en":"Nothing can be more delicious than her cooking.","id":"Tidak ada yang lebih enak dari masakannya."},{"jp":"この子の頭の良さだといったらない。","romaji":"Kono ko no atama no yosa da to ittara nai.","en":"This child is unbelievably smart.","id":"Anak ini luar biasa pintar."},{"jp":"彼の怠けっぷりだといったらない。","romaji":"Kare no namakeppuri da to ittara nai.","en":"Nobody could be lazier than him.","id":"Tidak ada yang lebih malas dari dia."}]},{"pattern":"～ときている (〜to kite iru)","meaning":"Highlights a situation or condition that is serious/extreme, often with a negative nuance.","meaningId":"Menyoroti situasi atau kondisi yang serius/ekstrim, seringkali bernuansa negatif.","formation":"Verb-casual / い-Adjective / な-Adjective（＋だ） / Noun（＋だ） + ときている","formationId":"Kata Kerja-kasual / い-Kata Sifat / な-Kata Sifat（＋だ） / Kata Benda（＋だ） + ときている","examples":[{"jp":"仕事が忙しいときているので、なかなか休みが取れません。","romaji":"Shigoto ga isogashii to kite iru no de, nakanaka yasumi ga toremasen.","en":"Because work is so busy, I just can’t take any time off.","id":"Karena pekerjaan sangat sibuk, saya tidak bisa mengambil cuti."},{"jp":"経済が悪いときているだけに、会社が大量解雇を発表した。","romaji":"Keizai ga warui to kite iru dake ni, kaisha ga tairyou kaiko o happyou shita.","en":"Since the economy is in such bad shape, the company announced mass layoffs.","id":"Karena kondisi perekonomian sedang buruk, perusahaan mengumumkan PHK massal."},{"jp":"旅行先で荷物を盗まれたときているから、旅行を楽しむどころではない。","romaji":"Ryokousaki de nimotsu o nusumareta to kite iru kara, ryokou o tanoshimu dokoro de wa nai.","en":"Given that my luggage was stolen while traveling, there’s no way I can enjoy the trip.","id":"Mengingat bagasi saya dicuri saat bepergian, tidak mungkin saya dapat menikmati perjalanan tersebut."},{"jp":"試験が近いときているうえに、課題も山ほどあって大変だ。","romaji":"Shiken ga chikai to kite iru ue ni, kadai mo yamahodo atte taihen da.","en":"Not only are exams coming up, but I also have a mountain of assignments, so it’s really tough.","id":"Bukan hanya ujian yang akan datang, tapi tugasku juga segudang, jadi ini sangat berat."}]},{"pattern":"～ところを (〜tokoro wo)","meaning":"Indicates a contrasting or inconvenient timing; 'just when...', 'even though...'.","meaningId":"Menunjukkan waktu yang kontras atau tidak tepat; 'saat...', 'padahal...'.","formation":"Verb-ている + ところを / Noun + の + ところを / い-Adjective + ところを / な-Adjective + な + ところを","formationId":"Kata Kerja-ている + ところを / Kata Benda + の + ところを / い-Kata Sifat + ところを / な-Kata Sifat + な + ところを","examples":[{"jp":"ちょうど映画を見ているところを、停電で真っ暗になった。","romaji":"Choudo eiga o mite iru tokoro o, teiden de makkura ni natta.","en":"Just when I was in the middle of watching a movie, the power went out and everything went dark.","id":"Tepat ketika saya sedang menonton film, listrik padam dan semuanya menjadi gelap."},{"jp":"美味しく食べているところを、彼が全部横取りしてしまった。","romaji":"Oishiku tabete iru tokoro o, kare ga zenbu yokodori shite shimatta.","en":"Right when I was enjoying my meal, he took it all away.","id":"Tepat ketika saya sedang menikmati makanan saya, dia mengambil semuanya."},{"jp":"飛行機が離陸しようとしているところを、急にエンジンが止まった。","romaji":"Hikouki ga ririku shiyou to shite iru tokoro o, kyuu ni enjin ga tomatta.","en":"Just as the plane was about to take off, the engine suddenly stopped.","id":"Saat pesawat hendak lepas landas, mesin tiba-tiba mati."},{"jp":"彼女が怒っているところを、私は冗談を言ってしまった。","romaji":"Kanojo ga okotte iru tokoro o, watashi wa joudan o itte shimatta.","en":"Even though she was angry, I went ahead and made a joke.","id":"Meskipun dia marah, saya terus saja melontarkan lelucon."}]},{"pattern":"～とされる (〜to sareru)","meaning":"Indicates a general belief or widely accepted view; 'is considered', 'is seen as', 'is said to be'.","meaningId":"Menunjukkan keyakinan umum atau pandangan yang diterima secara luas; 'dianggap', 'dilihat sebagai', 'dikatakan sebagai'.","formation":"Verb-casual + とされる / い-Adjective + とされる / な-Adjective + だとされる / Noun + だとされる","formationId":"Kata Kerja-kasual + とされる / い-Kata Sifat + とされる / な-Kata Sifat + だとされる / Kata Benda + だとされる","examples":[{"jp":"サッカーは世界で最も人気のあるスポーツとされています。","romaji":"Sakkaa wa sekai de mottomo ninki no aru supootsu to sarete imasu.","en":"Soccer is considered the most popular sport in the world.","id":"Sepak bola dianggap sebagai olahraga paling populer di dunia."},{"jp":"彼は最も有能な科学者とされる。","romaji":"Kare wa mottomo yuunou na kagakusha to sareru.","en":"He is considered the most talented scientist.","id":"Ia dianggap sebagai ilmuwan paling berbakat."},{"jp":"この建物は地元のランドマークだとされています。","romaji":"Kono tatemono wa jimoto no randomaaku da to sarete imasu.","en":"This building is said to be a local landmark.","id":"Bangunan ini dikatakan sebagai landmark lokal."},{"jp":"そのお寺は古代の美術品とされている。","romaji":"Sono otera wa kodai no bijutsuhin to sarete iru.","en":"That temple is considered an ancient work of art.","id":"Kuil itu dianggap sebagai karya seni kuno."}]},{"pattern":"～としたところで (〜to shita tokoro de)","meaning":"Means 'even if' or 'even assuming'; emphasizes that the outcome won’t change.","meaningId":"Berarti 'sekalipun' atau 'sekalipun berasumsi'; menekankan bahwa hasilnya tidak akan berubah.","formation":"Verb-casual + としたところで / い-Adjective + としたところで / な-Adjective + だとしたところで / Noun + だとしたところで","formationId":"Kata Kerja-kasual + としたところで / い-Kata Sifat + としたところで / な-Kata Sifat + だとしたところで / Kata Benda +だとしたところで","examples":[{"jp":"彼が来るとしたところで、何も変わらないだろう。","romaji":"Kare ga kuru to shita tokoro de, nani mo kawaranai darou.","en":"Even if he comes, nothing will probably change.","id":"Bahkan jika dia datang, mungkin tidak ada yang berubah."},{"jp":"美味しいお菓子を作るとしたところで、それが売れる保証はない。","romaji":"Oishii okashi o tsukuru to shita tokoro de, sore ga ureru hoshou wa nai.","en":"Even if we make delicious sweets, there's no guarantee they’ll sell.","id":"Meskipun kita membuat manisan yang enak, tidak ada jaminan manisan tersebut akan terjual."},{"jp":"電話をかけるとしたところで、彼女が出るとは限らない。","romaji":"Denwa o kakeru to shita tokoro de, kanojo ga deru to wa kagiranai.","en":"Even if I call her, she might not pick up.","id":"Bahkan jika aku meneleponnya, dia mungkin tidak mengangkatnya."},{"jp":"最高の材料を使うとしたところで、美味しくなるとは限らない。","romaji":"Saikou no zairyou o tsukau to shita tokoro de, oishiku naru to wa kagiranai.","en":"Even if you use the best ingredients, it might not turn out delicious.","id":"Meskipun Anda menggunakan bahan-bahan terbaik, hasilnya mungkin tidak enak."}]},{"pattern":"～とすると (〜to suru to)","meaning":"Expresses 'if', 'when', or 'assuming that' in a speculative sense.","meaningId":"Mengekspresikan 'jika', 'kapan', atau 'mengasumsikan itu' dalam arti spekulatif.","formation":"Verb-casual + とすると / い-Adjective + とすると / な-Adjective + だとすると / Noun + だとすると","formationId":"Kata Kerja-kasual + とすると / い-Kata Sifat + とすると / な-Kata Sifat + だとすると / Kata Benda + だとすると","examples":[{"jp":"彼が来るとすると、もうすぐ到着するはずです。","romaji":"Kare ga kuru to suru to, mou sugu touchaku suru hazu desu.","en":"If he’s coming, he should arrive soon.","id":"Jika dia datang, dia akan segera tiba."},{"jp":"この仕事を終えるとすると、最低でも3日はかかるでしょう。","romaji":"Kono shigoto o oeru to suru to, saitei demo mikka wa kakaru deshou.","en":"Assuming we finish this work, it will take at least three days.","id":"Dengan asumsi kita menyelesaikan pekerjaan ini, maka akan memakan waktu setidaknya tiga hari."},{"jp":"戦争が起きるとすると、多くの人々が犠牲になるでしょう。","romaji":"Sensou ga okiru to suru to, ooku no hitobito ga gisei ni naru deshou.","en":"If a war were to break out, many people would become victims.","id":"Jika terjadi perang, banyak orang yang akan menjadi korban."},{"jp":"彼が経営者だとすると、多くの責任を負うことになるでしょう。","romaji":"Kare ga keieisha da to suru to, ooku no sekinin o ou koto ni naru deshou.","en":"If he’s the manager, he will bear a lot of responsibility.","id":"Jika dia manajernya, dia akan memikul banyak tanggung jawab."}]},{"pattern":"～とすれば","meaning":"Used to express 'if it were the case that...', 'if we assume that...'.","meaningId":"Digunakan untuk menyatakan 'seandainya saja...', 'jika kita berasumsi bahwa...'.","formation":"Verb-casual + とすれば / い-Adjective + とすれば / な-Adjective + だとすれば / Noun + だとすれば","formationId":"Kata Kerja-kasual + とすれば / い-Kata Sifat + とすれば / な-Kata Sifat + だとすれば / Kata Benda + だとすれば","examples":[{"jp":"彼が嘘つきだとすれば、その話は信じられない。","romaji":"Kare ga usotsuki da to sureba, sono hanashi wa shinjirarenai.","en":"If he’s a liar, then his story can’t be believed.","id":"Jika dia pembohong, ceritanya tidak bisa dipercaya."},{"jp":"あなたが一緒に行くとすれば、私も行きます。","romaji":"Anata ga issho ni iku to sureba, watashi mo ikimasu.","en":"If you are going, I'll go too.","id":"Jika kamu pergi, aku juga akan pergi."},{"jp":"彼が浮気しているとすれば、どうすればいい？","romaji":"Kare ga uwaki shite iru to sureba, dou sureba ii?","en":"If he’s cheating, what should I do?","id":"Jika dia selingkuh, apa yang harus saya lakukan?"},{"jp":"その薬が効かないとすれば、他の方法を試すべきだ。","romaji":"Sono kusuri ga kikanai to sureba, hoka no houhou o tamesu beki da.","en":"If that medicine doesn’t work, we should try something else.","id":"Jika obat itu tidak berhasil, kita harus mencoba obat lain."}]},{"pattern":"～となったら (〜to nattara)","meaning":"Used to express 'if it comes to...', 'when it becomes the case that...'.","meaningId":"Digunakan untuk menyatakan 'jika menyangkut...', 'ketika menjadi hal...'.","formation":"Verb-casual + となったら / Noun + となったら","formationId":"Kata Kerja-kasual + となったら / Kata Benda + となったら","examples":[{"jp":"旅行に行くとなったら、荷造りをしなければいけません。","romaji":"Ryokou ni iku to nattara, nizukuri o shinakereba ikemasen.","en":"If it comes to going on a trip, we have to pack.","id":"Jika ingin bepergian, kita harus berkemas."},{"jp":"試験に落ちるとなったら、どうしよう。","romaji":"Shiken ni ochiru to nattara, dou shiyou.","en":"What should I do if I fail the exam?","id":"Apa yang harus saya lakukan jika saya gagal dalam ujian?"},{"jp":"彼女と別れるとなったら、とても悲しいです。","romaji":"Kanojo to wakareru to nattara, totemo kanashii desu.","en":"If it comes to breaking up with her, I’ll be very sad.","id":"Jika harus putus dengannya, saya akan sangat sedih."},{"jp":"結婚するとなったら、人生が大きく変わるでしょう。","romaji":"Kekkon suru to nattara, jinsei ga ookiku kawaru deshou.","en":"When it comes to getting married, life will probably change drastically.","id":"Ketika menikah, hidup mungkin akan berubah drastis."}]},{"pattern":"～となると (〜to naru to)","meaning":"Used to highlight a certain circumstance; 'when it comes to...', 'if it becomes...', 'in the event that...'.","meaningId":"Digunakan untuk menyoroti keadaan tertentu; 'jika sampai...', 'jika menjadi...', 'seandainya...'.","formation":"Verb-casual + となると / い-Adjective + となると / な-Adjective + だとなると / Noun + だとなると","formationId":"Kata Kerja-kasual + となると / い-Kata Sifat + となると / な-Kata Sifat + だとなると / Kata Benda + だとなると","examples":[{"jp":"試験となると、多くの学生が緊張する。","romaji":"Shiken to naru to, ooku no gakusei ga kinchou suru.","en":"When it comes to exams, many students get nervous.","id":"Saat menghadapi ujian, banyak siswa yang merasa gugup."},{"jp":"東京へ引っ越すとなると、生活費が一気に上がる。","romaji":"Toukyou e hikkosu to naru to, seikatsuhi ga ikki ni agaru.","en":"If you move to Tokyo, the cost of living goes up drastically.","id":"Jika Anda pindah ke Tokyo, biaya hidup naik drastis."},{"jp":"締め切りが明日となると、今夜は徹夜になりそうだ。","romaji":"Shimekiri ga ashita to naru to, konya wa tetsuya ni narisou da.","en":"If the deadline is tomorrow, I’ll probably be up all night.","id":"Jika tenggat waktunya besok, saya mungkin akan terjaga sepanjang malam."},{"jp":"彼がリーダーとなると、チームの活動は大きく改善されるかもしれない。","romaji":"Kare ga riidaa to naru to, chiimu no katsudou wa ookiku kaizen sareru kamoshirenai.","en":"If he becomes the leader, the team’s activities might improve significantly.","id":"Jika dia menjadi pemimpin, aktivitas tim mungkin akan meningkat secara signifikan."}]},{"pattern":"～となれば (〜to nareba)","meaning":"Expresses the idea of 'if it comes to...; when we talk about...; in the case of...'.","meaningId":"Mengekspresikan gagasan 'jika menyangkut...; ketika kita berbicara tentang...; dalam kasus...'.","formation":"Verb-casual + となれば, い-Adjective + となれば, な-Adjective + だとなれば, Noun + だとなれば","formationId":"Kata Kerja-kasual + となれば, い-Kata Sifat + となれば, な-Kata Sifat + だとなれば, Kata Benda + だとなれば","examples":[{"jp":"彼がリーダーとなれば、プロジェクトは成功するでしょう。","romaji":"Kare ga riidaa to nareba, purojekuto wa seikou suru deshou.","en":"If he becomes the leader, the project will probably succeed.","id":"Jika dia menjadi pemimpin, proyek tersebut mungkin akan berhasil."},{"jp":"明日が雨だとなれば、ピクニックをキャンセルしましょう。","romaji":"Ashita ga ame da to nareba, pikunikku wo kyanseru shimashou.","en":"If it turns out to be raining tomorrow, let's cancel the picnic.","id":"Kalau ternyata besok hujan, ayo batalkan pikniknya."},{"jp":"この仕事が終わったとなれば、休暇を取ることができます。","romaji":"Kono shigoto ga owatta to nareba, kyuuka wo toru koto ga dekimasu.","en":"If this job is over, you can take a vacation.","id":"Jika pekerjaan ini selesai, Anda bisa berlibur."},{"jp":"そのテストが難しいとなれば、より一層勉強しなければならない。","romaji":"Sono tesuto ga muzukashii to nareba, yori issou benkyou shinakereba naranai.","en":"If that test is difficult, we must study all the more.","id":"Jika ujian itu sulit, kita harus belajar lebih banyak lagi."}]},{"pattern":"～とのことだ (〜to no koto da)","meaning":"Expresses something that the speaker heard; 'I've heard that', 'I was told that'.","meaningId":"Mengungkapkan sesuatu yang didengar pembicara; 'Saya pernah mendengarnya', 'Saya diberitahu itu'.","formation":"Simplified phrase + とのことだ","formationId":"Frasa sederhana + とのことだ","examples":[{"jp":"週末にパーティーがあるとのことだ。","romaji":"Shuumatsu ni paatii ga aru to no koto da.","en":"I've heard that there is a party this weekend.","id":"Kudengar ada pesta akhir pekan ini."},{"jp":"彼は来年ロンドンに引っ越すとのことだ。","romaji":"Kare wa rainen Rondon ni hikkosu to no koto da.","en":"I was told that he is moving to London next year.","id":"Saya diberitahu bahwa dia akan pindah ke London tahun depan."},{"jp":"彼女は新しい仕事についたとのことだ。","romaji":"Kanojo wa atarashii shigoto ni tsuita to no koto da.","en":"I've heard that she has gotten a new job.","id":"Saya pernah mendengar bahwa dia mendapat pekerjaan baru."},{"jp":"明日は試験がないとのことだ。","romaji":"Ashita wa shiken ga nai to no koto da.","en":"I was told that there is no exam tomorrow.","id":"Saya diberitahu bahwa tidak ada ujian besok."}]},{"pattern":"～とはいえ","meaning":"Even though; although; but","meaningId":"Meskipun; meskipun; Tetapi","formation":"Noun + とはいえ, な-Adjective + だとはいえ, い-Adjective + とはいえ, Verb-casual + とはいえ","formationId":"Kata Benda + とはいえ, な-Kata Sifat + だとはいえ, い-Kata Sifat + とはいえ, Kata Kerja-kasual + とはいえ","examples":[{"jp":"彼は頭が良いとはいえ、少し怠け者だ。","romaji":"Kare wa atama ga yoi to wa ie, sukoshi namakemono da.","en":"Although he is smart, he is a bit lazy.","id":"Meskipun dia pintar, dia agak malas."},{"jp":"このレストランは美味しいとはいえ、ちょっと高い。","romaji":"Kono resutoran wa oishii to wa ie, chotto takai.","en":"While this restaurant is delicious, it's a bit expensive.","id":"Meskipun restoran ini enak, harganya agak mahal."},{"jp":"日本は小さい国だとはいえ、技術は世界一だ。","romaji":"Nihon wa chiisai kuni da to wa ie, gijutsu wa sekaiichi da.","en":"Even though Japan is a small country, its technology is among the best in the world.","id":"Meskipun Jepang adalah negara kecil, namun teknologinya termasuk yang terbaik di dunia."},{"jp":"彼女は若いとはいえ、経験豊富だ。","romaji":"Kanojo wa wakai to wa ie, keiken houfu da.","en":"Even though she is young, she is very experienced.","id":"Meskipun dia masih muda, dia sangat berpengalaman."}]},{"pattern":"～とみえて (〜to miete)","meaning":"It seems that; apparently","meaningId":"Tampaknya; tampaknya","formation":"Verb-casual + とみえて, い-Adjective + とみえて, な-Adjective + だとみえて, Noun + だとみえて","formationId":"Kata Kerja-kasual + とみえて, い-Kata Sifat + とみえて, な-Kata Sifat + だとみえて, Kata Benda + だとみえて","examples":[{"jp":"彼は運動が得意とみえて、毎日ジムに行っています。","romaji":"Kare wa undou ga tokui to miete, mainichi jimu ni itteimasu.","en":"He seems to be good at exercise, as he goes to the gym every day.","id":"Dia tampaknya pandai berolahraga, karena dia pergi ke gym setiap hari."},{"jp":"彼女は忙しいとみえて、なかなか会えない。","romaji":"Kanojo wa isogashii to miete, nakanaka aenai.","en":"She seems to be busy, as it's hard to meet her.","id":"Dia sepertinya sibuk, karena sulit untuk bertemu dengannya."},{"jp":"田中さんは疲れているとみえて、早く帰りました。","romaji":"Tanaka-san wa tsukarete iru to miete, hayaku kaerimashita.","en":"It seems that Tanaka-san was tired, as he went home early.","id":"Sepertinya Tanaka-san lelah, karena dia pulang lebih awal."},{"jp":"その店は人気だとみえて、いつも行列ができている。","romaji":"Sono mise wa ninki da to miete, itsumo retsu ga dekite iru.","en":"That shop seems to be popular, as there is always a line.","id":"Toko itu sepertinya populer, karena selalu ada antrean."}]},{"pattern":"～とみられる","meaning":"It is considered that; It is thought that; It is believed that","meaningId":"Hal ini dianggap bahwa; Diperkirakan bahwa; Hal ini diyakini bahwa","formation":"Verb-casual + とみられる, Noun + とみられる","formationId":"Kata Kerja-kasual + とみられる, Kata Benda + とみられる","examples":[{"jp":"彼の行動は無責任とみられる。","romaji":"Kare no koudou wa musekinin to mirareru.","en":"His behavior is considered irresponsible.","id":"Perilakunya dianggap tidak bertanggung jawab."},{"jp":"この絵はピカソの作品とみられている。","romaji":"Kono e wa pikaso no sakuhin to mirareteiru.","en":"This painting is believed to be a work of Picasso.","id":"Lukisan ini diyakini merupakan karya Picasso."},{"jp":"地震の後、被害はさらに増加するとみられる。","romaji":"Jishin no ato, higai wa sara ni zouka suru to mirareru.","en":"After the earthquake, damage is expected to increase further.","id":"Pasca gempa, kerusakan diperkirakan akan semakin meningkat."},{"jp":"週末は天気が良くなるとみられる。","romaji":"Shuumatsu wa tenki ga yoku naru to mirareru.","en":"The weather is expected to improve on the weekend.","id":"Cuaca diperkirakan membaik pada akhir pekan ini."}]},{"pattern":"～とみると (〜to miru to)","meaning":"Expresses the concept of 'when one sees it as', 'viewed as', or 'considering'.","meaningId":"Mengungkapkan konsep 'ketika seseorang melihatnya sebagai', 'dilihat sebagai', atau 'mempertimbangkan'.","formation":"Verb-casual + とみると, い-Adjective + とみると, な-Adjective + だとみると, Noun + だとみると","formationId":"Kata Kerja-kasual + とみると, い-Kata Sifat + とみると, な-Kata Sifat + だとみると, Kata Benda + だとみると","examples":[{"jp":"この問題を数学の視点でとみると、解決策が見えてきます。","romaji":"Kono mondai o suugaku no shiten de to miru to, kaiketsusaku ga miete kimasu.","en":"When one sees this problem from a mathematical perspective, a solution begins to emerge.","id":"Ketika seseorang melihat masalah ini dari sudut pandang matematika, solusi mulai muncul."},{"jp":"彼女が優秀な学生だとみると、その賞をもらったのは当然です。","romaji":"Kanojo ga yuushuuna gakusei da to miru to, sono shou o moratta no wa touzen desu.","en":"Considering she is an excellent student, it's natural that she received that award.","id":"Mengingat dia adalah murid yang berprestasi, wajar jika dia menerima penghargaan itu."},{"jp":"彼が新入社員だとみると、その成果は素晴らしいです。","romaji":"Kare ga shinnyuushain da to miru to, sono seika wa subarashii desu.","en":"Viewing him as a new employee, his achievements are exceptional.","id":"Dilihat sebagai karyawan baru, prestasinya luar biasa."},{"jp":"このパンダが絶滅危惧種だとみると、保護が必要です。","romaji":"Kono panda ga zetsumetsu kigushu da to miru to, hogo ga hitsuyou desu.","en":"Considering this panda is an endangered species, it needs protection.","id":"Mengingat panda ini termasuk spesies yang terancam punah, maka perlu dilindungi."}]},{"pattern":"どんなに～うが","meaning":"Expresses 'no matter how much...', 'even if...'.","meaningId":"Menyatakan 'tidak peduli berapa banyak...', 'sekalipun...'.","formation":"どんなに + Verb-volitional + うが, どんなに + い-Adjective(～かろう) + が, どんなに + な-Adjective + だろうが","formationId":"どんなに + Verba-volitional + うが, どんなに + い-Adjective(～かろう) + が, どんなに + な-Adjective + だろうが","examples":[{"jp":"どんなに頑張ろうが、彼の速さには追いつけない。","romaji":"Donna ni ganbarou ga, kare no hayasa ni wa oitsukenai.","en":"No matter how hard I try, I can't catch up with his speed.","id":"Tidak peduli seberapa keras saya mencoba, saya tidak dapat mengejar kecepatannya."},{"jp":"どんなに食べようが、彼女は太らない。","romaji":"Donna ni tabeyou ga, kanojo wa futoranai.","en":"No matter how much she eats, she doesn't gain weight.","id":"Tidak peduli berapa banyak dia makan, berat badannya tidak bertambah."},{"jp":"どんなに寒かろうが、彼は毎日ジョギングをします。","romaji":"Donna ni samukarou ga, kare wa mainichi jogging wo shimasu.","en":"No matter how cold it is, he goes jogging every day.","id":"Tidak peduli betapa dinginnya cuaca, dia tetap jogging setiap hari."},{"jp":"どんなに暑かろうが、エアコンは使いません。","romaji":"Donna ni atsukarou ga, eakon wa tsukaimasen.","en":"No matter how hot it is, I don't use air conditioning.","id":"Betapapun panasnya, saya tidak menggunakan AC."}]},{"pattern":"～と言わんばかりに (〜to iwan bakari ni)","meaning":"Indicates an action or behavior that strongly implies a certain unspoken message or feeling.","meaningId":"Menunjukkan tindakan atau perilaku yang secara kuat menyiratkan pesan atau perasaan tertentu yang tidak terucapkan.","formation":"Verb-volitional + と言わんばかりに, い-Adjective + と言わんばかりに, な-Adjective + だと言わんばかりに, Noun + だと言わんばかりに","formationId":"Verba-volisi + と言わんばかりに, い-Kata Sifat + と言わんばかりに, な-Kata Sifat + だと言わんばかりに, Kata Benda +だと言わんばかりに","examples":[{"jp":"彼女は優勝したと言わんばかりに笑った。","romaji":"Kanojo wa yuushou shita to iwan bakari ni waratta.","en":"She laughed as if to say she won.","id":"Dia tertawa seolah mengatakan dia menang."},{"jp":"彼は倒れると言わんばかりの疲労感があった。","romaji":"Kare wa taoreru to iwan bakari no hiroukan ga atta.","en":"He was so fatigued it was as if he might collapse.","id":"Dia sangat lelah seolah-olah dia akan pingsan."},{"jp":"彼女は雨の日を恐れていて、晴れてほしいと言わんばかりに窓の外を見つめていた。","romaji":"Kanojo wa ame no hi o osorete ite, harete hoshii to iwan bakari ni mado no soto o mitsumete ita.","en":"She was afraid of rainy days, almost as if to say she wanted it to be sunny, as she gazed out the window.","id":"Dia takut pada hari hujan, seolah-olah mengatakan dia ingin hari cerah, sambil menatap ke luar jendela."},{"jp":"彼の行動は、誰にも信じてもらえないと言わんばかりだった。","romaji":"Kare no koudou wa, dare ni mo shinjite moraenai to iwan bakari datta.","en":"His behavior was as if to say that no one would believe him.","id":"Perilakunya seolah mengatakan bahwa tidak ada yang akan mempercayainya."}]},{"pattern":"～と言わんばかりの Noun","meaning":"Expresses the concept of 'as if to say'; 'almost says'; 'suggests'.","meaningId":"Mengekspresikan konsep 'seolah-olah mengatakan'; 'hampir berkata'; 'menyarankan'.","formation":"Verb-plain form + と言わんばかりの Noun","formationId":"Bentuk kata kerja-biasa + と言わんばかりの Kata benda","examples":[{"jp":"田中さんは嬉しくて飛び上がると言わんばかりの笑顔を見せた。","romaji":"Tanaka-san wa ureshikute tobiagaru to iwan bakari no egao wo miseta.","en":"Tanaka showed a smile as if to say he was so happy he could jump for joy.","id":"Tanaka menunjukkan senyuman seolah mengatakan dia sangat bahagia hingga bisa melompat kegirangan."},{"jp":"彼女は僕に話しかけると言わんばかりの視線を送った。","romaji":"Kanojo wa boku ni hanashikakeru to iwan bakari no shisen wo okutta.","en":"She sent me glances as if to say she wanted to speak with me.","id":"Dia melirikku seolah mengatakan dia ingin berbicara denganku."},{"jp":"その老人は寒さで震えていると言わんばかりの姿を見せていた。","romaji":"Sono roujin wa samusa de furueteiru to iwan bakari no sugata wo miseteita.","en":"The old man was shivering as if to say he was freezing from the cold.","id":"Lelaki tua itu menggigil seolah mengatakan dia kedinginan karena kedinginan."},{"jp":"彼の体は緊張で固まっていると言わんばかりの風格を放っている。","romaji":"Kare no karada wa kinchou de katamatteiru to iwan bakari no fuukaku wo hanatteiru.","en":"He exudes an air as if his body were stiff from tension.","id":"Dia memancarkan udara seolah tubuhnya kaku karena ketegangan."}]},{"pattern":"～ながらに","meaning":"Expresses a state or condition continuing just as it is (e.g. 'from birth', 'while crying', 'in the old way').","meaningId":"Mengekspresikan keadaan atau kondisi yang terus berlanjut (misalnya 'sejak lahir', 'sambil menangis', 'dengan cara lama').","formation":"Common set phrases: 生まれながらに, 涙ながらに, 昔ながらに, 子供ながらに, etc.","formationId":"Kumpulan frasa umum: 生まれながらに, 涙ながらに, 昔ながらに, 子供ながらに, dll.","examples":[{"jp":"彼女は生まれながらにして優れた音感を持っている。","romaji":"Kanojo wa umare nagara ni shite sugureta onkan o motte iru.","en":"She has had an excellent sense of pitch from birth.","id":"Dia memiliki kepekaan nada yang luar biasa sejak lahir."},{"jp":"彼は子供ながらに大人の会話を理解していた。","romaji":"Kare wa kodomo nagara ni otona no kaiwa o rikaishite ita.","en":"Even though he was just a child, he understood adult conversations.","id":"Meskipun dia masih anak-anak, dia memahami percakapan orang dewasa."},{"jp":"彼女は涙ながらに真実を訴えた。","romaji":"Kanojo wa namida nagara ni shinjitsu o uttaeta.","en":"She pleaded the truth while in tears.","id":"Dia memohon kebenaran sambil menangis."},{"jp":"私たちは昔ながらに伝わる祭りを大切にしている。","romaji":"Watashi-tachi wa mukashi nagara ni tsutawaru matsuri o taisetsu ni shite iru.","en":"We cherish the traditional festival that has been passed down unchanged from old times.","id":"Kami menghargai festival tradisional yang telah diwariskan secara turun-temurun sejak dahulu kala."}]},{"pattern":"～ながらの Noun (〜nagara no Noun)","meaning":"Indicates one action or state happening at the same time as the noun in question (e.g. 'dinner while watching TV').","meaningId":"Menunjukkan satu tindakan atau keadaan yang terjadi bersamaan dengan kata benda yang dimaksud (misalnya 'makan malam sambil menonton TV').","formation":"Verb-ますstem (or plain minus る) + ながら + の + Noun","formationId":"Kata Kerja-ますbatang (atau biasa dikurangi る) + ながら + の + Kata Benda","examples":[{"jp":"テレビを見ながらの夕食は、子供たちにとって楽しいだろう。","romaji":"Terebi o mi-nagara no yuushoku wa, kodomotachi ni totte tanoshii darou.","en":"Eating dinner while watching TV might be fun for the children.","id":"Makan malam sambil menonton TV mungkin menjadi hal yang menyenangkan bagi anak."},{"jp":"地図を読みながらの運転は危険です。","romaji":"Chizu o yomi-nagara no unten wa kiken desu.","en":"Driving while reading a map is dangerous.","id":"Mengemudi sambil membaca peta itu berbahaya."},{"jp":"散歩しながらの会話はリラックスできます。","romaji":"Sanpo shi-nagara no kaiwa wa rirakkusu dekimasu.","en":"Talking during a walk can be relaxing.","id":"Berbicara sambil berjalan-jalan memang bisa membuat rileks."},{"jp":"音楽を聴きながらの勉強は集中力を高めるかもしれません。","romaji":"Ongaku o kiki-nagara no benkyou wa shuuchuuryoku o takameru kamoshiremasen.","en":"Studying while listening to music might improve concentration.","id":"Belajar sambil mendengarkan musik dapat meningkatkan konsentrasi."}]},{"pattern":"～ながらも (〜nagara mo)","meaning":"Means 'even though' or 'despite'.","meaningId":"Berarti 'walaupun' atau 'walaupun'.","formation":"Verb stem + ながらも, い-Adjective + ながらも, な-Adjective/Noun + ながらも","formationId":"Batang kata kerja + ながらも, い-Kata Sifat + ながらも, な-Kata Sifat/Kata Benda + ながらも","examples":[{"jp":"彼は貧しいながらも、幸せな生活を送っている。","romaji":"Kare wa mazushii nagara mo, shiawase na seikatsu o okutte iru.","en":"Despite being poor, he leads a happy life.","id":"Meskipun miskin, ia menjalani kehidupan yang bahagia."},{"jp":"僕は忙しいながらも、毎日運動しています。","romaji":"Boku wa isogashii nagara mo, mainichi undou shiteimasu.","en":"Even though I am busy, I exercise every day.","id":"Meskipun saya sibuk, saya berolahraga setiap hari."},{"jp":"病気ながらも、彼は仕事を続けました。","romaji":"Byouki nagara mo, kare wa shigoto o tsuzukemashita.","en":"Despite being sick, he continued working.","id":"Meski sakit, ia tetap bekerja."},{"jp":"雨が降っているながらも、彼は散歩に出かけた。","romaji":"Ame ga futte iru nagara mo, kare wa sanpo ni dekaketa.","en":"Even though it was raining, he went for a walk.","id":"Meski hujan, dia tetap berjalan-jalan."}]},{"pattern":"～なくはない (〜naku wa nai)","meaning":"Expresses the idea 'it's not that it's impossible' or 'it's not that I can't'.","meaningId":"Mengungkapkan gagasan 'bukannya tidak mungkin' atau 'bukannya saya tidak bisa'.","formation":"Verb-ないform + なくはない, い-Adjective－い + くはない, な-Adjective + ではなくはない, Noun + ではなくはない","formationId":"Kata Kerja-ないbentuk + なくはない, い-Kata Sifat－い + くはない, な-Kata Sifat + ではなくはない, Kata Benda + ではなくはない","examples":[{"jp":"それを終えるのは難しくなくはない。","romaji":"Sore o oeru no wa muzukashiku naku wa nai.","en":"It's not that it's impossible to finish it.","id":"Bukan berarti tidak mungkin untuk menyelesaikannya."},{"jp":"彼に話すのは怖くなくはない。","romaji":"Kare ni hanasu no wa kowaku naku wa nai.","en":"It's not that I'm entirely unafraid to talk to him.","id":"Bukannya aku tidak takut untuk berbicara dengannya."},{"jp":"映画を見に行く時間がなくはない。","romaji":"Eiga o mi ni iku jikan ga naku wa nai.","en":"It's not that I don't have time to go see a movie.","id":"Bukannya saya tidak punya waktu untuk menonton film."},{"jp":"日本語で講演するのは難しくなくはない。","romaji":"Nihongo de kouen suru no wa muzukashiku naku wa nai.","en":"It's not impossible to give a lecture in Japanese, but it won't be easy.","id":"Memberikan ceramah dalam bahasa Jepang bukan tidak mungkin, namun tidak mudah."}]},{"pattern":"～なくもない (〜naku mo nai)","meaning":"Expresses 'not impossible' or 'might as well'.","meaningId":"Menyatakan 'bukan tidak mungkin' atau 'mungkin juga'.","formation":"Verb-ないform + なくもない, い-Adjective－い + くもない, な-Adjective + でもない, Noun + でもない","formationId":"Kata kerja-ないbentuk + なくもない, い-Kata Sifat－い + くもない, な-Kata Sifat + でもない, Kata Benda + でもない","examples":[{"jp":"彼がもうすぐ戻るなら、待つなくもない。","romaji":"Kare ga mou sugu modoru nara, matsu naku mo nai.","en":"If he’s coming back soon, waiting wouldn’t be a bad idea.","id":"Jika dia segera kembali, menunggu bukanlah ide yang buruk."},{"jp":"この本が役に立つなら、買うなくもない。","romaji":"Kono hon ga yaku ni tatsu nara, kau naku mo nai.","en":"If this book is useful, it might not be a bad idea to buy it.","id":"Jika buku ini bermanfaat, mungkin bukan ide buruk untuk membelinya."},{"jp":"天気が良ければ、ピクニックに行くなくもない。","romaji":"Tenki ga yokereba, pikunikku ni iku naku mo nai.","en":"If the weather is nice, it wouldn't be impossible for us to go on a picnic.","id":"Jika cuacanya bagus, bukan tidak mungkin kita bisa piknik."},{"jp":"そのプロジェクトが成功すれば、プロモーションもあり得なくもない。","romaji":"Sono purojekuto ga seikou sureba, puromooshon mo arienaku mo nai.","en":"If that project succeeds, a promotion might not be out of the question.","id":"Jika proyek itu berhasil, promosi mungkin tidak mungkin dilakukan."}]},{"pattern":"～なら～なりに","meaning":"Means 'if it is X, then it's X in its own way', emphasizing unique qualities.","meaningId":"Berarti 'jika itu X, maka itu X dengan caranya sendiri', menekankan kualitas unik.","formation":"Noun/Adjective + なら + (same Noun/Adjective) + なりに","formationId":"Kata Benda/Kata Sifat + なら + (Kata Benda/Kata Sifat yang sama) + なりに","examples":[{"jp":"彼はまだ初心者なら初心者なりに頑張っている。","romaji":"Kare wa mada shoshinsha nara shoshinsha nari ni ganbatteiru.","en":"Since he’s still a beginner, he’s doing his best in his own beginner way.","id":"Karena dia masih pemula, dia melakukan yang terbaik dengan cara pemulanya sendiri."},{"jp":"この料理は辛いなら辛いなりに美味しい。","romaji":"Kono ryouri wa karai nara karai nari ni oishii.","en":"If this dish is spicy, it’s delicious in its own spicy way.","id":"Kalau masakan ini pedas, enak dengan cara pedasnya sendiri."},{"jp":"あの人は変なら変なりに面白い。","romaji":"Ano hito wa hen nara hen nari ni omoshiroi.","en":"If that person is strange, they’re interesting in their own strange way.","id":"Jika orang itu aneh, berarti dia menarik dengan caranya sendiri yang aneh."},{"jp":"この町は小さいなら小さいなりに楽しい。","romaji":"Kono machi wa chiisai nara chiisai nari ni tanoshii.","en":"If this town is small, it’s fun in its own small way.","id":"Jika kota ini kecil, kota ini menyenangkan dengan caranya yang kecil."}]},{"pattern":"～には及ばない (〜ni wa oyobanai)","meaning":"Means 'no need to go that far' or 'not necessary'.","meaningId":"Berarti 'tidak perlu sejauh itu' atau 'tidak perlu'.","formation":"Verb-dictionary form + には及ばない","formationId":"Bentuk kamus kata kerja + には及ばない","examples":[{"jp":"ファーストクラスに乗るには及ばない、エコノミーでも十分だ。","romaji":"Faasuto kurasu ni noru ni wa oyobanai, ekonomii demo juubun da.","en":"There’s no need to go as far as flying first class; economy is enough.","id":"Tidak perlu terbang sejauh penerbangan kelas satu; perekonomian sudah cukup."},{"jp":"毎回会うたびにギフトを持って行くには及ばない。","romaji":"Maikai au tabi ni gifuto o motte iku ni wa oyobanai.","en":"There’s no need to bring a gift every time you meet her.","id":"Tidak perlu membawa hadiah setiap kali bertemu dengannya."},{"jp":"その問題は先生に聞くには及ばない、自分で解決できる。","romaji":"Sono mondai wa sensei ni kiku ni wa oyobanai, jibun de kaiketsu dekiru.","en":"That issue doesn’t warrant asking the teacher; you can solve it yourself.","id":"Masalah itu tidak perlu ditanyakan kepada guru; Anda bisa menyelesaikannya sendiri."},{"jp":"小さな失敗のために、あんなに辛辣な言葉を使うには及ばないだろう。","romaji":"Chiisana shippai no tame ni, anna ni shinratsu na kotoba o tsukau ni wa oyobanai darou.","en":"For such a small mistake, there’s no need to use such harsh words.","id":"Untuk kesalahan sekecil itu, tidak perlu menggunakan kata-kata kasar seperti itu."}]},{"pattern":"～に堪えない","meaning":"Indicates something is unbearable or not worth doing (e.g., 'unbearable to watch', 'unbearable to listen to').","meaningId":"Menunjukkan sesuatu yang tidak tertahankan atau tidak layak untuk dilakukan (misalnya, 'tak tertahankan untuk ditonton', 'tak tertahankan untuk didengarkan').","formation":"Verb-dictionary form + に堪えない, Noun + に堪えない","formationId":"Bentuk kamus kata kerja + に堪えない, Kata Benda + に堪えない","examples":[{"jp":"彼の冗談は聞くに堪えない。","romaji":"Kare no joudan wa kiku ni taenai.","en":"His jokes are unbearable to listen to.","id":"Leluconnya tidak tertahankan untuk didengarkan."},{"jp":"その映画は見るに堪えないほどひどい出来だ。","romaji":"Sono eiga wa miru ni taenai hodo hidoi deki da.","en":"That movie is so bad that it’s unbearable to watch.","id":"Film itu sangat buruk sehingga tak tertahankan untuk ditonton."},{"jp":"この小説は読むに堪えないほど退屈だ。","romaji":"Kono shousetsu wa yomu ni taenai hodo taikutsu da.","en":"This novel is so boring that it’s unbearable to read.","id":"Novel ini sangat membosankan sehingga tak tertahankan untuk dibaca."},{"jp":"彼の行動は見るに堪えない。","romaji":"Kare no koudou wa miru ni taenai.","en":"His behavior is unbearable to watch.","id":"Perilakunya tak tertahankan untuk dilihat."}]},{"pattern":"～に堪える","meaning":"Used to say that something is 'worth doing' or 'can stand up to' something (the positive counterpart of ～に堪えない).","meaningId":"Digunakan untuk mengatakan bahwa sesuatu itu 'layak dilakukan' atau 'bisa bertahan terhadap' sesuatu (padanan positif dari ～に堪えない).","formation":"Verb-dictionary form + に堪える, Noun + に堪える","formationId":"Bentuk kamus kata kerja + に堪える, Kata Benda + に堪える","examples":[{"jp":"彼の歌声は聞くに堪える。","romaji":"Kare no utagoe wa kiku ni taeru.","en":"His singing voice is worth listening to.","id":"Suara nyanyiannya layak untuk didengarkan."},{"jp":"この小説は読むに堪える内容だ。","romaji":"Kono shousetsu wa yomu ni taeru naiyou da.","en":"This novel is worth reading.","id":"Novel ini layak untuk dibaca."},{"jp":"あの映画は見るに堪える名作だ。","romaji":"Ano eiga wa miru ni taeru meisaku da.","en":"That movie is a masterpiece worth watching.","id":"Film itu adalah mahakarya yang layak untuk ditonton."},{"jp":"彼の意見は十分に参考に堪える。","romaji":"Kare no iken wa juubun ni sankou ni taeru.","en":"His opinion is definitely worth considering.","id":"Pendapatnya tentu patut dipertimbangkan."}]},{"pattern":"～に耐える","meaning":"To endure or withstand something; 'endure', 'withstand', 'tolerate'.","meaningId":"Untuk menanggung atau menahan sesuatu; 'bertahan', 'menahan', 'mentolerir'.","formation":"Noun + に耐える","formationId":"Kata benda + に耐える","examples":[{"jp":"彼は厳しい修行に耐えた。","romaji":"Kare wa kibishii shugyou ni taeta.","en":"He endured the harsh training.","id":"Dia menjalani pelatihan yang keras."},{"jp":"この橋は強風に耐えられる。","romaji":"Kono hashi wa kyoufuu ni taerareru.","en":"This bridge can withstand strong winds.","id":"Jembatan ini mampu menahan angin kencang."},{"jp":"彼女は苦しみに耐えた。","romaji":"Kanojo wa kurushimi ni taeta.","en":"She endured the pain.","id":"Dia menahan rasa sakitnya."},{"jp":"この建物は地震に耐えることができます。","romaji":"Kono tatemono wa jishin ni taeru koto ga dekimasu.","en":"This building can withstand an earthquake.","id":"Bangunan ini mampu menahan gempa."}]},{"pattern":"～に至った (〜ni itatta)","meaning":"Expresses the outcome or final conclusion of a process; 'reached the point', 'led to'.","meaningId":"Mengekspresikan hasil atau kesimpulan akhir dari suatu proses; 'mencapai titik', 'mengarah ke'.","formation":"Verb-てform + に至った or Noun / Verb-dictionary + に至る (more general).","formationId":"Kata kerja-てbentuk + に至った atau Kata Benda / Kamus Kata Kerja + に至る (lebih umum).","examples":[{"jp":"彼は練習を重ねて、ついにプロのギタリストに至った。","romaji":"Kare wa renshuu o kasanete, tsui ni puro no gitarisuto ni itatta.","en":"After repeated practice, he finally became a professional guitarist.","id":"Setelah berulang kali berlatih, akhirnya ia menjadi gitaris profesional."},{"jp":"調査を進めるうちに、驚くべき結論に至った。","romaji":"Chousa o susumeru uchi ni, odoroku beki ketsuron ni itatta.","en":"As the investigation progressed, it led to a surprising conclusion.","id":"Saat penyelidikan berlangsung, hal itu menghasilkan kesimpulan yang mengejutkan."},{"jp":"この問題はついに国際的な対立に至った。","romaji":"Kono mondai wa tsui ni kokusaiteki na tairitsu ni itatta.","en":"This issue finally led to an international conflict.","id":"Permasalahan ini akhirnya menimbulkan konflik internasional."},{"jp":"たくさんの失敗を経て、成功に至った。","romaji":"Takusan no shippai o hete, seikou ni itatta.","en":"After many failures, I finally achieved success.","id":"Setelah banyak kegagalan, akhirnya saya mencapai kesuksesan."}]},{"pattern":"～に越したことはない (〜ni koshita koto wa nai)","meaning":"Expresses that something is the best or most desirable course of action; 'nothing better than...'.","meaningId":"Menyatakan bahwa sesuatu adalah tindakan yang terbaik atau paling diinginkan; 'tidak ada yang lebih baik dari...'.","formation":"Verb (dictionary form) + に越したことはない, い-Adjective + に越したことはない, な-Adjective/Noun + である + に越したことはない","formationId":"Kata Kerja (bentuk kamus) + に越したことはない, い-Kata Sifat + に越したことはない, な-Kata Sifat/Kata Benda + である +に越したことはない","examples":[{"jp":"早く準備するに越したことはない。","romaji":"Hayaku junbi suru ni koshita koto wa nai.","en":"It's best to prepare early.","id":"Sebaiknya persiapkan sejak dini."},{"jp":"新鮮な食材を使うに越したことはない。","romaji":"Shinsen na shokuzai o tsukau ni koshita koto wa nai.","en":"There's nothing better than using fresh ingredients.","id":"Tidak ada yang lebih baik daripada menggunakan bahan-bahan segar."},{"jp":"安全運転に越したことはない。","romaji":"Anzen unten ni koshita koto wa nai.","en":"Safe driving is always best.","id":"Mengemudi yang aman selalu yang terbaik."},{"jp":"健康的な生活を送るに越したことはない。","romaji":"Kenkouteki na seikatsu o okuru ni koshita koto wa nai.","en":"There's nothing better than leading a healthy lifestyle.","id":"Tidak ada yang lebih baik daripada menjalani gaya hidup sehat."}]},{"pattern":"～に難くない","meaning":"Expresses 'not difficult to ~' in a formal/literary sense; e.g., 'not hard to imagine/understand'.","meaningId":"Mengungkapkan 'tidak sulit untuk ~' dalam pengertian formal/sastra; misalnya, 'tidak sulit untuk dibayangkan/dipahami'.","formation":"Verb-dictionary form + に難くない (commonly with 想像する, 理解する, 察する, etc.)","formationId":"Bentuk kamus kata kerja + に難くない (umumnya dengan 想像する, 理解する, 察する, dll.)","examples":[{"jp":"彼の喜びは想像に難くない。","romaji":"Kare no yorokobi wa souzou ni katakunai.","en":"It's not hard to imagine his delight.","id":"Tidak sulit membayangkan kegembiraannya."},{"jp":"この結果が彼女を失望させたことは理解に難くない。","romaji":"Kono kekka ga kanojo o shitsubou saseta koto wa rikai ni katakunai.","en":"It's not difficult to understand that this outcome disappointed her.","id":"Tidak sulit untuk memahami bahwa hasil ini mengecewakannya."},{"jp":"彼が怒る気持ちは察するに難くない。","romaji":"Kare ga okoru kimochi wa sassuru ni katakunai.","en":"It's not hard to guess why he is angry.","id":"Tidak sulit menebak mengapa dia marah."},{"jp":"このような状況が起こった理由は想像に難くない。","romaji":"Kono youna joukyou ga okotta riyuu wa souzou ni katakunai.","en":"It's not hard to imagine why this situation occurred.","id":"Tidak sulit membayangkan mengapa situasi ini terjadi."}]},{"pattern":"～のは Noun ぐらいのものだ (〜no wa Noun gurai no mono da)","meaning":"Conveys that 'only (Noun) is the case' or 'nothing but (Noun)'.","meaningId":"Menyampaikan bahwa 'hanya (Kata Benda) yang menjadi kasus' atau 'tidak lain hanyalah (Kata Benda)'.","formation":"Verb-casual + のは + Noun + ぐらいのものだ, い-Adjective + のは + Noun + ぐらいのものだ, etc.","formationId":"Kata kerja-kasual + のは + Kata Benda + ぐらいのものだ, い-Kata Sifat + のは + Kata Benda + ぐらいのものだ, dsb.","examples":[{"jp":"この小説を読むのは暇つぶしぐらいのものだ。","romaji":"Kono shousetsu o yomu no wa hima tsubushi gurai no mono da.","en":"Reading this novel is nothing but a way to kill time.","id":"Membaca novel ini tidak lain adalah cara untuk menghabiskan waktu."},{"jp":"今日の夕食で良かったのはピザぐらいのものだ。","romaji":"Kyou no yuushoku de yokatta no wa piza gurai no mono da.","en":"About the only good thing at tonight's dinner was the pizza.","id":"Satu-satunya hal yang baik pada makan malam malam ini adalah pizza."},{"jp":"この映画を見るのは時間の無駄ぐらいのものだ。","romaji":"Kono eiga o miru no wa jikan no muda gurai no mono da.","en":"Watching this movie is nothing but a waste of time.","id":"Menonton film ini hanya membuang-buang waktu saja."},{"jp":"彼と話すのはストレスぐらいのものだ。","romaji":"Kare to hanasu no wa sutoresu gurai no mono da.","en":"Talking to him is nothing but stressful.","id":"Berbicara dengannya hanyalah stres."}]},{"pattern":"～ば～ものを","meaning":"Expresses regret or a missed opportunity: 'if only', 'had I but...'.","meaningId":"Mengekspresikan penyesalan atau peluang yang terlewatkan: 'seandainya', 'seandainya saja...'.","formation":"Verb-ば + Verb-past + ものを, い-Adjective + ければ + ものを, な-Adjective/Noun + であれば + ものを, etc.","formationId":"Kata kerja-ば + Kata kerja-masa lalu + ものを, い-Kata Sifat + ければ + ものを, な-Kata Sifat/Kata Benda + であれば + ものを, dsb.","examples":[{"jp":"早く起きれば、遅刻しなかったものを。","romaji":"Hayaku okireba, chikoku shinakatta mono o.","en":"If only I'd woken up early, I wouldn't have been late.","id":"Kalau saja aku bangun pagi, aku tidak akan terlambat."},{"jp":"もっと頑張れば、テストに合格したものを。","romaji":"Motto ganbareba, tesuto ni goukaku shita mono o.","en":"If only I'd tried harder, I would have passed the test.","id":"Kalau saja saya berusaha lebih keras, saya pasti bisa lulus ujian itu."},{"jp":"お金があれば、新しい車を買ったものを。","romaji":"Okane ga areba, atarashii kuruma o katta mono o.","en":"If only I had the money, I would have bought a new car.","id":"Kalau saja saya punya uang, saya pasti sudah membeli mobil baru."},{"jp":"友達がいれば、一緒に遊んだものを。","romaji":"Tomodachi ga ireba, issho ni asonda mono o.","en":"If only I had a friend, I would have hung out together.","id":"Kalau saja aku punya teman, aku pasti sudah jalan-jalan bersama."}]},{"pattern":"～びた","meaning":"A suffix meaning “looking or seeming like ~” (often appears with nouns/adjectives).","meaningId":"Sufiks yang berarti “tampak atau tampak seperti ~” (sering muncul dengan kata benda/kata sifat).","formation":"[Noun/Adjective stem] + びた (forms a 連体形 modifier, e.g., 大人びた人 “an adult-like person”)","formationId":"[Kata Benda/Kata Sifat] + びた (membentuk pengubah 連体形, misalnya, 大人びた人 “orang seperti orang dewasa”)","examples":[{"jp":"大人びた考え方をする子供","romaji":"Otonabita kangaekata o suru kodomo","en":"A child who thinks in a very grown-up way","id":"Seorang anak yang berpikir dengan cara yang sangat dewasa"},{"jp":"古びたカバンを捨てられない。","romaji":"Furubita kaban o suterarenai.","en":"I can't throw away that old, worn-looking bag.","id":"Saya tidak bisa membuang tas tua yang tampak usang itu."},{"jp":"田舎びた雰囲気がこの町の魅力だ。","romaji":"Inakabita fun'iki ga kono machi no miryoku da.","en":"The countrified atmosphere is this town’s charm.","id":"Suasana pedesaan adalah daya tarik kota ini."},{"jp":"彼女は少し大人びた服装をしている。","romaji":"Kanojo wa sukoshi otonabita fukusou o shite iru.","en":"She’s dressed in a slightly grown-up style.","id":"Dia berpakaian dengan gaya yang sedikit dewasa."}]},{"pattern":"～びる (〜biru)","meaning":"A suffix meaning “to appear/to become ~,” often used with certain adjectives or nouns.","meaningId":"Sufiks yang berarti “muncul/menjadi ~”, sering digunakan dengan kata sifat atau kata benda tertentu.","formation":"Adjective/Noun + びる (to form a verb)","formationId":"Kata Sifat/Kata Benda + びる (untuk membentuk kata kerja)","examples":[{"jp":"彼女は年齢より大人びている。","romaji":"Kanojo wa nenrei yori otona bite iru.","en":"She seems older than her actual age.","id":"Dia tampak lebih tua dari usia sebenarnya."},{"jp":"この建物はすっかり古びている。","romaji":"Kono tatemono wa sukkari furubite iru.","en":"This building has become completely old and worn.","id":"Bangunan ini telah menjadi tua dan usang."},{"jp":"彼は都会育ちなのに、少し田舎びている話し方をする。","romaji":"Kare wa tokai sodachi na noni, sukoshi inakabite iru hanashikata o suru.","en":"Even though he grew up in the city, he speaks in a somewhat country-like way.","id":"Meskipun dia besar di kota, cara bicaranya agak mirip pedesaan."},{"jp":"子供が急に大人びる瞬間を見ると驚く。","romaji":"Kodomo ga kyuu ni otona biru shunkan o miru to odoroku.","en":"It’s surprising when you see a child suddenly act grown-up.","id":"Sungguh mengejutkan ketika melihat seorang anak tiba-tiba bertingkah dewasa."}]},{"pattern":"～ぶった","meaning":"Often appears as a past form of ～ぶる, meaning 'acted/pretended like ~' (or literally 'hit/bashed', depending on context).","meaningId":"Sering muncul sebagai bentuk lampau dari ～ぶる, yang berarti 'bertindak/berpura-pura seperti ~' (atau secara harafiah 'memukul/memukul', bergantung pada konteksnya).","formation":"Noun/Adjective + ぶる → ぶった (past tense), e.g., 偉そうぶった, 大人ぶった","formationId":"Kata Benda/Kata Sifat + ぶる → ぶった (past tense), misalnya, 偉そうぶった, 大人ぶった","examples":[{"jp":"彼は何でも知っているかのようにぶった態度を取る。","romaji":"Kare wa nandemo shitteiru ka no you ni butta taido o toru.","en":"He takes on an attitude as though he knows everything.","id":"Dia mengambil sikap seolah-olah dia tahu segalanya."},{"jp":"偉そうぶった物言いをされると、少し腹が立つ。","romaji":"Erasou butta monoii o sareru to, sukoshi hara ga tatsu.","en":"It irritates me when he speaks in such a high-and-mighty way.","id":"Aku kesal ketika dia berbicara dengan cara yang begitu tinggi dan perkasa."},{"jp":"彼女は大人ぶった口調で話しているが、実はまだ高校生だ。","romaji":"Kanojo wa otona butta kuchou de hanashite iru ga, jitsu wa mada koukousei da.","en":"She’s speaking in a very grown-up manner, but she’s actually still in high school.","id":"Dia berbicara dengan cara yang sangat dewasa, tapi sebenarnya dia masih duduk di bangku SMA."},{"jp":"いい子ぶった態度を取らなくてもいいよ。","romaji":"Ii ko butta taido o toranakute mo ii yo.","en":"You don't have to pretend to be such a goody-goody.","id":"Anda tidak perlu berpura-pura menjadi orang yang sok sok."}]},{"pattern":"～ぶって (〜butte)","meaning":"Te-form of ～ぶる, meaning 'acting/pretending to be ~'.","meaningId":"Bentuk Te dari ～ぶる, artinya 'bertindak/berpura-pura menjadi ~'.","formation":"Noun/Adjective + ぶる → ぶって (te-form)","formationId":"Kata Benda/Kata Sifat + ぶる → ぶって (te-form)","examples":[{"jp":"彼は何でも知ったかぶって話をする。","romaji":"Kare wa nandemo shittaka butte hanashi o suru.","en":"He talks as if he knows everything.","id":"Dia berbicara seolah-olah dia tahu segalanya."},{"jp":"彼女は何も知らないふりをしてぶっていたが、本当は全部わかっている。","romaji":"Kanojo wa nanimo shiranai furi o shite butte ita ga, hontou wa zenbu wakatte iru.","en":"She was acting like she didn’t know anything, but in reality, she understands it all.","id":"Dia bertingkah seolah dia tidak tahu apa-apa, tapi kenyataannya, dia mengerti semuanya."},{"jp":"彼はいつも偉そうぶって周りに指図している。","romaji":"Kare wa itsumo erasou butte mawari ni sashizu shite iru.","en":"He’s always bossing people around as if he’s so important.","id":"Dia selalu memerintah orang lain seolah-olah dia sangat penting."},{"jp":"大人ぶっているけど、まだ子供っぽいところがある。","romaji":"Otona butte iru kedo, mada kodomoppoi tokoro ga aru.","en":"He acts grown-up, but he still has some childish traits.","id":"Dia bertingkah dewasa, tapi dia masih memiliki beberapa sifat kekanak-kanakan."}]},{"pattern":"～ぶり (〜buri)","meaning":"Expresses the amount of time elapsed since doing something last.","meaningId":"Menyatakan jumlah waktu yang telah berlalu sejak melakukan sesuatu yang terakhir.","formation":"Time expression + ぶり","formationId":"Ekspresi waktu + ぶり","examples":[{"jp":"三年ぶりに彼に会いました。","romaji":"San-nen buri ni kare ni aimashita.","en":"I met him for the first time in three years.","id":"Saya bertemu dengannya untuk pertama kalinya dalam tiga tahun."},{"jp":"一週間ぶりにジムに行った。","romaji":"Isshuukan buri ni jimu ni itta.","en":"I went to the gym for the first time in a week.","id":"Saya pergi ke gym untuk pertama kalinya dalam seminggu."},{"jp":"一ヶ月ぶりに彼からの手紙が来た。","romaji":"Ikkagetsu buri ni kare kara no tegami ga kita.","en":"I received a letter from him for the first time in a month.","id":"Saya menerima surat darinya untuk pertama kalinya dalam sebulan."},{"jp":"五年ぶりに雪が降った。","romaji":"Go-nen buri ni yuki ga futta.","en":"It snowed for the first time in five years.","id":"Salju turun untuk pertama kalinya dalam lima tahun."}]},{"pattern":"～ぶる (〜buru)","meaning":"Used when someone is acting or pretending to be something they are not (often a negative connotation).","meaningId":"Digunakan ketika seseorang bertindak atau berpura-pura menjadi sesuatu yang bukan dirinya (seringkali berkonotasi negatif).","formation":"Noun / (Adjective stem) + ぶる","formationId":"Kata Benda / (Batang kata sifat) + ぶる","examples":[{"jp":"彼はあたかも知っているかのように学者ぶる。","romaji":"Kare wa atakamo shitteiru ka no you ni gakusha buru.","en":"He acts like a scholar, as if he knows everything.","id":"Dia bertindak seperti seorang sarjana, seolah-olah dia mengetahui segalanya."},{"jp":"女優ぶるのはやめて、自分自身でいろ。","romaji":"Joyu buru no wa yamete, jibun jishin de iro.","en":"Stop acting like you’re an actress and just be yourself.","id":"Berhentilah bertingkah seolah Anda seorang aktris dan jadilah diri sendiri."},{"jp":"彼女は常にお嬢様ぶっている。","romaji":"Kanojo wa tsune ni ojou-sama butte iru.","en":"She’s always putting on the airs of a refined lady.","id":"Dia selalu bersikap seperti wanita yang beradab."},{"jp":"私がいじめられていると無邪気ぶる彼女を見て、怒りがこみ上げた。","romaji":"Watashi ga ijimerarete iru to mujaki buru kanojo o mite, ikari ga komiageta.","en":"Seeing her act innocent while I was being bullied made my anger surge.","id":"Melihat dia bertingkah polos saat aku di-bully membuat amarahku melonjak."}]},{"pattern":"～までだ","meaning":"Expresses a limit or extent; 'it's only up to...', 'no more than...'.","meaningId":"Menyatakan batas atau luasnya; 'hanya sampai...', 'tidak lebih dari...'.","formation":"Verb (dictionary/ない form) + までだ, い-Adjective + までだ, Noun + までだ","formationId":"Kata Kerja (kamus/bentuk ない) + までだ, い-Kata Sifat + までだ, Kata Benda + までだ","examples":[{"jp":"彼とは友達までだ。それ以上の関係ではありません。","romaji":"Kare to wa tomodachi made da. Sore ijou no kankei dewa arimasen.","en":"With him, it's only friendship—nothing more.","id":"Baginya, yang ada hanyalah persahabatan—tidak lebih."},{"jp":"飲み放題は9時までだ。それ以降は追加料金が必要だ。","romaji":"Nomihoudai wa kuji made da. Sore ikou wa tsuika ryoukin ga hitsuyou da.","en":"The all-you-can-drink deal is only until nine. After that, there's an extra charge.","id":"Kesepakatan minuman sepuasnya hanya sampai jam sembilan. Setelah itu, ada biaya tambahan."},{"jp":"私たちの情報は昨日までだ。それ以降のアップデートはありません。","romaji":"Watashitachi no jouhou wa kinou made da. Sore ikou no appudeeto wa arimasen.","en":"Our information only goes up to yesterday; there are no further updates.","id":"Informasi kami hanya sampai kemarin; tidak ada pembaruan lebih lanjut."},{"jp":"彼の知識は中学生レベルまでだ。それ以上は理解できない。","romaji":"Kare no chishiki wa chuugakusei reberu made da. Sore ijou wa rikai dekinai.","en":"His knowledge is only at a junior-high level. He can't understand anything more advanced.","id":"Pengetahuannya hanya sebatas SMP. Dia tidak dapat memahami hal yang lebih maju."}]},{"pattern":"～もなんでもない (〜mo nandemonai)","meaning":"Used to dismiss or negate something’s importance; 'it’s nothing at all', 'it doesn’t matter'.","meaningId":"Digunakan untuk mengabaikan atau meniadakan pentingnya sesuatu; 'tidak apa-apa', 'tidak masalah'.","formation":"Verb-dictionary form + もなんでもない, い-Adjective + もなんでもない, な-Adjective + なもなんでもない, Noun + もなんでもない","formationId":"Bentuk kamus kata kerja + もなんでもない, い-Kata Sifat + もなんでもない, な-Kata Sifat + なもなんでもない, Kata Benda +もなんでもない","examples":[{"jp":"100万円を負けるもなんでもない。","romaji":"Hyaku man-en o makeru mo nandemonai.","en":"Losing a million yen is no big deal at all.","id":"Kehilangan satu juta yen bukanlah masalah besar sama sekali."},{"jp":"彼が社長だもなんでもない。","romaji":"Kare ga shachou da mo nandemonai.","en":"It doesn't matter one bit that he's the president.","id":"Tidak masalah sedikit pun bahwa dia adalah presiden."},{"jp":"あなたが来ないもなんでもない。","romaji":"Anata ga konai mo nandemonai.","en":"It doesn't matter at all if you don't come.","id":"Tidak masalah sama sekali jika Anda tidak datang."},{"jp":"それが美しいもなんでもない。","romaji":"Sore ga utsukushii mo nandemonai.","en":"It doesn't matter at all whether it's beautiful.","id":"Tidak masalah apakah itu indah atau tidak."}]},{"pattern":"～ものとして","meaning":"Indicates an assumption or supposition; 'assuming', 'under the assumption that'.","meaningId":"Menunjukkan asumsi atau anggapan; 'dengan asumsi', 'dengan asumsi itu'.","formation":"Verb-casual + ものとして, い-Adjective + ものとして, な-Adjective + なものとして, Noun + のものとして","formationId":"Kata Kerja-kasual + ものとして, い-Kata Sifat + ものとして, な-Kata Sifat + なものとして, Kata Benda + のものとして","examples":[{"jp":"雨が降るものとして、傘を持って行きました。","romaji":"Ame ga furu mono to shite, kasa o motte ikimashita.","en":"Assuming it would rain, I took an umbrella.","id":"Dengan asumsi akan turun hujan, saya membawa payung."},{"jp":"彼が病気なものとして、代わりに私が出席した。","romaji":"Kare ga byouki na mono to shite, kawari ni watashi ga shusseki shita.","en":"On the assumption that he was sick, I attended in his place.","id":"Dengan asumsi dia sakit, saya hadir menggantikannya."},{"jp":"このケーキが美味しいものとして、みんなに分けよう。","romaji":"Kono keeki ga oishii mono to shite, minna ni wakeyou.","en":"Let’s share this cake, assuming it’s delicious.","id":"Mari kita berbagi kue ini, dengan asumsi enak."},{"jp":"彼女が学生のものとして、学割を適用しました。","romaji":"Kanojo ga gakusei no mono to shite, gakuwari o tekiyou shimashita.","en":"Assuming she is a student, I applied the student discount.","id":"Dengan asumsi dia seorang pelajar, saya menerapkan diskon pelajar."}]},{"pattern":"～んがために (〜n ga tame ni)","meaning":"Emphasizes the reason or purpose for an action; 'in order to', 'for the sake of'.","meaningId":"Menekankan alasan atau tujuan suatu tindakan; 'untuk', 'demi'.","formation":"Verb-negative stem + んがために","formationId":"Batang kata kerja negatif + んがために","examples":[{"jp":"健康を保たんがために、毎日運動をしています。","romaji":"Kenkou o tamotan ga tame ni, mainichi undou o shite imasu.","en":"I exercise daily in order to maintain my health.","id":"Saya berolahraga setiap hari untuk menjaga kesehatan saya."},{"jp":"合格せんがために、一生懸命勉強します。","romaji":"Goukaku sen ga tame ni, isshoukenmei benkyou shimasu.","en":"I study hard in order to pass.","id":"Saya belajar keras agar bisa lulus."},{"jp":"明日の試験に備えんがため、今夜は早く寝るつもりです。","romaji":"Ashita no shiken ni sonaen ga tame, kon'ya wa hayaku neru tsumori desu.","en":"I plan to go to bed early so I can prepare for tomorrow’s exam.","id":"Saya berencana untuk tidur lebih awal agar saya dapat mempersiapkan ujian besok."},{"jp":"彼女の笑顔を見んがために、毎日会いに行きます。","romaji":"Kanojo no egao o min ga tame ni, mainichi ai ni ikimasu.","en":"I go to see her every day in order to see her smile.","id":"Saya pergi menemuinya setiap hari untuk melihat senyumnya."}]},{"pattern":"～んばかりに (〜n bakari ni)","meaning":"Indicates 'as though about to ~' or 'as if to say ~'.","meaningId":"Menunjukkan 'seolah-olah hendak ~' atau 'seolah-olah mengatakan ~'.","formation":"Verb-negative stem + ん + ばかりに","formationId":"Batang kata kerja negatif + ん + ばかりに","examples":[{"jp":"彼は何も知らんばかりに、私の質問を無視した。","romaji":"Kare wa nanimo shir-an bakari ni, watashi no shitsumon o mushi shita.","en":"He ignored my question as if he didn’t know anything.","id":"Dia mengabaikan pertanyaanku seolah dia tidak tahu apa-apa."},{"jp":"その子は泣かんばかりに顔をしかめた。","romaji":"Sono ko wa nakan bakari ni kao o shikameta.","en":"The child made a face as if he were about to cry.","id":"Anak itu memasang wajah seperti hendak menangis."},{"jp":"彼女は笑わんばかりに口元を押さえた。","romaji":"Kanojo wa warawan bakari ni kuchimoto o osaeta.","en":"She covered her mouth as though she were about to burst out laughing.","id":"Dia menutup mulutnya seolah dia akan tertawa terbahak-bahak."},{"jp":"彼は退屈だと言わんばかりに、ため息を何度もついた。","romaji":"Kare wa taikutsu da to iwan bakari ni, tameiki o nando mo tsuita.","en":"He sighed over and over as if to say he was bored.","id":"Dia menghela nafas berulang kali seolah mengatakan dia bosan."}]},{"pattern":"～差し支えない (〜sashitsukaenai)","meaning":"Indicates no problem or obstacle; 'it’s fine if...', 'there’s no issue'.","meaningId":"Menunjukkan tidak ada masalah atau hambatan; 'tidak apa-apa jika...', 'tidak ada masalah'.","formation":"Verb-て form + も差し支えない, Noun + が差し支えない","formationId":"Bentuk kata kerja-て + も差し支えない, Kata Benda + が差し支えない","examples":[{"jp":"多少遅くても差し支えないです。","romaji":"Tashou osokute mo sashitsukaenai desu.","en":"It’s no problem if you’re a bit late.","id":"Tidak masalah jika Anda sedikit terlambat."},{"jp":"部屋が少し汚くても差し支えない。","romaji":"Heya ga sukoshi kitanakute mo sashitsukaenai.","en":"It doesn’t matter if the room is slightly messy.","id":"Tidak masalah jika ruangannya sedikit berantakan."},{"jp":"雨が降っても差し支えない。","romaji":"Ame ga futte mo sashitsukaenai.","en":"It’s not an issue even if it rains.","id":"Itu tidak menjadi masalah meskipun hujan."},{"jp":"彼がここにいることが差し支えないですか？","romaji":"Kare ga koko ni iru koto ga sashitsukaenai desu ka?","en":"Is it okay (no problem) for him to be here?","id":"Bolehkah (tidak masalah) dia berada di sini?"}]},{"pattern":"～折に (〜ori ni)","meaning":"Indicates the time or occasion when something happens; 'when', 'at the time of'.","meaningId":"Menunjukkan waktu atau kejadian ketika sesuatu terjadi; 'kapan', 'pada saat'.","formation":"Verb-dictionary form + 折に, Verb-た形 + 折に, Noun + の折に","formationId":"Bentuk kamus kata kerja + 折に, Kata Kerja-た形 + 折に, Kata Benda + の折に","examples":[{"jp":"父が病気の折に、私は留学していました。","romaji":"Chichi ga byouki no ori ni, watashi wa ryuugaku shite imashita.","en":"When my father was ill, I was studying abroad.","id":"Ketika ayah saya sakit, saya belajar di luar negeri."},{"jp":"日本へ行く折に、お土産を買ってきてください。","romaji":"Nihon e iku ori ni, omiyage o katte kite kudasai.","en":"When you go to Japan, please buy souvenirs.","id":"Kalau ke Jepang, silakan beli oleh-oleh."},{"jp":"子供が寝ている折に、静かにしてください。","romaji":"Kodomo ga nete iru ori ni, shizuka ni shite kudasai.","en":"Please be quiet when the child is sleeping.","id":"Harap diam saat anak sedang tidur."},{"jp":"彼に会う折に、この手紙を渡してください。","romaji":"Kare ni au ori ni, kono tegami o watashite kudasai.","en":"Please give him this letter when you see him.","id":"Tolong berikan dia surat ini ketika Anda melihatnya."}]},{"pattern":"～極まりない (〜kiwamarinai)","meaning":"Expresses an extreme state, often negative; 'utterly', 'extremely', 'boundlessly'.","meaningId":"Mengekspresikan keadaan ekstrim, seringkali negatif; 'sama sekali', 'sangat', 'tanpa batas'.","formation":"な-Adjective（語幹）+ 極まりない, い-Adjective（連用形）+ こと + 極まりない, Noun + の極まりない","formationId":"な-Kata Sifat（語幹）+ 極まりない, い-Kata Sifat（連用形）+ こと + 極まりない, Kata Benda + の極まりない","examples":[{"jp":"彼の失礼な態度は極まりない。","romaji":"Kare no shitsurei na taido wa kiwamarinai.","en":"His rude attitude is utterly beyond words.","id":"Sikap kasarnya sungguh melampaui kata-kata."},{"jp":"その運転は危険極まりない。","romaji":"Sono unten wa kiken kiwamarinai.","en":"That driving is extremely dangerous.","id":"Mengemudi itu sangat berbahaya."},{"jp":"彼女のわがままぶりは非常識極まりない。","romaji":"Kanojo no wagamama-buri wa hijoushiki kiwamarinai.","en":"Her selfishness is utterly irrational.","id":"Keegoisannya sama sekali tidak rasional."},{"jp":"この部屋の汚さは不衛生極まりない。","romaji":"Kono heya no kitasa wa fueisei kiwamarinai.","en":"The filthiness of this room is extremely unsanitary.","id":"Kekotoran ruangan ini sangat tidak sehat."}]},{"pattern":"～極まる (〜kiwamaru)","meaning":"Also expresses an extreme degree or state, typically negative.","meaningId":"Juga menyatakan derajat atau keadaan ekstrem, biasanya negatif.","formation":"な-Adjective（語幹）+ 極まる, い-Adjective（連用形）+ こと + 極まる, etc.","formationId":"な-Kata Sifat（語幹）+ 極まる, い-Kata Sifat（連用形）+ こと + 極まる, dsb.","examples":[{"jp":"彼の言動は失礼極まる。","romaji":"Kare no gendou wa shitsurei kiwamaru.","en":"His words and actions are extremely rude.","id":"Kata-kata dan tindakannya sangat kasar."},{"jp":"その態度は非常識極まる。","romaji":"Sono taido wa hijoushiki kiwamaru.","en":"That behavior is utterly irrational.","id":"Perilaku itu sungguh tidak rasional."},{"jp":"彼女の発言は無責任極まる。","romaji":"Kanojo no hatsugen wa musekinin kiwamaru.","en":"Her remark is extremely irresponsible.","id":"Ucapannya sangat tidak bertanggung jawab."},{"jp":"このような誤解は遺憾極まる。","romaji":"Kono youna gokai wa ikan kiwamaru.","en":"Such a misunderstanding is exceedingly regrettable.","id":"Kesalahpahaman seperti ini sangat disayangkan."}]},{"pattern":"～足りない","meaning":"Expresses insufficiency or lack; 'not enough', 'insufficient'.","meaningId":"Menyatakan kekurangan atau kekurangan; 'tidak cukup', 'tidak cukup'.","formation":"Noun + (が) 足りない, Verb-casual + ほど/だけ + (が) 足りない","formationId":"Kata Benda + (が) 足りない, Kata kerja kasual + ほど/だけ + (が) 足りない","examples":[{"jp":"私の日本語の能力はまだまだ足りない。","romaji":"Watashi no nihongo no nouryoku wa madamada tarinai.","en":"My Japanese skills are still not enough.","id":"Kemampuan bahasa Jepang saya masih belum cukup."},{"jp":"時間が足りないから、今すぐ行かなきゃ。","romaji":"Jikan ga tarinai kara, ima sugu ikanakya.","en":"We don't have enough time, so we must go right now.","id":"Kita tidak punya cukup waktu, jadi kita harus pergi sekarang."},{"jp":"彼の説明には詳細が足りない。","romaji":"Kare no setsumei ni wa shousai ga tarinai.","en":"His explanation lacks detail.","id":"Penjelasannya kurang detail."},{"jp":"料理するための食材が足りない。","romaji":"Ryouri suru tame no shokuzai ga tarinai.","en":"There's not enough food to cook with.","id":"Tidak ada cukup makanan untuk dimasak."}]},{"pattern":"～足る Noun (〜taru Noun)","meaning":"Indicates that something is worthy or sufficient to be called/used as ~; 'worthy of', 'enough to ~'.","meaningId":"Menandakan sesuatu itu layak atau cukup untuk disebut/digunakan sebagai ~; 'layak untuk', 'cukup untuk ~'.","formation":"Noun/Verb-dictionary form + に足る + Noun","formationId":"Bentuk kamus Kata Benda/Kata Kerja + に足る + Kata Benda","examples":[{"jp":"彼は信頼に足る人物だ。","romaji":"Kare wa shinrai ni taru jinbutsu da.","en":"He is a person worthy of trust.","id":"Dia adalah orang yang layak dipercaya."},{"jp":"この小説は読むに足る価値がある。","romaji":"Kono shousetsu wa yomu ni taru kachi ga aru.","en":"This novel is well worth reading.","id":"Novel ini sangat layak untuk dibaca."},{"jp":"検討に足るデータが十分に集まった。","romaji":"Kentou ni taru deeta ga juubun ni atsumatta.","en":"We've gathered enough data to be worth examining.","id":"Kami telah mengumpulkan cukup data untuk diperiksa."},{"jp":"彼の説明は信用に足るものだと思う。","romaji":"Kare no setsumei wa shinyou ni taru mono da to omou.","en":"I think his explanation is worthy of trust.","id":"Saya pikir penjelasannya layak dipercaya."}]},{"pattern":"～限りだ (〜kagiri da)","meaning":"Expresses an extreme degree of emotion or reaction; 'I feel so ~', 'as ~ as can be'.","meaningId":"Mengekspresikan emosi atau reaksi tingkat ekstrim; 'Aku merasa begitu ~', 'sebisa mungkin'.","formation":"い-Adjective + 限りだ, な-Adjective + な/である + 限りだ, Noun + の + 限りだ","formationId":"い-Kata Sifat + 限りだ, な-Kata Sifat + な/である + 限りだ, Kata Benda + の + 限りだ","examples":[{"jp":"彼女が急に辞めてしまった。驚きの限りだ。","romaji":"Kanojo ga kyuu ni yamete shimatta. Odoroki no kagiri da.","en":"She suddenly quit. I'm as shocked as can be.","id":"Dia tiba-tiba berhenti. Saya sangat terkejut."},{"jp":"息子が成功した。嬉しい限りだ。","romaji":"Musuko ga seikou shita. Ureshii kagiri da.","en":"My son succeeded. I'm so happy.","id":"Anakku berhasil. Saya sangat senang."},{"jp":"こんなに綺麗な花が見られるなんて、幸せの限りだ。","romaji":"Konna ni kirei na hana ga mirareru nante, shiawase no kagiri da.","en":"I'm as happy as can be to see such beautiful flowers.","id":"Saya sangat bahagia melihat bunga-bunga indah seperti itu."},{"jp":"試験に合格できて、ほっとした限りだ。","romaji":"Shiken ni goukaku dekite, hotto shita kagiri da.","en":"I passed the exam—what a relief!","id":"Saya lulus ujian—sungguh melegakan!"}]}]
